interface TreeSkill {
  sys: string;
  name: string;
  icon?: string;
  no: string[];
  skills: string[];
  uniqs: string[];
}

interface Way {
  find: string;
  cost: number;
  plus?: string | string[];
  ignore?: string[];
}

interface FractionWheel {
  name: string;
  nameS?: string;
  fraction: string;
  num: number;
  klass: number | false;
  ways: Way[];
  skills: Record<string, string | string[]>;
}

interface HeroSkillDesc {
  name: string;
  img?: string;
  desc: string;
}

/**
 * В исходных PNG перков нарисована своя жёлтая рамка — примерно 8.5% ширины с
 * каждой стороны (9px из 120 у `i/perks/2x*.png`, 5px из 60 у
 * `help/img/skills/*`). Рамку не показываем: картинка берётся крупнее
 * (PERK_ICON_ZOOM) и обрезается по окну нужного размера.
 *
 * Иконки узлов большого колеса приходят из атласа `skillwheelIcons` — там они
 * уже без рамки, и обрезка им не нужна. Константы работают на остальных путях:
 * мини-колёса фракций, панель описания, таблица навыков, список набора и те 15
 * навыков, которых в атласе нет и которые падают на парадный PNG.
 */
export const PERK_ICON_INSET = 0.085;
export const PERK_ICON_ZOOM = 1 / (1 - 2 * PERK_ICON_INSET);

