/** Палитра секторов из оригинала (maincolors в skillwheel.js). */
export const SW_BRANCH_COLORS: Record<string, string> = {
  attacks:'#FF7575', defs:'#CCCCFF', sorceries:'#8FB4FF', shout:'#8FB4FF',
  mlight:'#FFE478', mdark:'#FF99FF', mhaos:'#FFCCB2', msummon:'#B6FF6F',
  lucks:'#FFFF85', leads:'#ABD94E', logistics:'#DEB054', books:'#B2B2B2'
};

export const SW_BRANCH_ORDER: string[] = ['attacks','defs','sorceries','books','leads','lucks','mlight','mdark','msummon','mhaos','shout','logistics','uniq','uniqTime'];

export function swGetWheelsForFaction(fractionKey: string): FractionWheel[] {
  return Object.keys(TREE_SKILLS_FRACTION).filter(function(k) {
    return TREE_SKILLS_FRACTION[k].fraction === fractionKey;
  }).map(function(k) { return TREE_SKILLS_FRACTION[k]; });
}

/**
 * Путь текущего колеса: `/skillwheels/<фракция>[/<класс>]`.
 *
 * Номер класса пишем только там, где колёс у фракции больше одного, — иначе в
 * адресе болтался бы бессмысленный ноль.
 */
export function swRoutePath(): string {
  var sel = document.getElementById('sw-faction') as HTMLSelectElement | null;
  var f = sel ? sel.value : '';
  if (!f) return '/skillwheels';
  var wheels = swGetWheelsForFaction(f);
  if (wheels.length > 1) {
    var classSel = document.getElementById('sw-class') as HTMLSelectElement | null;
    var idx = classSel ? (parseInt(classSel.value, 10) || 0) : 0;
    return '/skillwheels/' + f + '/' + idx;
  }
  return '/skillwheels/' + f;
}

/** Отразить выбранное колесо в адресной строке. */
function swSyncUrl(): void {
  // Только когда мы действительно на вкладке колёс: swInit зовётся и из
  // маршрутизатора, и переписать чужой адрес было бы хуже, чем не писать свой.
  if (typeof location === 'undefined' || appPath().indexOf('/skillwheels') !== 0) return;
  var path = swRoutePath();
  if (appPath() === path) return;
  // replaceState, а не push: выбор во выпадающем списке — не отдельный шаг
  // истории, иначе «Назад» пришлось бы жать по разу на каждое переключение.
  try { history.replaceState(null, '', siteUrl(path)); } catch (e) { /* about:blank и т.п. */ }
}

export function swInit(faction?: string, classIdx?: number): void {
  var sel = document.getElementById('sw-faction') as HTMLSelectElement;
  sel.innerHTML = '';
  PLAYABLE.forEach(function(f) {
    var meta = FACTIONS_META[f];
    if (meta) {
      var opt = document.createElement('option');
      opt.value = f;
      opt.textContent = meta.nameRu;
      sel.appendChild(opt);
    }
  });
  var neutWithWheels = ['pirates','winter'];
  neutWithWheels.forEach(function(f) {
    var meta = FACTIONS_META[f];
    if (meta) {
      var opt = document.createElement('option');
      opt.value = f;
      opt.textContent = meta.nameRu + ' (нейтр.)';
      sel.appendChild(opt);
    }
  });
  // Фракция из адреса, если она вообще есть в списке; иначе — рыцари.
  var wanted = faction && swGetWheelsForFaction(faction).length ? faction : 'knight';
  sel.value = wanted;
  [0, 1].forEach(function(i) {
    var b = document.getElementById('sw-slot-' + i);
    if (b) b.classList.toggle('active', i === swHeroSlot);
  });
  swOnFactionChange(classIdx);
}

export function swOnFactionChange(classIdx?: number): void {
  var f = (document.getElementById('sw-faction') as HTMLSelectElement).value;
  var wheels = swGetWheelsForFaction(f);
  var classGroup = document.getElementById('sw-class-group') as HTMLElement;
  var classSel = document.getElementById('sw-class') as HTMLSelectElement;
  if (wheels.length > 1) {
    classGroup.style.display = '';
    classSel.innerHTML = '';
    wheels.forEach(function(w, i) {
      var opt = document.createElement('option');
      opt.value = String(i);
      opt.textContent = w.nameS || w.name;
      classSel.appendChild(opt);
    });
    var idx = typeof classIdx === 'number' && classIdx >= 0 && classIdx < wheels.length
      ? classIdx : 0;
    classSel.value = String(idx);
  } else {
    classGroup.style.display = 'none';
  }
  swRenderWheel();
}


interface WheelNode {
  key: string;
  name: string;
}

interface Branch {
  sys: string;
  name: string;
  cost: number;
  /** Префикс уровневых навыков ветки: 'attack' для attack1/2/3. */
  prefix: string;
  /** Три «уровневые» способности ветки (attack1/2/3) — внешнее кольцо. */
  levels: WheelNode[];
  /** Перки по кольцам: rings[0] требует <ветка>1, rings[1] — <ветка>2, и т.д. */
  rings: WheelNode[][];
}

/**
 * Разобранное колесо: всё, что нужно и для отрисовки, и для правил набора.
 * Правила один в один из игрового skillwheel.js (calcpossible / onRelease).
 */
interface WheelModel {
  key: string;
  faction: string;
  wheel: FractionWheel;
  branches: Branch[];
  uniqKey: string | null;
  /** Стоимость навыка в очках = стоимость его ветки (way.cost). */
  cost: Record<string, number>;
  /** Первое требование: '<ветка><уровень>' либо '' у уровневых и классового. */
  need1: Record<string, string>;
  /** Остальные требования (need2..need4) — все обязательны. */
  needs: Record<string, string[]>;
  branchOf: Record<string, Branch>;
}

var swModel: WheelModel | null = null;
/** Выбранные навыки в порядке набора — как curperks в оригинале. */
var swPicked: string[] = [];

/** Ключи в localStorage: набор переживает переход на вкладку боя и перезагрузку. Наборов два —
 *  по одному на героя боя: Герой 1 (свой) и Герой 2 (справа). */
const SW_BUILD_KEYS = ['hwm-skillwheel-build', 'hwm-skillwheel-build-2'];
/** Чей набор собирается на открытой вкладке колеса: 0 — Герой 1, 1 — Герой 2. */
export var swHeroSlot = 0;

interface SavedBuild { faction: string; wheel: string; picked: string[]; }

function swLoadSaved(slot: number = swHeroSlot): SavedBuild | null {
  try {
    const raw = localStorage.getItem(SW_BUILD_KEYS[slot]);
    if (!raw) return null;
    const v = JSON.parse(raw);
    if (!v || typeof v.wheel !== 'string' || !Array.isArray(v.picked)) return null;
    return { faction: String(v.faction || ''), wheel: v.wheel, picked: v.picked.map(String) };
  } catch (e) { return null; }
}

function swSaveBuild(): void {
  if (!swModel) return;
  try {
    localStorage.setItem(SW_BUILD_KEYS[swHeroSlot], JSON.stringify({
      faction: swModel.faction, wheel: swModel.key, picked: swPicked,
    }));
  } catch (e) { /* приватный режим — набор просто не переживёт перезагрузку */ }
}

/**
 * Набор для боя. Отдаётся и из открытой вкладки колеса, и из сохранённого:
 * вкладку боя можно открыть, ни разу не зайдя на колесо.
 */
export function swGetBattleBuild(slot: number = 0): { faction: string; wheel: string; perks: string[] } | null {
  if (swModel && swPicked.length && swHeroSlot === slot) {
    return { faction: swModel.faction, wheel: swModel.key, perks: swPicked.slice() };
  }
  const saved = swLoadSaved(slot);
  if (saved && saved.picked.length) {
    return { faction: saved.faction, wheel: saved.wheel, perks: saved.picked.slice() };
  }
  return null;
}

/** Переключить, чей набор собирается на колесе (0 — Герой 1, 1 — Герой 2): колесо и набор
 *  открываются сохранёнными для этого героя, чужой набор остаётся в своём ключе. */
export function swSetHeroSlot(slot: number): void {
  swHeroSlot = slot === 1 ? 1 : 0;
  [0, 1].forEach(function(i) {
    var b = document.getElementById('sw-slot-' + i);
    if (b) b.classList.toggle('active', i === swHeroSlot);
  });
  var sel = document.getElementById('sw-faction') as HTMLSelectElement | null;
  if (!sel || !sel.options.length) return;       // вкладка колеса ещё не построена — swInit возьмёт слот сам
  var saved = swLoadSaved(swHeroSlot);
  if (saved && saved.faction && Array.prototype.some.call(sel.options, function(o: HTMLOptionElement) { return o.value === saved!.faction; })) {
    sel.value = saved.faction;
    var wheels = swGetWheelsForFaction(saved.faction), idx = 0;
    wheels.forEach(function(w, i) { if (saved!.faction + '_' + (w.klass === false ? 'n' : w.klass) === saved!.wheel) idx = i; });
    swOnFactionChange(idx);
  } else {
    swRenderWheel();
  }
}

function swPrefixOf(need: string): string { return need.slice(0, -1); }

/** Сколько перков ветки уже набрано (уровневые не в счёт) — needcounter. */
function swBranchPicked(prefix: string): number {
  var m = swModel;
  if (!m) return 0;
  var n = 0;
  swPicked.forEach(function(p) {
    var n1 = m!.need1[p];
    if (n1 && swPrefixOf(n1) === prefix) n++;
  });
  return n;
}

/**
 * Можно ли выучить навык. Формула оригинала: k-й перк ветки требует уровень
 * max(собственный уровень, k), и больше трёх перков в ветку не влезает.
 */
export function swCanLearn(key: string): boolean {
  var m = swModel;
  if (!m || swPicked.indexOf(key) !== -1) return false;
  // Навык не с этого колеса выучить нельзя. Без проверки он проходил насквозь:
  // требований у него нет (`need1` не задан), и «Образование» попадало в набор
  // рыцаря — со стоимостью undefined в панели.
  if (m.cost[key] === undefined) return false;
  var extra = m.needs[key] || [];
  for (var i = 0; i < extra.length; i++) {
    if (swPicked.indexOf(extra[i]) === -1) return false;
  }
  var n1 = m.need1[key];
  if (!n1) return true;
  var prefix = swPrefixOf(n1);
  var t = parseInt(n1.slice(-1), 10);
  var learned = swBranchPicked(prefix);
  var c = t + Math.max(0, learned - (t - 1));
  if (c > 3) return false;
  return swPicked.indexOf(prefix + c) !== -1;
}

/** Забыть навык можно, пока на него никто из набранных не опирается. */
export function swCanForget(key: string): boolean {
  var m = swModel;
  if (!m || swPicked.indexOf(key) === -1) return false;
  for (var i = 0; i < swPicked.length; i++) {
    var p = swPicked[i];
    if (p === key) continue;
    if (m.need1[p] === key) return false;
    if ((m.needs[p] || []).indexOf(key) !== -1) return false;
  }
  return true;
}

/** Текущий набор (копия) — для тестов и внешних потребителей. */
export function swGetBuild(): string[] { return swPicked.slice(); }

export function swBuildCost(): number {
  var m = swModel;
  if (!m) return 0;
  return swPicked.reduce(function(s, k) { return s + (m!.cost[k] || 0); }, 0);
}

/** Формула игры: очки = 5 × (уровень − 3), навыки открыты с 5-го уровня. */
export function swPointsToLevel(points: number): number {
  if (!(points > 0)) points = 0;
  return Math.max(5, Math.ceil(points / 5) + 3);
}

export function swToggleSkill(key: string): void {
  if (!swModel) return;
  if (swPicked.indexOf(key) === -1) {
    if (!swCanLearn(key)) return;
    swPicked.push(key);
  } else {
    if (!swCanForget(key)) return;
    swPicked.splice(swPicked.indexOf(key), 1);
  }
  swSaveBuild();
  swPaintWheel();
  swShowSkill(key, swModel.key);
}

export function swResetBuild(): void {
  swPicked = [];
  swSaveBuild();
  swPaintWheel();
}

function swBuildModel(wheel: FractionWheel, faction: string): WheelModel {
  var m: WheelModel = {
    key: faction + '_' + (wheel.klass === false ? 'n' : wheel.klass),
    faction: faction,
    wheel: wheel,
    branches: [],
    uniqKey: null,
    cost: {},
    need1: {},
    needs: {},
    branchOf: {}
  };

  wheel.ways.forEach(function(way) {
    var treeSkill = TREE_SKILLS[way.find];
    if (!treeSkill) return;
    var plusArr: string[] = typeof way.plus === 'string' ? [way.plus] : (way.plus || []);

    if (way.find === 'uniq') {
      plusArr.forEach(function(p) {
        if (p && treeSkill.uniqs.indexOf(p) !== -1) {
          m.uniqKey = p;
          m.cost[p] = way.cost;
          m.need1[p] = '';
          m.needs[p] = [];
        }
      });
      return;
    }
    // «Недоступные навыки» — служебная ветка, на колесе её нет.
    if (way.find === 'uniqTime') return;

    var prefix = treeSkill.no.length ? treeSkill.no[0].slice(0, -1) : way.find;
    var levels: WheelNode[] = [];
    var rings: WheelNode[][] = [[], [], []];
    var branch: Branch = {
      sys: way.find, name: treeSkill.name, cost: way.cost,
      prefix: prefix, levels: levels, rings: rings
    };

    var addSkill = function(key: string) {
      if (way.ignore && way.ignore.indexOf(key) !== -1) return;
      var d = HERO_SKILL_DESCS[key];
      var node: WheelNode = { key: key, name: d ? d.name : key };
      m.cost[key] = way.cost;
      m.branchOf[key] = branch;

      var lvl = treeSkill.no.indexOf(key);
      if (lvl !== -1) {
        // Уровневые навыки требований в данных не имеют: как в оригинале,
        // «развитая» тянет «обычную», «искусная» — «развитую».
        m.need1[key] = '';
        m.needs[key] = lvl > 0 ? [treeSkill.no[lvl - 1]] : [];
        levels[lvl] = node;
        return;
      }
      var prereq = wheel.skills[key];
      var reqArr = typeof prereq === 'string' ? [prereq] : (Array.isArray(prereq) ? prereq.slice() : []);
      var first = reqArr.length ? reqArr[0] : '';
      if (first === 'none') first = '';
      m.need1[key] = first;
      m.needs[key] = reqArr.slice(1).filter(function(r) { return !!r && r !== 'none'; });
      // Кольцо перка задаёт первое требование: attack1 → 1-е кольцо и т.д.
      var digit = /(\d)$/.exec(first || '');
      var tier = digit ? parseInt(digit[1], 10) : 1;
      if (!(tier >= 1 && tier <= 3)) tier = 1;
      rings[tier - 1].push(node);
    };
    treeSkill.skills.forEach(addSkill);
    treeSkill.uniqs.forEach(function(u) {
      if (plusArr.indexOf(u) !== -1) addSkill(u);
    });

    branch.levels = levels.filter(Boolean);
    m.branches.push(branch);
  });

  return m;
}

export function swRenderWheel(): void {
  var f = (document.getElementById('sw-faction') as HTMLSelectElement).value;
  var wheels = swGetWheelsForFaction(f);
  if (!wheels.length) {
    (document.getElementById('skillwheel-error') as HTMLElement).style.display = 'block';
    (document.getElementById('skillwheel-error') as HTMLElement).textContent = 'Для этой фракции нет данных о колесе навыков';
    (document.getElementById('skillwheel-visual') as HTMLElement).innerHTML = '';
    swModel = null;
    swPicked = [];
    var sideEl = document.getElementById('sw-build');
    if (sideEl) sideEl.innerHTML = '';
    var tableEl = document.getElementById('skillwheel-table');
    if (tableEl) tableEl.innerHTML = '';
    (document.querySelector('#skillwheel-detail #sw-detail-content') as HTMLElement).style.display = 'none';
    (document.querySelector('#skillwheel-detail #sw-detail-empty') as HTMLElement).style.display = '';
    return;
  }
  (document.getElementById('skillwheel-error') as HTMLElement).style.display = 'none';
  var idx = 0;
  if (wheels.length > 1) {
    idx = parseInt((document.getElementById('sw-class') as HTMLSelectElement).value) || 0;
  }
  var wheel = wheels[idx];

  var detail = document.getElementById('skillwheel-detail') as HTMLElement;
  (detail.querySelector('#sw-detail-content') as HTMLElement).style.display = 'none';
  (detail.querySelector('#sw-detail-empty') as HTMLElement).style.display = '';

  // Смена колеса обнуляет набор — очки и уровень считаются для текущего класса.
  // Набор ТОГО ЖЕ колеса восстанавливается: иначе уход на вкладку боя и
  // обратно стирал бы собранный билд.
  swModel = swBuildModel(wheel, f);
  swPicked = [];
  const saved = swLoadSaved();
  if (saved && saved.wheel === swModel.key) {
    // Проигрываем сохранённый порядок через те же правила: данные колеса могли
    // измениться, и невалидный навык не должен попасть в набор молча.
    saved.picked.forEach(function(k) { if (swCanLearn(k)) swPicked.push(k); });
  }
  swPaintWheel();

  swSyncUrl();
}

/** Перерисовка колеса, панели набора и таблицы под текущий выбор. */
export function swPaintWheel(): void {
  var m = swModel;
  var visual = document.getElementById('skillwheel-visual') as HTMLElement;
  if (!m || !visual) return;
  var branches = m.branches;
  var uniqKey = m.uniqKey;

  // ── Геометрия ──────────────────────────────────────────────────────────
  // Пропорции взяты из оригинального skillwheel.js: при radius = 262
  // шаги колец 25 / 50 / 50 / 50, иконка 36, центральная втулка 62.
  var svgW = 700, svgH = 700, cx = 350, cy = 350, R = 310;
  var UNIT = R / 262;
  var STEP1 = 25 * UNIT, STEP = 50 * UNIT;
  // Границы четырёх цветных полос сектора (снаружи внутрь).
  var bandEdges = [R, R - (STEP1 + STEP / 2), R - (STEP1 + 1.5 * STEP), R - (STEP1 + 2.5 * STEP), R - (STEP1 + 3.5 * STEP)];
  var hubR = bandEdges[4];
  // Радиусы колец с иконками: внешнее — уровни ветки, дальше перки 1/2/3.
  var ringR = [R - STEP1, R - STEP1 - STEP, R - STEP1 - 2 * STEP, R - STEP1 - 3 * STEP];
  var ICON = 34 * UNIT;

  var nums = branches.length || 1;

  function ang(i: number, off: number): number {
    return Math.PI / 2 + 2 * Math.PI * (i + off) / nums;
  }
  function px(r: number, a: number): string { return (cx + r * Math.cos(a)).toFixed(2); }
  function py(r: number, a: number): string { return (cy - r * Math.sin(a)).toFixed(2); }
  // Дуга рисуется против часовой на экране (y перевёрнут) → sweep = 0.
  function wedge(i: number, rOut: number, rIn: number): string {
    var a1 = ang(i, 0), a2 = ang(i, 1);
    var large = (2 * Math.PI / nums) > Math.PI ? 1 : 0;
    return 'M ' + px(rOut,a1) + ',' + py(rOut,a1) +
      ' A ' + rOut.toFixed(2) + ' ' + rOut.toFixed(2) + ' 0 ' + large + ' 0 ' + px(rOut,a2) + ',' + py(rOut,a2) +
      ' L ' + px(rIn,a2) + ',' + py(rIn,a2) +
      ' A ' + rIn.toFixed(2) + ' ' + rIn.toFixed(2) + ' 0 ' + large + ' 1 ' + px(rIn,a1) + ',' + py(rIn,a1) + ' Z';
  }

  var html = '<svg class="sw-wheel-svg" viewBox="0 0 ' + svgW + ' ' + svgH + '" preserveAspectRatio="xMidYMid meet" xmlns="http://www.w3.org/2000/svg">';
  html += '<defs><marker id="sw-arrow" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0,0 L8,4 L0,8 z" fill="#3a3a3a"/></marker></defs>';

  // Фон-диск: у оригинала колесо светлое, иконки нарисованы под светлый фон.
  html += '<circle cx="' + cx + '" cy="' + cy + '" r="' + R.toFixed(2) + '" class="sw-wheel-disc"/>';

  // ── Полосы секторов ────────────────────────────────────────────────────
  var bandAlpha = [0.25, 0.5, 0.75, 1];
  branches.forEach(function(branch, bi) {
    var color = SW_BRANCH_COLORS[branch.sys] || '#CCCCCC';
    html += '<g class="sw-branch-sector" data-branch="' + branch.sys + '">';
    for (var c = 0; c < 4; c++) {
      html += '<path d="' + wedge(bi, bandEdges[c], bandEdges[c + 1]) + '" fill="' + color +
        '" fill-opacity="' + bandAlpha[c] + '" stroke="#000" stroke-opacity="0.18" stroke-width="1"/>';
    }
    html += '</g>';
  });

  // ── Раскладка иконок ───────────────────────────────────────────────────
  interface Placed { key: string; name: string; x: number; y: number; size: number; }
  var placed: Placed[] = [];
  var posByKey: Record<string, Placed> = {};
  function place(nodes: WheelNode[], bi: number, r: number, size: number): void {
    var z = nodes.length;
    if (!z) return;
    nodes.forEach(function(n, k0) {
      // Оригинал: a = 2π(i + (z + 0.5 − k)/z)/nums + π/2, k = 1..z.
      var a = ang(bi, (z + 0.5 - (k0 + 1)) / z);
      var p: Placed = {
        key: n.key, name: n.name,
        x: cx + r * Math.cos(a), y: cy - r * Math.sin(a),
        size: size
      };
      placed.push(p);
      posByKey[n.key] = p;
    });
  }
  branches.forEach(function(branch, bi) {
    place(branch.levels, bi, ringR[0], ICON);
    for (var c = 1; c <= 3; c++) {
      // Как в оригинале, иконки мельчают к центру: _xscale = 1 − c*0.1.
      place(branch.rings[c - 1], bi, ringR[c], ICON * (1 - c * 0.1));
    }
  });
  // Классовый навык рисуется отдельно, во втулке, но в раскладке он ОБЯЗАН
  // быть: на него ссылаются перки веток («Павший рыцарь» требует «Метку
  // рыцаря»), и без его координат такие связи молча не рисовались — часть
  // стрелок с колеса просто пропадала.
  if (uniqKey) {
    posByKey[uniqKey] = { key: uniqKey, name: uniqKey, x: cx, y: cy - 6, size: ICON };
  }

  // ── Связи «требуется» ──────────────────────────────────────────────────
  // Стрелками показаны ВТОРОЕ и дальше требования (need2..need4), первое — нет:
  // его выражает само положение узла, перк лежит в кольце своего уровня, и
  // линия туда была бы повтором. Так рисует оригинал (skillwheel.js, dotway).
  //
  // Оговорка оттуда же: у второго требования линия рисуется, только если у
  // навыка ЕСТЬ первое (или это классовый навык). Иначе стрелка появилась бы
  // между ступенями ветки — «Развитое нападение» ← «Нападение», — а их связь
  // и так очевидна из соседства в кольце.
  function swDrawNeeds(key: string): void {
    var to = posByKey[key];
    if (!to) return;
    var extra = m!.needs[key] || [];
    extra.forEach(function(req, i) {
      if (!req) return;
      if (i === 0 && !m!.need1[key] && key !== uniqKey) return;
      var from = posByKey[req];
      if (!from) return;
      var live = swPicked.indexOf(req) !== -1 && swPicked.indexOf(key) !== -1;
      html += '<line x1="' + from.x.toFixed(2) + '" y1="' + from.y.toFixed(2) +
        '" x2="' + to.x.toFixed(2) + '" y2="' + to.y.toFixed(2) +
        '" class="sw-connector' + (live ? ' active' : '') + '" marker-end="url(#sw-arrow)"/>';
    });
  }
  branches.forEach(function(branch) {
    branch.levels.forEach(function(n) { swDrawNeeds(n.key); });
    branch.rings.forEach(function(ring) {
      ring.forEach(function(n) { swDrawNeeds(n.key); });
    });
  });
  if (uniqKey) swDrawNeeds(uniqKey);

  // ── Иконки ─────────────────────────────────────────────────────────────
  placed.forEach(function(p) {
    var d = HERO_SKILL_DESCS[p.key];
    var state = swSkillState(p.key);
    var tip = p.name + ' — ' + m!.cost[p.key] + ' очк.' + (d && d.desc ? '\n' + d.desc.replace(/<[^>]+>/g, '') : '');
    html += '<g class="sw-skill-node sw-' + state + '" data-skill="' + p.key + '"' +
      ' onclick="swToggleSkill(\'' + p.key + '\')" onmouseover="swShowSkill(\'' + p.key + '\',\'' + m!.key + '\')">';
    html += '<title>' + tip.replace(/&/g, '&amp;').replace(/</g, '&lt;') + '</title>';
    html += '<rect x="' + (p.x - p.size / 2 - 2).toFixed(2) + '" y="' + (p.y - p.size / 2 - 2).toFixed(2) +
      '" width="' + (p.size + 4).toFixed(2) + '" height="' + (p.size + 4).toFixed(2) + '" rx="4" class="sw-skill-node-bg"/>';
    html += swIconMarkup(p.key, p.x, p.y, p.size);
    html += '</g>';
  });

  // ── Подписи веток по внешней дуге ──────────────────────────────────────
  // Текст в верхней половине идёт по часовой, в нижней — против, чтобы
  // буквы всегда стояли «головой наружу».
  var LBL = 12;
  branches.forEach(function(branch, bi) {
    var mid = ang(bi, 0.5);
    var down = Math.sin(mid) < 0;
    var lr = R + 5 + (down ? LBL : 0);
    var a1 = ang(bi, 0.04), a2 = ang(bi, 0.96);
    var s = down ? a1 : a2, e = down ? a2 : a1;
    var sweep = down ? 0 : 1;
    var pid = 'swlbl-' + bi;
    html += '<path id="' + pid + '" fill="none" d="M ' + px(lr,s) + ',' + py(lr,s) +
      ' A ' + lr.toFixed(2) + ' ' + lr.toFixed(2) + ' 0 0 ' + sweep + ' ' + px(lr,e) + ',' + py(lr,e) + '"/>';
    html += '<text class="sw-branch-label" font-size="' + LBL + '"><textPath href="#' + pid +
      '" startOffset="50%" text-anchor="middle">' + branch.name + ' · ' + branch.cost + ' очк.</textPath></text>';
  });

  html += '<circle cx="' + cx + '" cy="' + cy + '" r="' + R.toFixed(2) + '" class="sw-wheel-rim"/>';

  // ── Центр: уникальный навык класса ─────────────────────────────────────
  html += '<circle cx="' + cx + '" cy="' + cy + '" r="' + hubR.toFixed(2) + '" class="sw-wheel-hub"/>';
  if (uniqKey) {
    var udesc = HERO_SKILL_DESCS[uniqKey];
    var uName = udesc ? udesc.name : uniqKey;
    var utip = uName + ' — ' + m.cost[uniqKey] + ' очк.' + (udesc && udesc.desc ? '\n' + udesc.desc.replace(/<[^>]+>/g, '') : '');
    html += '<g class="sw-skill-node sw-center-skill sw-' + swSkillState(uniqKey) + '" data-skill="' + uniqKey + '"' +
      ' onclick="swToggleSkill(\'' + uniqKey + '\')" onmouseover="swShowSkill(\'' + uniqKey + '\',\'' + m.key + '\')">';
    html += '<title>' + utip.replace(/&/g, '&amp;').replace(/</g, '&lt;') + '</title>';
    html += '<rect x="' + (cx - ICON / 2 - 2).toFixed(2) + '" y="' + (cy - ICON / 2 - 8).toFixed(2) +
      '" width="' + (ICON + 4).toFixed(2) + '" height="' + (ICON + 4).toFixed(2) + '" rx="4" class="sw-skill-node-bg"/>';
    html += swIconMarkup(uniqKey, cx, cy - 6, ICON);
    html += '<text x="' + cx + '" y="' + (cy + ICON / 2 + 8).toFixed(2) + '" class="sw-center-text" font-size="11">' + uName + '</text>';
    html += '</g>';
  }

  html += '</svg>';
  visual.innerHTML = html;

  swRenderBuildPanel();
  swRenderSkillTable();
}

/**
 * Иконка навыка размером `size` с центром в (x, y).
 *
 * Берётся из атласа колеса — иконки там без рамки и без подложки, как в
 * оригинале. Вложенный `<svg>` со своим viewBox сам обрезает атлас до нужного
 * кадра, поэтому обходимся без clipPath и уникальных id на каждый узел.
 * Навыка нет в атласе — падаем на парадную иконку из справочника: лучше
 * иконка в рамке, чем пустое место.
 */
function swIconMarkup(key: string, x: number, y: number, size: number): string {
  var f = SW_ICON_RECTS[key];
  if (f) {
    var sx = f[0], sy = f[1], w = f[2], h = f[3];
    var a = f[4], b = f[5], c = f[6], d = f[7];
    var ax = f[8], ay = f[9], bw = f[10], bh = f[11], bcx = f[12], bcy = f[13];
    // Вписываем ПОВЁРНУТЫЙ габарит: иначе наклонная иконка вылезала бы за узел.
    var k = size / Math.max(bw, bh);
    var tx = x - k * bcx, ty = y - k * bcy;
    // Порядок как у движка: сдвиг кадра на точку привязки → матрица части →
    // масштаб под размер узла → перенос в центр узла.
    var tr = 'translate(' + tx.toFixed(2) + ',' + ty.toFixed(2) + ') scale(' + k.toFixed(4) + ') ' +
      'matrix(' + a + ',' + b + ',' + c + ',' + d + ',0,0) translate(' + (-ax) + ',' + (-ay) + ')';
    // Вложенный <svg> со своим viewBox сам обрезает атлас до кадра — без
    // clipPath и уникальных id на каждый узел.
    //
    // Оговорка на будущее: РИСУЕТСЯ по этому viewBox только видимая часть, но
    // getBoundingClientRect у такой группы возвращает НЕобрезанный атлас
    // целиком (1839×541 в своём масштабе). Кому нужна настоящая геометрия
    // узла — берите прямоугольник `.sw-skill-node-bg`, он и есть его рамка.
    return '<g transform="' + tr + '"><svg x="0" y="0" width="' + w + '" height="' + h +
      '" viewBox="' + sx + ' ' + sy + ' ' + w + ' ' + h + '">' +
      '<image href="' + SW_ICON_ATLAS + '" x="0" y="0" width="' + SW_ICON_ATLAS_SIZE[0] +
      '" height="' + SW_ICON_ATLAS_SIZE[1] + '"/></svg></g>';
  }
  var desc = HERO_SKILL_DESCS[key];
  if (desc && desc.img) {
    // В парадном PNG нарисована жёлтая рамка — срезаем её тем же приёмом, что и
    // кадр атласа выше: вложенный <svg>, viewBox которого охватывает только
    // внутреннюю часть картинки. Без clipPath и уникальных id на узел.
    var inner = 1 - 2 * PERK_ICON_INSET;
    return '<svg x="' + (x - size / 2).toFixed(2) + '" y="' + (y - size / 2).toFixed(2) +
      '" width="' + size.toFixed(2) + '" height="' + size.toFixed(2) +
      '" viewBox="' + PERK_ICON_INSET + ' ' + PERK_ICON_INSET + ' ' + inner + ' ' + inner + '">' +
      '<image href="' + cdnImg(desc.img) + '" x="0" y="0" width="1" height="1" preserveAspectRatio="xMidYMid meet"/></svg>';
  }
  return '<text x="' + x.toFixed(2) + '" y="' + (y + 4).toFixed(2) + '" text-anchor="middle" font-size="11">?</text>';
}

/** 'picked' — выучен, 'open' — доступен, 'locked' — пока нельзя. */
function swSkillState(key: string): string {
  if (swPicked.indexOf(key) !== -1) return 'picked';
  return swCanLearn(key) ? 'open' : 'locked';
}

function swRenderBuildPanel(): void {
  var box = document.getElementById('sw-build');
  var m = swModel;
  if (!box || !m) return;
  var points = swBuildCost();
  var level = swPointsToLevel(points);

  var html = '';
  html += '<div class="sw-build-score"><div class="sw-build-score-label">Требуется очков:</div>' +
    '<div class="sw-build-score-value">' + points + '</div></div>';
  html += '<div class="sw-build-level" title="Формула игры: очки = 5 × (уровень − 3). Навыки открыты с 5-го уровня.">' +
    'Уровень героя: <b>' + level + '</b></div>';
  html += '<div class="sw-build-list-head">Навыки: <span>' + swPicked.length + '</span></div>';
  if (!swPicked.length) {
    html += '<div class="sw-build-empty">Кликните по навыку на колесе или в таблице, чтобы выучить его.</div>';
  } else {
    html += '<ul class="sw-build-list">';
    swPicked.forEach(function(k) {
      var d = HERO_SKILL_DESCS[k];
      var locked = !swCanForget(k);
      html += '<li class="sw-build-item' + (locked ? ' locked' : '') + '" onclick="swToggleSkill(\'' + k + '\')"' +
        ' onmouseover="swShowSkill(\'' + k + '\',\'' + m!.key + '\')"' +
        ' title="' + (locked ? 'На этот навык опираются другие — сначала забудьте их' : 'Забыть навык') + '">' +
        (d && d.img ? '<img src="' + cdnImg(d.img) + '" alt="">' : '') +
        '<span>' + (d ? d.name : k) + '</span><b>' + m!.cost[k] + '</b></li>';
    });
    html += '</ul>';
  }
  html += '<button type="button" class="sw-build-reset" onclick="swResetBuild()"' +
    (swPicked.length ? '' : ' disabled') + '>Сбросить</button>';
  box.innerHTML = html;
}

function swRenderSkillTable(): void {
  var box = document.getElementById('skillwheel-table');
  var m = swModel;
  if (!box || !m) return;

  var rows = function(nodes: WheelNode[], branch: Branch): string {
    var out = '';
    nodes.forEach(function(n) {
      var d = HERO_SKILL_DESCS[n.key];
      var state = swSkillState(n.key);
      var reqs = [m!.need1[n.key]].concat(m!.needs[n.key] || []).filter(Boolean);
      var reqNames = reqs.map(function(r) {
        var rd = HERO_SKILL_DESCS[r];
        return rd ? rd.name : r;
      });
      out += '<tr class="sw-row sw-' + state + '" data-skill="' + n.key + '"' +
        ' onclick="swToggleSkill(\'' + n.key + '\')" onmouseover="swShowSkill(\'' + n.key + '\',\'' + m!.key + '\')">' +
        '<td class="sw-row-icon">' + (d && d.img ? '<img src="' + cdnImg(d.img) + '" alt="" loading="lazy">' : '') + '</td>' +
        '<td class="sw-row-name">' + (d ? d.name : n.key) + '</td>' +
        '<td class="sw-row-cost">' + branch.cost + '</td>' +
        '<td class="sw-row-req">' + (reqNames.length ? reqNames.join(', ') : '—') + '</td>' +
        '<td class="sw-row-desc">' + (d ? d.desc : '') + '</td>' +
        '</tr>';
    });
    return out;
  };

  var html = '<h3 class="sw-table-title">Навыки и способности</h3>';
  html += '<div class="sw-table-scroll"><table class="sw-table">';
  html += '<thead><tr><th></th><th>Навык</th><th>Очки</th><th>Требует</th><th>Описание</th></tr></thead>';
  html += '<tbody>';
  if (m.uniqKey) {
    var ud = HERO_SKILL_DESCS[m.uniqKey];
    html += '<tr class="sw-table-branch"><td colspan="5">Уникальный навык класса <b>' + m.cost[m.uniqKey] + ' очк.</b></td></tr>';
    html += '<tr class="sw-row sw-' + swSkillState(m.uniqKey) + '" data-skill="' + m.uniqKey + '"' +
      ' onclick="swToggleSkill(\'' + m.uniqKey + '\')" onmouseover="swShowSkill(\'' + m.uniqKey + '\',\'' + m.key + '\')">' +
      '<td class="sw-row-icon">' + (ud && ud.img ? '<img src="' + cdnImg(ud.img) + '" alt="" loading="lazy">' : '') + '</td>' +
      '<td class="sw-row-name">' + (ud ? ud.name : m.uniqKey) + '</td>' +
      '<td class="sw-row-cost">' + m.cost[m.uniqKey] + '</td>' +
      '<td class="sw-row-req">—</td>' +
      '<td class="sw-row-desc">' + (ud ? ud.desc : '') + '</td></tr>';
  }
  m.branches.forEach(function(branch) {
    html += '<tr class="sw-table-branch"><td colspan="5">' + branch.name +
      ' <b>' + branch.cost + ' очк.</b> за навык</td></tr>';
    html += rows(branch.levels, branch);
    branch.rings.forEach(function(ring) { html += rows(ring, branch); });
  });
  html += '</tbody></table></div>';
  box.innerHTML = html;
}

export function swShowSkill(skillKey: string, wheelKey: string): void {
  var desc = HERO_SKILL_DESCS[skillKey];
  if (!desc) {
    (document.getElementById('sw-detail-empty') as HTMLElement).style.display = 'none';
    var content = document.getElementById('sw-detail-content') as HTMLElement;
    content.style.display = 'block';
    content.innerHTML = '<div class="sw-detail-name">'+skillKey+'</div><div class="sw-detail-desc">Нет описания</div>';
    return;
  }
  (document.getElementById('sw-detail-empty') as HTMLElement).style.display = 'none';
  var content = document.getElementById('sw-detail-content') as HTMLElement;
  content.style.display = 'block';

  var parts = wheelKey.split('_');
  var f = parts[0];
  var wheels = swGetWheelsForFaction(f);
  var wheel: FractionWheel | null = null;
  for (var wi = 0; wi < wheels.length; wi++) {
    if (wheels[wi].klass === false || String(wheels[wi].klass) === parts[1]) {
      wheel = wheels[wi];
      break;
    }
  }

  var branchName = '';
  if (wheel) {
    for (var wi2 = 0; wi2 < wheel.ways.length; wi2++) {
      var w = wheel.ways[wi2];
      var treeS = TREE_SKILLS[w.find];
      if (!treeS) continue;
      if (treeS.skills.indexOf(skillKey) !== -1 || treeS.uniqs.indexOf(skillKey) !== -1 ||
          (typeof w.plus === 'string' && w.plus === skillKey) ||
          (Array.isArray(w.plus) && w.plus.indexOf(skillKey) !== -1)) {
        branchName = treeS.name;
        break;
      }
    }
  }

  var html = '';
  if (desc.img) {
    html += '<div class="sw-detail-icon"><img src="'+cdnImg(desc.img)+'" alt="" onerror="this.parentElement.style.display=\'none\'"></div>';
  }
  html += '<div class="sw-detail-name">'+desc.name+'</div>';
  if (branchName) {
    html += '<div class="sw-detail-branch">Ветвь: '+branchName+'</div>';
  }
  // Стоимость и состояние набора берём из разобранной модели текущего колеса.
  if (swModel && swModel.cost[skillKey] !== undefined) {
    var st = swSkillState(skillKey);
    var stText = st === 'picked'
      ? (swCanForget(skillKey) ? 'Навык выучен — клик снимет его' : 'Навык выучен, на него опираются другие')
      : (st === 'open' ? 'Доступен — клик выучит его' : 'Пока недоступен: не выполнены требования');
    html += '<div class="sw-detail-cost">Стоимость: <b>'+swModel.cost[skillKey]+'</b> очк.</div>';
    html += '<div class="sw-detail-state sw-'+st+'">'+stText+'</div>';
  }
  html += '<div class="sw-detail-desc">'+desc.desc+'</div>';

  if (wheel && wheel.skills[skillKey]) {
    var prereq = wheel.skills[skillKey];
    var reqArr = typeof prereq === 'string' ? [prereq] : (Array.isArray(prereq) ? prereq : []);
    var reqNames: string[] = [];
    reqArr.forEach(function(r) {
      if (r && r !== 'none') {
        var d = HERO_SKILL_DESCS[r];
        reqNames.push(d ? d.name : r);
      }
    });
    if (reqNames.length) {
      html += '<div class="sw-detail-req"><b>Требует:</b> '+reqNames.join(', ')+'</div>';
    }
  }

  var inWheels: Array<{name: string; faction: string}> = [];
  for (var wk in TREE_SKILLS_FRACTION) {
    var w2 = TREE_SKILLS_FRACTION[wk];
    if (w2.skills && w2.skills[skillKey] !== undefined) {
      var fMeta2 = FACTIONS_META[w2.fraction];
      if (fMeta2) {
        inWheels.push({name:w2.nameS || w2.name, faction: fMeta2.nameRu});
      }
    }
  }
  if (inWheels.length > 1) {
    html += '<div style="margin-top:12px;padding:6px 0;border-top:1px solid var(--border);font-size:12px;color:var(--text-dim)">';
    html += 'Также входит в: '+inWheels.filter(function(w3){return w3.name !== wheel?.nameS;}).map(function(w3){return w3.name+' ('+w3.faction+')';}).join(', ');
    html += '</div>';
  }

  content.innerHTML = html;
  document.querySelectorAll('.sw-skill-node.sw-active, .sw-row.sw-active').forEach(function(el){ el.classList.remove('sw-active'); });
  document.querySelectorAll('.sw-skill-node[data-skill="'+skillKey+'"], .sw-row[data-skill="'+skillKey+'"]').forEach(function(el){ el.classList.add('sw-active'); });
}

