// ===== CONSTANTS =====

/** Значения без «%»: основные параметры, счётчики (доп. выстрелы, дальность) и флаги
 *  «есть/нет» (навыки, заклинания, +1 к скорости существ). Всё остальное — проценты. */
const PLAIN_MODIFIERS = new Set<string>([
  'attack', 'defence', 'spellpower', 'knowledge', 'luck', 'morale', 'reload', 'critical',
  'stactics', 'frost', 'sol', 'bandit', 'ves', 'bes', 'tak', 'tactics', 'zam', 'avto', 'hp',
  'magic_immunity', 'petrify',
]);
export function isPctModifier(key: string): boolean {
  return !PLAIN_MODIFIERS.has(key) && !/^(ini|sko)\d$/.test(key);
}

