export const ICON_BASE: string = '/api/img?url=https://dcdn.heroeswm.ru/i/icons/';

/** Спец-эффект: структурированная запись (новый формат) или строка (старый). */
export interface ArtifactSpecial {
  stat?: string;
  value?: number | string;
  unit?: string;
  text_ru?: string;
  unknown?: boolean;
}

export function specialText(s: ArtifactSpecial | string): string {
  if (typeof s === 'string') return s;
  return s.text_ru || s.stat || '';
}

/** Return the high-quality (_b) version of an artifact icon URL.
 *
 * Идемпотентна: 101 иконка в data/artifacts.json уже заканчивается на ``_b.png``,
 * и повторный суффикс давал ``bmedal5_b_b.png`` — такого файла на CDN нет, и
 * каждый такой запрос висел на сетевых фоллбэках вместо мгновенного кэша. */
export function artIconB(iconUrl: string | undefined | null): string {
  if (!iconUrl) return '';
  return /_b(\.[^.]+)$/i.test(iconUrl)
    ? iconUrl
    : iconUrl.replace(/(\.[^.]+)$/, '_b$1');
}

// ===== ARTIFACTS TAB =====

export function renderArtifacts(artifacts: ArtifactRecord[]): void {
  const grid = document.getElementById('artifact-grid');
  const countEl = document.getElementById('artifact-count');
  if (!grid || !countEl) return;
  countEl.textContent = artifacts.length + ' артефактов';
  grid.innerHTML = artifacts.map(a => {
    const mods = a.modifiers || {};
    const modText = Object.entries(mods)
      .filter(([,v]) => v)
      .map(([k,v]) => `<span>${MODIFIER_LABELS[k] || k}: +${v}${isPctModifier(k) ? '%' : ''}</span>`).join('');
    return `<div class="artifact-card" onclick="openArtifactModal('${a.key}')" style="cursor:pointer">
      <div style="display:flex;gap:10px;align-items:flex-start">
        ${a.icon && a.icon_ok !== false ? `<img src="/api/img?url=${encodeURIComponent(artIconB(a.icon))}" class="artifact-icon-img" loading="lazy" width="64" height="64" onerror="this.outerHTML='<div class=artifact-icon>\u2726</div>'">` : `<div class="artifact-icon">✦</div>`}
        <div>
          <div class="name">${(a as any).nameRu || a.name}</div>
          <div class="sub">${a.slot ? a.slot.charAt(0).toUpperCase() + a.slot.slice(1) : ''}${a.level ? ' · Lv' + a.level : ''}${a.category && a.category !== a.slot ? ' · ' + a.category : ''}</div>
          ${modText ? `<div class="mods">${modText}</div>` : ''}
        </div>
      </div>
    </div>`;
  }).join('');
}

/** Виды, которых НЕТ среди слотов. Слот и «категория» в данных почти
 * дублируют друг друга (weapon/ring/helm/boots/backpack/cuirass/cloack/shield —
 * это те же места на кукле), и второй список фильтров повторял первый. Здесь
 * остались только настоящие группы, слотом не выражаемые. */
export const ARTIFACT_KINDS: Record<string, string> = {
  relict: 'Реликты',
  thief: 'Воровские',
  tactic: 'Тактические',
  verb: 'Именные',
  other: 'Прочие',
};

/** Комплекты, подходящие под запрос: по названию, якорю и описанию. */
function setsMatching(q: string): number[] {
  const ids = Object.keys(SET_NAMES).map(Number);
  if (!q) return ids;
  return ids.filter(id => {
    const s = SET_NAMES[id];
    return !!s && ((s.name || '').toLowerCase().includes(q)
      || (s.anchor || '').toLowerCase().includes(q)
      || (s.description || '').toLowerCase().includes(q));
  });
}

export function filterArtifacts(shuffle?: boolean): void {
  const searchEl = document.getElementById('artifact-search') as HTMLInputElement;
  const slotEl = document.getElementById('slot-filter') as HTMLSelectElement;
  const categoryEl = document.getElementById('category-filter') as HTMLSelectElement;
  const levelEl = document.getElementById('level-filter') as HTMLSelectElement;
  if (!searchEl || !slotEl || !categoryEl || !levelEl) return;
  
  const q = searchEl.value.toLowerCase();
  const slot = slotEl.value;
  const category = categoryEl.value;
  const level = levelEl.value;
  let list: ArtifactRecord[] = Array.isArray(allData.artifacts) ? allData.artifacts : Object.values(allData.artifacts || {});
  if (shuffle) shuffleArray(list);
  if (slot) list = list.filter(a => (a.slot || '') === slot);
  if (category) list = list.filter(a => (a.category || '') === category);
  if (level) list = list.filter(a => String(a.level || '') === level);
  if (q) {
    // Запрос ищет и КОМПЛЕКТ: набрав «Пирата», игрок ждёт увидеть и сам
    // комплект, и входящие в него артефакты, а не пустой список из-за того,
    // что слово стоит только в названии комплекта.
    const hitSets = new Set(setsMatching(q));
    list = list.filter(a =>
      ((a as any).nameRu || a.name || '').toLowerCase().includes(q) ||
      (a.nameEn || '').toLowerCase().includes(q) ||
      (a.slot || '').toLowerCase().includes(q) ||
      (a.set != null && hitSets.has(Number(a.set)))
    );
  }
  // Комплекты живут в этом же разделе и подчиняются тому же поиску.
  renderSetsGrid(q);
  renderArtifacts(list);
}

export function initArtifacts(): void {
  const art: ArtifactRecord[] = Array.isArray(allData.artifacts) ? allData.artifacts : Object.values(allData.artifacts || {});
  const slots = [...new Set(art.map(a => a.slot).filter(Boolean))].sort();
  const cats = [...new Set(art.map(a => a.category).filter(Boolean))].sort();
  const lvls = [...new Set(art.map(a => a.level).filter(Boolean))].sort((a,b)=>a-b);

  const slotSel = document.getElementById('slot-filter') as HTMLSelectElement;
  if (slotSel) slots.forEach(s => { const o = document.createElement('option'); o.value=s!; o.textContent=s!; slotSel.appendChild(o); });

  const catSel = document.getElementById('category-filter') as HTMLSelectElement;
  if (catSel) {
    cats.filter(c => c && ARTIFACT_KINDS[c]).forEach(c => {
      const o = document.createElement('option');
      o.value = c!;
      o.textContent = ARTIFACT_KINDS[c!];
      catSel.appendChild(o);
    });
  }

  const lvlSel = document.getElementById('level-filter') as HTMLSelectElement;
  if (lvlSel) lvls.forEach(l => { const o = document.createElement('option'); o.value=String(l); o.textContent='Lv '+l; lvlSel.appendChild(o); });
  // Grid render is lazy — navigation.ts TAB_RENDERERS runs filterArtifacts(true) on the
  // tab's first activation instead of at startup.
}

