function setTitle(id: number, sn: SetInfo | undefined): string {
  if (SET_TITLES[id]) return SET_TITLES[id];
  if (!sn) return 'Комплект ' + id;
  if (id === 0) return sn.name + ' артефакты';
  return 'Комплект ' + sn.name.charAt(0).toLowerCase() + sn.name.slice(1);
}

export function showArtifactSet(setId: number): void {
  closeArtifactModal();
  var anchor = getSetAnchor(setId);
  navigateTo('/artifacts/' + anchor);
}

export function closeArtifactModal(): void {
  const modal = document.getElementById('artifact-modal');
  if (modal) modal.style.display = 'none';
}

// ===== SETS TAB =====

/** Раскрыт ли блок комплектов. Пустой поиск оставляет его свёрнутым: карточек
 *  54, и раскрытыми они оттесняют сами артефакты за нижний край экрана. */
let setsBlockOpen = false;

export function toggleSetsBlock(force?: boolean): void {
  setsBlockOpen = force !== undefined ? force : !setsBlockOpen;
  const grid = document.getElementById('sets-grid');
  const arrow = document.getElementById('sets-toggle');
  if (grid) grid.style.display = setsBlockOpen ? '' : 'none';
  if (arrow) arrow.textContent = setsBlockOpen ? '▾' : '▸';
}

export function renderSetsGrid(query?: string): void {
  var container = document.getElementById('sets-grid');
  var detail = document.getElementById('set-detail');
  if (!container || !detail) return;
  detail.style.display = 'none';
  container.innerHTML = '';
  // Комплекты стоят над списком артефактов в том же разделе и слушают тот же
  // поиск: пустой запрос — все, иначе только подходящие по названию.
  var allow = query ? new Set(setsMatching(query)) : null;
  // По запросу блок раскрывается сам: искали комплект — покажем найденное.
  toggleSetsBlock(query ? true : setsBlockOpen);
  var countEl = document.getElementById('sets-count');
  if (countEl) {
    const shown = allow ? allow.size : Object.keys(SET_NAMES).length;
    countEl.textContent = query ? `найдено ${shown}` : `${shown}`;
  }
  var list: ArtifactRecord[] = Array.isArray(allData.artifacts) ? allData.artifacts : Object.values(allData.artifacts || {});
  var setMap: Record<number, ArtifactRecord[]> = {};
  for (var i = 0; i < list.length; i++) {
    var a = list[i];
    if (a.set == null) continue;
    if (!setMap[a.set]) setMap[a.set] = [];
    setMap[a.set].push(a);
  }
  var setIds = Object.keys(setMap).map(Number).sort(function(a,b){return a-b});
  for (var si = 0; si < setIds.length; si++) {
    var sid = setIds[si];
    if (allow && !allow.has(sid)) continue;
    var items = setMap[sid];
    var sn = SET_NAMES[sid];
    var name = setTitle(sid, sn);
    var desc = sn ? (sn.description || '') : '';
    var iconsHtml = '';
    var shown = 0;
    for (var ii = 0; ii < items.length && shown < 8; ii++) {
      // icon_ok=false = иконки нет на CDN (клан-артефакты /kwar/) — не дёргаем прокси,
      // слот отдаём живой иконке
      if (items[ii].icon && items[ii].icon_ok !== false) {
        iconsHtml += '<img src="/api/img?url=' + encodeURIComponent(artIconB(items[ii].icon)) + '" loading="lazy" onerror="this.style.display=\'none\'">';
        shown++;
      }
    }
    var card = document.createElement('div');
    card.className = 'set-card';
    var plural = (items.length % 10 === 1 && items.length % 100 !== 11) ? '' : (items.length % 10 >= 2 && items.length % 10 <= 4 && (items.length % 100 < 10 || items.length % 100 >= 20) ? 'а' : 'ов');
    card.innerHTML = '<div class="set-name">' + name + '</div><div class="set-count">' + items.length + ' предмет' + plural + '</div>' +
      (desc ? '<div class="set-desc">' + desc + '</div>' : '') +
      '<div class="set-icons">' + iconsHtml + '</div>';
    var anchor = sn && sn.anchor ? sn.anchor : String(sid);
    card.addEventListener('click', function(a) { return function() { navigateTo('/artifacts/' + a); }; }(anchor));
    container.appendChild(card);
  }
}

export function resolveSetAnchor(anchor: string): number | null {
  // Accept numeric ID or anchor name
  if (/^\d+$/.test(anchor)) return parseInt(anchor, 10);
  return ANCHOR_TO_ID[anchor] || null;
}

export function renderSetDetail(setId: number | string): void {
  // Resolve if called with anchor string
  if (typeof setId === 'string') {
    var resolved = resolveSetAnchor(setId);
    if (resolved === null) {
      var detail = document.getElementById('set-detail');
      if (detail) detail.innerHTML = '<div style="padding:20px;color:var(--text-dim)">Комплект не найден</div>';
      return;
    }
    setId = resolved;
  }
  var container = document.getElementById('sets-grid');
  var detail = document.getElementById('set-detail');
  if (!container || !detail) return;
  container.style.display = 'none';
  detail.style.display = 'block';
  var list: ArtifactRecord[] = Array.isArray(allData.artifacts) ? allData.artifacts : Object.values(allData.artifacts || {});
  var items = list.filter(function(a){return a.set === setId});
  if (!items.length) {
    detail.innerHTML = '<div style="padding:20px;color:var(--text-dim)">Комплект не найден</div>';
    return;
  }
  var sn = SET_NAMES[setId];
  var name = setTitle(setId as number, sn);
  var desc = sn ? (sn.description || '') : '';

  // Load fitting set bonuses if available
  if (!fittingSets) {
    loadFittingSets().then(function(){if (document.getElementById('set-detail')?.style.display === 'block') renderSetDetail(setId as number);});
  }

  // Build header
  var html = '<a class="back-link" onclick="closeSetDetail()">← Все комплекты</a>';
  html += '<div class="sd-header">' + name + '</div>';
  if (desc) html += '<div class="sd-desc">' + desc + '</div>';

    // Предметы по типам (кинжал, арбалет, доспех…) — в порядке оригинала; внутри типа от лёгкого к великому.
  var slotOrder: Record<string, number> = {weapon_left: 0, weapon: 0, body: 2, helm: 3, boots: 4, cloak: 5, neck: 6, ring: 7, backpack: 8};
  var typeKey = function(x: ArtifactRecord): string { return (x.slot || '') + '|' + (x.category || ''); };
  var typeRank = function(x: ArtifactRecord): number {
    // Арбалет занимает слот плаща, но по смыслу идёт сразу за кинжалом.
    if (x.slot === 'cloak' && x.category === 'weapon') return 1;
    return slotOrder[x.slot || ''] !== undefined ? slotOrder[x.slot || ''] : 9;
  };
  items = items.slice().sort(function(x, y) {
    return typeRank(x) - typeRank(y) || (typeKey(x) < typeKey(y) ? -1 : typeKey(x) > typeKey(y) ? 1 : 0) || (x.level || 0) - (y.level || 0);
  });
  var groups: ArtifactRecord[][] = [];
  for (var gi = 0; gi < items.length; gi++) {
    var last = groups[groups.length - 1];
    if (last && typeKey(last[0]) === typeKey(items[gi])) last.push(items[gi]); else groups.push([items[gi]]);
  }

  html += '<div class="sd-main-table">';
  html += '<div class="sd-left">';
  for (var i = 0; i < items.length; i++) {
    var a = items[i];
    html += '<a class="sd-link" onclick="openArtifactModal(\'' + a.key + '\')">' + ((a as any).nameRu || a.name) + '</a>';
  }
  html += '</div>';

  // Правая половина: параметры одной строкой с иконками, эффекты — текстом.
  html += '<div class="sd-right">';
  html += '<div class="sd-bonus-header">Бонусы комплекта:</div>';
  var fs = fittingSets ? fittingSets[setId as number] : null;
  if (fs && fs.bonuses) {
    var bkeys = Object.keys(fs.bonuses).map(Number).sort(function(a,b){return a-b});
    for (var bi = 0; bi < bkeys.length; bi++) {
      var count = bkeys[bi];
      var bonus = fs.bonuses[count];
      var stats = '', effects = '';
      for (var bk in bonus) {
        if (!bonus[bk]) continue;
        var pct = isPctModifier(bk) ? '%' : '';
        if (MODIFIER_ICONS[bk]) {
          stats += '<span class="sd-stat" title="' + (MODIFIER_LABELS[bk] || bk) + '"><img src="' + ICON_BASE + MODIFIER_ICONS[bk] + '" alt="">+' + bonus[bk] + pct + '</span>';
        } else {
          var label = MODIFIER_LABELS[bk] || bk;
          var phrase = EFFECT_PHRASES[bk] || (label.charAt(0).toLowerCase() + label.slice(1));
          effects += '<div class="sd-effect">+' + bonus[bk] + pct + ' ' + phrase + '</div>';
        }
      }
      html += '<div class="sd-bonus-tier"><div class="sd-bonus-label">от ' + count + ' вещей:</div>';
      if (stats) html += '<div class="sd-stats">' + stats + '</div>';
      html += effects + '</div>';
    }
    // Правила «+N за каждые M артефактов»: до ступеней — общие, с «from» — отдельным блоком.
    var ruleHtml = function(r: any): string {
      var ic = MODIFIER_ICONS[r.stat] ? '<img src="' + ICON_BASE + MODIFIER_ICONS[r.stat] + '" alt="">' : '';
      return '<div class="sd-rule">' + ic + '<b>+' + r.value + (r.pct ? '%' : '') + '</b> ' + r.text + '</div>';
    };
    var rules: any[] = (fs as any).rules || [];
    var always = rules.filter(function(r){return !r.from});
    if (always.length) html += '<div class="sd-bonus-tier">' + always.map(ruleHtml).join('') + '</div>';
    var fromSet: Record<number, any[]> = {};
    rules.filter(function(r){return r.from}).forEach(function(r){(fromSet[r.from] = fromSet[r.from] || []).push(r);});
    Object.keys(fromSet).map(Number).sort(function(a,b){return a-b}).forEach(function(n){
      html += '<div class="sd-bonus-tier"><div class="sd-bonus-label">От ' + n + ' вещей дополнительно:</div>' + fromSet[n].map(ruleHtml).join('') + '</div>';
    });
    if (!bkeys.length && !rules.length) html += '<div class="sd-effect">отсутствуют</div>';
  } else {
    html += '<div style="color:var(--text-dim);font-size:13px;margin-top:12px">Данные о бонусах загружаются...</div>';
  }
  html += '</div>';

  // Иконки: если у всех типов поровну ступеней (лёгкий/обычный/великий) — столбец на тип,
  // строка на ступень; иначе (тактик: по одной вещи каждого вида) просто ровная сетка по порядку.
  var sameTiers = groups.length > 1 && groups[0].length > 1 && groups.every(function(g){return g.length === groups[0].length;});
  var iconTag = function(it: ArtifactRecord): string {
    return '<img src="/api/img?url=' + encodeURIComponent(artIconB(it.icon || '')) + '" loading="lazy" title="' + ((it as any).nameRu || it.name) + '" onerror="this.style.visibility=\'hidden\'" onclick="openArtifactModal(\'' + it.key + '\')">';
  };
  var layout = SET_LAYOUTS[setId as number];
  if (layout) {
    // Как в оригинале: клетки по строкам раскладки; пустая клетка — просвет, одиночная
    // строка в широкой сетке тянется на всю ширину (по центру).
    var maxCols = 0;
    layout.forEach(function(row){ if (row.length > maxCols) maxCols = row.length; });
    var byKey: Record<string, ArtifactRecord> = {};
    items.forEach(function(x){ byKey[x.key] = x; });
    html += '<div class="sd-icons-grid sd-doll" style="grid-template-columns:repeat(' + maxCols + ',minmax(0,100px))">';
    layout.forEach(function(row){
      row.forEach(function(k, ci){
        var cell = k && byKey[k] ? iconTag(byKey[k]) : '<span></span>';
        if (row.length === 1 && maxCols > 1) html += '<div class="sd-doll-wide" style="grid-column:1 / -1">' + cell + '</div>';
        else html += cell;
      });
      // Короткая строка добивается пустыми клетками, иначе следующая строка начнётся в её хвосте.
      if (row.length > 1 || maxCols === 1) for (var pad = row.length; pad < maxCols; pad++) html += '<span></span>';
    });
  } else if (sameTiers) {
    html += '<div class="sd-icons-grid" style="grid-template-columns:repeat(' + groups.length + ',minmax(0,100px))">';
    for (var r = 0; r < groups[0].length; r++) for (var g2 = 0; g2 < groups.length; g2++) html += iconTag(groups[g2][r]);
  } else {
    html += '<div class="sd-icons-grid" style="grid-template-columns:repeat(auto-fill,minmax(0,100px))">';
    for (var ii = 0; ii < items.length; ii++) html += iconTag(items[ii]);
  }
  html += '</div>';
  html += '</div>';

  detail.innerHTML = html;
}

export function closeSetDetail(): void {
  const detailEl = document.getElementById('set-detail');
  const gridEl = document.getElementById('sets-grid');
  if (detailEl) detailEl.style.display = 'none';
  if (gridEl) gridEl.style.display = '';
  navigateTo('/artifacts');
}

export function getSetAnchor(setId: number): string {
  var sn = SET_NAMES[setId];
  return sn && sn.anchor ? sn.anchor : String(setId);
}

