/** У гнома по умолчанию открыты все десять рун: они открываются по уровню фракции (1…10),
 * поэтому при выборе класса с нетронутым уровнем 1 ставим 10 (игрок может снизить). */
function tacDwarfDefaultLevel(inputId: string, isDwarf: boolean): void {
  const el = document.getElementById(inputId) as HTMLInputElement | null;
  if (isDwarf && el && (parseInt(el.value) || 1) < 10) el.value = '10';
}

export function tacHeroClassChange() {
  const sel = tacById('tac-hero-class');
  const skillsEl = tacById('tac-hero-class-skills');
  const abilEl = tacById('tac-hero-faction-ability');
  tacHero.cls = sel.value;
  tacDwarfDefaultLevel('tac-hero-flvl', sel.value === 'dwarf');
  tacRenderHeroTile();
  // Способность эльфа уже в строке фракционной способности ниже — вторая, устаревшая строка
  // («+5%/ур.») дублировала её.
  skillsEl.style.display = 'none';
  if (sel.value && FACTION_ABILITY_INFO[sel.value as keyof typeof FACTION_ABILITY_INFO]) {
    const info = FACTION_ABILITY_INFO[sel.value as keyof typeof FACTION_ABILITY_INFO];
    abilEl.innerHTML = `<span style="color:var(--gold)">${info.icon} ${info.text}</span>`;
  } else {
    abilEl.innerHTML = '';
  }
  // Набор колеса привязан к классу: сменили класс — строка о навыках должна
  // сразу сказать, подходит ли собранный билд.
  tacUpdateHeroPerksCount();
  // Фигура героя на поле и фишка в ленте — по новому классу.
  tacRenderHeroFigures();
  tacRenderInitiative();
}


/** Ключи артефактов, надетых в Примерочной. Сервер надевает их герою (build_hero →
 * Hero.equip), откуда берутся прибавки к атаке/защите/удаче/морали и процентная
 * защита от стрелков. Кукла в Примерочной одна, поэтому артефакты достаются только
 * герою ИГРОКА — врагу их взять неоткуда. */
export function tacHeroArtifactEntries(heroIndex = 0): Array<string | { key: string; craft: Record<string, number> }> {
  const on = tacById('tac-hero-use-arts');
  if (on && !on.checked) return [];
  const entries: Array<string | { key: string; craft: Record<string, number> }> = [];
  // Героя игрока одевает Герой 1 куклы, второго героя (справа) — Герой 2.
  const worn = fittingHero(heroIndex);
  for (const slot in worn.equipment) {
    const a = worn.equipment[slot];
    if (!a || !a.key) continue;
    // Крафт — свойство экземпляра на кукле: уезжает рядом с ключом. Без него
    // остаётся прежняя строка — так формат запроса не меняется для базовых предметов.
    const craft = worn.craft[slot];
    entries.push(craft && Object.keys(craft).length ? { key: a.key, craft: { ...craft } } : a.key);
  }
  return entries;
}

export function tacHeroArtifactKeys(): string[] {
  const on = tacById('tac-hero-use-arts');
  if (on && !on.checked) return [];
  const keys = [];
  const worn = fittingHero(0).equipment;
  for (const slot in worn) {
    const a = worn[slot];
    if (a && a.key) keys.push(a.key);
  }
  return keys;
}

/** Навыки из колеса, которые уедут в бой (`Hero.perks` на сервере).
 *
 * Колесо собирается для КОНКРЕТНОГО класса, поэтому набор чужой фракции не
 * применяется: перки там свои, и «Надзор» рыцаря у некроманта — не билд, а
 * ошибка. Класс героя в бою задаётся отдельным списком, отсюда и сверка. */
export function tacHeroPerkKeys(heroIndex = 0): string[] {
  const on = tacById('tac-hero-use-perks');
  if (on && !on.checked) return [];
  const build = swGetBattleBuild(heroIndex);
  if (!build || !build.perks.length) return [];
  // Класс героя: свой — из списка палитры, второго — из Героя 2 Примерочной.
  const cls = heroIndex === 1 ? tacEnemyClass() : tacHero.cls;
  if (cls && build.faction && build.faction !== cls) return [];
  return build.perks.slice();
}

/** Прибавка от навыков колеса к удаче или морали.
 *
 * Те же ступени, что у сервера (battle/hero_perks.py, LEVELED): `luck1..3` →
 * +1..3, `leadership1..3` → +1..3. Нужна карточке отряда ВНЕ боя: в запрос
 * навыки уезжают отдельным списком (`perks`), и `luck_bonus` в данных героя
 * несёт только то, что вбито руками в панели. Пока бой идёт, значения берутся
 * из состояния сервера и этот расчёт не используется.
 */
export function tacHeroPerkBonus(kind: 'luck' | 'leadership'): number {
  let best = 0;
  for (const key of tacHeroPerkKeys()) {
    const m = new RegExp('^' + kind + '([123])$').exec(key);
    if (m) best = Math.max(best, Number(m[1]));
  }
  return best;
}

/** Строка о наборе рядом с флажком: сколько навыков уедет и почему не уедут. */
export function tacUpdateHeroPerksCount() {
  const el = tacById('tac-hero-perks-count');
  const note = tacById('tac-hero-perks-note');
  if (!el) return;
  const build = swGetBattleBuild();
  const on = tacById('tac-hero-use-perks');
  const n = tacHeroPerkKeys().length;
  el.textContent = n ? `— ${n} шт.` : '— пусто';
  if (!note) return;
  if (!build || !build.perks.length) {
    note.textContent = 'Наберите билд во вкладке «Колёса навыков».';
  } else if (on && !on.checked) {
    note.textContent = '';
  } else if (tacHero.cls && build.faction && build.faction !== tacHero.cls) {
    const built = FACTIONS_META[build.faction]?.nameRu || build.faction;
    const now = FACTIONS_META[tacHero.cls]?.nameRu || tacHero.cls;
    note.textContent = `Набор собран для класса «${built}», а герой — «${now}»: навыки не применяются.`;
  } else {
    note.textContent = '';
  }
}

/**
 * Отчёт сервера по набору навыков (`perks` в ответе /api/simulate).
 *
 * Показывает ровно то, что движок с набором сделал: применил, пропустил как
 * внебоевой навык или пока не умеет. Ничего не показывать нельзя — иначе
 * выученный перк, которого движок не считает, выглядит сломанным.
 */
export function tacShowPerkReport(report: any) {
  const note = tacById('tac-hero-perks-note');
  if (!note) return;
  if (!report) { tacUpdateHeroPerksCount(); return; }
  const name = (k: string) => HERO_SKILL_DESCS[k]?.name || k;
  const parts: string[] = [];
  if (report.applied?.length) parts.push(`применено ${report.applied.length}`);
  if (report.hero_attack?.length) {
    parts.push(`прямая атака героя: ${report.hero_attack.map(name).join(', ')}`);
  }
  if (report.atb?.length) {
    parts.push(`шкала ATB героя: ${report.atb.map(name).join(', ')}`);
  }
  if (report.out_of_battle?.length) {
    parts.push(`вне боя: ${report.out_of_battle.map(name).join(', ')}`);
  }
  if (report.unsupported?.length) {
    parts.push(`движок пока не считает: ${report.unsupported.map(name).join(', ')}`);
  }
  if (report.wrong_class?.length) {
    parts.push(`не для класса героя (отброшено): ${report.wrong_class.map(name).join(', ')}`);
  }
  if (report.unknown?.length) parts.push(`неизвестно серверу: ${report.unknown.join(', ')}`);
  note.textContent = parts.join('; ');
}

/** Показать в панели героя, сколько артефактов реально уедет в бой. Без этого связь с
 * Примерочной была бы невидимой: игрок туда мог не заходить, и бой молча шёл бы без
 * снаряжения. */
export function tacUpdateHeroArtsCount() {
  const el = tacById('tac-hero-arts-count');
  if (!el) return;
  const n = tacHeroArtifactKeys().length;
  el.textContent = n ? `— ${n} шт.` : '— пусто';
}

const MINI_KINDS = ['atk', 'def', 'spd', 'hp', 'mor', 'ini'];

/** Мини-артефакты героя из конструктора страницы магов: {уровень существ: {параметры, умение при сборке}} — только одетые. */
function miniArtifactsForBattle(heroIdx: number): Record<number, { parts: string[]; level: number }> {
  const out: Record<number, { parts: string[]; level: number }> = {};
  try {
    const list = JSON.parse(localStorage.getItem('mini-artifacts-v1') || '[]') as { parts: number[]; wearer: string; hero?: number; level?: number }[];
    for (const a of list) {
      if ((a.hero === 1 ? 1 : 0) !== heroIdx) continue;   // у героев 1 и 2 комплекты раздельные
      const m = /^tier(\d)$/.exec(a.wearer || '');
      if (!m) continue;
      // Считаем по надетому артефакту: умение фракции, с которым он собран.
      out[Number(m[1])] = { parts: a.parts.map(i => MINI_KINDS[i]).filter(Boolean), level: Number(a.level) || DEFAULT_FACTION_LEVEL };
    }
  } catch { /* без хранилища артефактов нет */ }
  return out;
}


export function tacGetHeroData(): HeroData | null {
  tacHero.atk = tacHeroManual(0, 'atk');
  tacHero.def = tacHeroManual(0, 'def');
  tacHero.ini = tacHeroManual(0, 'ini');
  tacHero.luck = tacHeroManual(0, 'luck');
  tacHero.morale = tacHeroManual(0, 'morale');
  const sp = tacHeroManual(0, 'sp');
  const knowManual = tacHeroManual(0, 'know');
  const flvl = parseInt(tacById('tac-hero-flvl').value) || DEFAULT_FACTION_LEVEL;
  if (!tacHero.cls) return null;
  const spells = Object.keys(allData.magics! || {});
  return {
    name: FACTIONS_META[tacHero.cls]?.nameRu || '',
    faction: tacHero.cls,
    // Очки параметров из Примерочной (БУ − 1 + образование) идут в бой наравне с ручными прибавками панели.
    attack_bonus: tacHero.atk + fittingAllocTotals(0).attack + tacFactionBase(0, 'attack'),
    defense_bonus: tacHero.def + fittingAllocTotals(0).defence + tacFactionBase(0, 'defence'),
    // Очки защиты, вложенные вручную в Примерочной: Повелитель смерти обращает в бою ТОЛЬКО их в нападение.
    defense_alloc: fittingAllocTotals(0).defence,
    initiative_bonus_pct: tacHero.ini + tacFactionBase(0, 'initiative'),
    luck_bonus: tacHero.luck,
    morale_bonus: tacHero.morale + tacFactionBase(0, 'morale'),
    spell_power: sp + fittingAllocTotals(0).spellpower + tacFactionBase(0, 'spellpower'),
    knowledge: knowManual + fittingAllocTotals(0).knowledge + tacFactionBase(0, 'knowledge'),
    mana_max: tacHeroKnowledge(0) * 10,
    spells: spells,
    faction_lvl: flvl,
    // «Тёмная сила» и «Сияние Луны и Солнца» отдельными галочками не задаются:
    // это перки колеса навыков (battle/hero_perks.py, FLAGS), и приходят они
    // вместе с `perks`. Альтернативный класс редактор тоже не выставляет —
    // сервер без поля берёт основной (battle/service.py).
    // «Вся магия»: снимает серверный запрет NOT_HERO_SPELLS (Армагеддон и т.п.).
    allow_all_magic: !!tacById<HTMLInputElement>('tac-hero-all-magic')?.checked,
    favoured_enemy_crit_chance: tacHero.cls === 'elf' ? elfCritChance(flvl) : 0,
    // Заклятые враги из выбора на странице эльфов: двойной урон только по ним, без выбора крита нет.
    ...(tacHero.cls === 'elf' ? { favoured_units: favoredUnitIds(0, allData.factions, allData.units) } : {}),
    artifacts: tacHeroArtifactEntries(),
    // Навыки из колеса: сервер разбирает их в battle/hero_perks.py.
    perks: tacHeroPerkKeys(),
    // Книга — по навыкам колеса (школа открыта навыком, массовые — через «Мастеров»), пока галочка «навыки» включена.
    skill_gated_book: tacById('tac-hero-use-perks')?.checked !== false,
    level: fittingHero(0).level,
    // Артефакты, собранные в конструкторе мага и одетые на отряды (без них бонуса нет).
    ...(tacHero.cls === 'magi' ? { mini_artifacts: miniArtifactsForBattle(0) } : {}),
  };
}

/** Герой противника. Панели у него больше нет — правую колонку редактора убрали
 *  целиком, — поэтому данных взять неоткуда и бой идёт без вражеского героя.
 *
 *  Функция оставлена, а не выпилена: её зовёт сборка запроса к серверу, и `null`
 *  там был штатным ответом и раньше — панель по умолчанию стояла на «— Нет
 *  героя —», и все бои без явной настройки шли ровно так же. */
export function tacGetEnemyHeroData(): HeroData | null {
  if (!tacEnemyHeroOn) return null;
  const doll = fittingHero(1);
  const base = tacEnemyClass();
  if (!base) return null;
  // Параметры — из панели второго героя, артефакты и крафт — у Героя 2 Примерочной, навыки — из
  // второго набора колеса. Галочки «артефакты»/«навыки» общие с панелью героя игрока.
  const num = (id: string, def: number) => {
    const v = parseInt((document.getElementById(id) as HTMLInputElement | null)?.value || '');
    return isNaN(v) ? def : v;
  };
  const data: HeroData = {
    name: FACTIONS_META[base]?.nameRu || '',
    faction: base,
    attack_bonus: tacHeroManual(1, 'atk') + fittingAllocTotals(1).attack + tacFactionBase(1, 'attack'),
    defense_bonus: tacHeroManual(1, 'def') + fittingAllocTotals(1).defence + tacFactionBase(1, 'defence'),
    defense_alloc: fittingAllocTotals(1).defence,
    initiative_bonus_pct: tacHeroManual(1, 'ini') + tacFactionBase(1, 'initiative'),
    luck_bonus: tacHeroManual(1, 'luck'),
    morale_bonus: tacHeroManual(1, 'morale') + tacFactionBase(1, 'morale'),
    spell_power: tacHeroManual(1, 'sp') + fittingAllocTotals(1).spellpower + tacFactionBase(1, 'spellpower'),
    knowledge: tacHeroManual(1, 'know') + fittingAllocTotals(1).knowledge + tacFactionBase(1, 'knowledge'),
    mana_max: tacHeroKnowledge(1) * 10,
    spells: Object.keys(allData.magics || {}),
    faction_lvl: Math.max(1, num('tac-hero2-flvl', DEFAULT_FACTION_LEVEL)),
    allow_all_magic: !!tacById<HTMLInputElement>('tac-hero-all-magic')?.checked,
    favoured_enemy_crit_chance: base === 'elf' ? elfCritChance(Math.max(1, num('tac-hero2-flvl', DEFAULT_FACTION_LEVEL))) : 0,
    ...(base === 'elf' ? { favoured_units: favoredUnitIds(1, allData.factions, allData.units) } : {}),
    artifacts: tacHeroArtifactEntries(1),
    perks: tacHeroPerkKeys(1),
    skill_gated_book: tacById('tac-hero-use-perks')?.checked !== false,
    level: fittingHero(1).level,
    // Свой комплект мини-артефактов героя 2 (у обычного мага; без них бонуса нет).
    ...(base === 'magi' ? { mini_artifacts: miniArtifactsForBattle(1) } : {}),
  };
  // Классы 101+ — альтернативные (Рыцарь света, Маг-разрушитель, …), 205 — варвар-шаман.
  if (doll.faction >= 100) data.use_alt_ability = true;
  if (doll.faction === 205) data.faction_alt_cls = 'shaman';
  return data;
}

// ── Второй герой (справа) ──────────────────────────────────────────────────

/** Включён ли второй герой: плитка «+» в палитре. Класс и артефакты — у Героя 2 примерочной. */
export let tacEnemyHeroOn = false;

/** Номер фракции куклы (`fitting.FRACTIONS`, без сотен) → системное имя класса боя. */
const ENEMY_FACTION_BY_DOLL: Record<number, string> = {
  1: 'knight', 2: 'necromance', 3: 'magi', 4: 'elf', 5: 'barbarian',
  6: 'telf', 7: 'demon', 8: 'dwarf', 9: 'stepbarbarian', 10: 'faraon',
};

/** Плитка «+» / второго героя рядом с плиткой героя игрока. */
export function tacRenderHeroTile2() {
  tacSyncNameInputs();
  tacSyncHeroStats();
  const tile = document.getElementById('tac-hero2-tile');
  if (!tile) return;
  // «+» показываем, только когда свой герой уже выбран; снят герой — второй тоже убирается.
  if (!heroChipInfo('player')) {
    tile.style.display = 'none';
    if (tacEnemyHeroOn) {
      tacEnemyHeroOn = false;
      const body = document.getElementById('tac-hero2-body');
      if (body) body.style.display = 'none';
    }
    return;
  }
  tile.style.display = '';
  if (tacEnemyHeroOn) tacUpdateHero2Info();
  const info = tacEnemyHeroOn ? heroChipInfo('enemy') : null;
  tile.classList.toggle('on', !!info);
  if (!info) {
    tile.innerHTML = '+';
    tile.title = 'Добавить второго героя справа (класс и артефакты — Герой 2 в Примерочной)';
    return;
  }
  tile.innerHTML = heroChipFace(info) + '<span class="tac-hero2-del" title="Убрать второго героя">×</span>';
  tile.title = `${info.name} — второй герой (класс и артефакты — Герой 2 в Примерочной)`;
}

/** Системное имя класса второго героя (по фракции Героя 2 Примерочной). */
export function tacEnemyClass(): string {
  return ENEMY_FACTION_BY_DOLL[fittingHero(1).faction % 100] || '';
}

/** Клик по плитке: «+» добавляет второго героя, «×» на нём — убирает, клик по портрету
 *  раскрывает/сворачивает его настройки (класс, параметры, артефакты, навыки). */
export function tacHero2Click(ev?: MouseEvent) {
  const target = ev && (ev.target as HTMLElement | null);
  const isDel = !!(target && target.classList.contains('tac-hero2-del'));
  const body = document.getElementById('tac-hero2-body');
  if (tacEnemyHeroOn && !isDel) {
    tacToggleHero2();
    return;
  }
  tacEnemyHeroOn = !tacEnemyHeroOn;
  if (body) body.style.display = tacEnemyHeroOn ? 'block' : 'none';
  tacRenderHeroTile2();
  tacRenderHeroFigures();
  tacRenderInitiative();
}

/** Показать/скрыть панель второго героя: клик по его плитке или по его фигуре на поле. */
export function tacToggleHero2(): void {
  const body = document.getElementById('tac-hero2-body');
  if (!tacEnemyHeroOn || !body) return;
  body.style.display = body.style.display === 'none' ? 'block' : 'none';
  tacUpdateHero2Info();
}

/** Список классов второго героя: те же, что в Примерочной (с альтернативными), парами. */
function tacFillHero2Classes(): void {
  const sel = document.getElementById('tac-hero2-class') as HTMLSelectElement | null;
  if (!sel || sel.options.length) return;
  Object.keys(FRACTIONS).map(Number).sort((x, y) => x % 100 - y % 100 || x - y).forEach(id => {
    const o = document.createElement('option');
    o.value = String(id);
    o.textContent = FRACTIONS[id];
    sel.appendChild(o);
  });
}

/** Смена класса второго героя: он же — фракция Героя 2 Примерочной (кукла и класс не расходятся). */
export function tacHero2ClassChange(): void {
  const sel = document.getElementById('tac-hero2-class') as HTMLSelectElement | null;
  if (!sel) return;
  fittingHero(1).faction = parseInt(sel.value) || 1;
  tacDwarfDefaultLevel('tac-hero2-flvl', fittingHero(1).faction % 100 === 8);
  // Если Примерочная уже построена — перерисовать куклу Героя 2 там.
  try { (window as any).renderDoll?.(); (window as any).renderEffects?.(); } catch { /* вкладка ещё не открывалась */ }
  tacRenderHeroTile2();
  tacRenderHeroFigures();
  tacRenderInitiative();
}

/** Строки панели второго героя: класс, способность фракции, число артефактов и навыков. */
export function tacUpdateHero2Info(): void {
  tacFillHero2Classes();
  const sel = document.getElementById('tac-hero2-class') as HTMLSelectElement | null;
  if (sel) sel.value = String(fittingHero(1).faction);
  const cls = tacEnemyClass();
  const abil = document.getElementById('tac-hero2-faction-ability');
  const info = FACTION_ABILITY_INFO[cls as keyof typeof FACTION_ABILITY_INFO];
  if (abil) abil.innerHTML = info ? `<span style="color:var(--gold)">${info.icon} ${info.text}</span>` : '';
  const arts = document.getElementById('tac-hero2-arts-count');
  const n = tacHeroArtifactEntries(1).length;
  if (arts) arts.textContent = n ? `— ${n} шт.` : '— пусто';
  const perksEl = document.getElementById('tac-hero2-perks-count');
  const note = document.getElementById('tac-hero2-perks-note');
  const keys = tacHeroPerkKeys(1);
  if (perksEl) perksEl.textContent = keys.length ? `— ${keys.length} шт.` : '— пусто';
  if (note) {
    const build = swGetBattleBuild(1);
    if (!build || !build.perks.length) note.textContent = 'Наберите билд во вкладке «Колёса навыков» (набор для Героя 2).';
    else if (cls && build.faction && build.faction !== cls) {
      note.textContent = `Набор собран для класса «${FACTIONS_META[build.faction]?.nameRu || build.faction}», а герой — «${FACTIONS_META[cls]?.nameRu || cls}»: навыки не применяются.`;
    } else note.textContent = '';
  }
}

/** Примерочная — одеть Героя 2. */
export function tacHero2OpenDressroom(): void {
  (window as any).navigateTo?.('/dressroom');
}

/** Колесо навыков — набор для Героя 2 (колесо открывается на его классе). */
export function tacHero2OpenSkills(): void {
  swSetHeroSlot(1);
  const id = fittingHero(1).faction;
  const idx = id >= 200 ? 2 : id >= 100 ? 1 : 0;
  const cls = tacEnemyClass();
  (window as any).navigateTo?.('/skillwheels/' + cls + (idx ? '/' + idx : ''));
}
