import type { GameData } from './types/api.js';
import { init } from './navigation.js';

export let allData: GameData = {};

export async function loadData(): Promise<void> {
  const loadingEl = document.getElementById('loading-indicator') || (function() {
    const el = document.createElement('div');
    el.id = 'loading-indicator';
    el.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;display:flex;align-items:center;justify-content:center;background:var(--bg);z-index:9999;font-size:18px;color:var(--gold)';
    el.textContent = 'Загрузка данных...';
    document.body.prepend(el);
    return el;
  })();

  function fetchJSON<T>(url: string, fallback: T): Promise<T> {
    return fetch(url).then(function(r) { if (!r.ok) throw new Error(r.status as unknown as string); return r.json(); })
      .catch(function(e: Error) { console.warn('Failed to load ' + url + ': ' + e.message); return fallback; });
  }

  /** Ручка API, а если её нет — статический дамп рядом с сайтом.
   *
   * Второй адрес нужен опубликованной статике (GitHub Pages): там Python-сервера
   * нет, а дампы кладёт scripts/build_static_data.py. Обычно до фолбэка не
   * доходит — на статике ручку подменяет service worker, — но он отваливается
   * в приватных окнах и на первой загрузке до активации, и тогда каталог
   * держится на этой ветке.
   */
  function fetchData<T>(apiUrl: string, dumpUrl: string, fallback: T): Promise<T> {
    return fetchJSON<T>(apiUrl, fallback).then(function(d) {
      return Object.keys(d as unknown as object).length ? d : fetchJSON(dumpUrl, fallback);
    });
  }

  var [units, factions, artifacts, abilities, magics, unitsByFaction] = await Promise.all([
    fetchData('/api/units', '/data/units.json', {}),
    fetchData('/api/factions', '/data/factions.json', {}),
    fetchData('/api/artifacts', '/data/artifacts.json', []),
    fetchData('/api/abilities', '/data/abilities.json', {}),
    fetchData('/api/magics', '/data/magics.json', {}),
    fetchJSON('/data/units_by_faction.json', {}),
  ]);
  allData = { units, factions, artifacts, abilities, magics, unitsByFaction };
  var loadedCount = [units, factions, artifacts, abilities, magics, unitsByFaction].filter(function(d) { return d && Object.keys(d).length; }).length;
  if (loadedCount === 0) {
    loadingEl.innerHTML = '❌ Не удалось загрузить данные.<br>Убедитесь что сервер запущен: <code>uvicorn api.app:app</code>';
    loadingEl.style.color = '#ff6b6b';
    return;
  }
  loadingEl.textContent = '✓ Загружено (' + loadedCount + '/6)';
  setTimeout(function() { loadingEl.style.display = 'none'; }, 500);
  init();
}

