// ===== REPLAY TAB (ES Module) =====

let replayInputTimer: ReturnType<typeof setTimeout> | null = null;

export function setReplayId(id: string): void {
  (document.getElementById('replay-warid') as HTMLInputElement).value = id;
  startReplay();
}

export function extractWarId(input: string): string | null {
  var s = input.trim();
  if (!s) return null;
  if (/^\d+$/.test(s)) return s;
  var m = s.match(/[?&]warid=(\d+)/i);
  if (m) return m[1];
  m = s.match(/(?:\/war\/id\/|\/battle\/id\/)(\d+)/i);
  if (m) return m[1];
  m = s.match(/(?:war|battle).*\/id\/(\d+)/i);
  if (m) return m[1];
  m = s.match(/\bid=(\d+)/i);
  if (m) return m[1];
  return null;
}

export function openReplayById(id: string): void {
  window.open('/replay.html?warid=' + id, '_blank');
}

export function setReplayCardContent(html: string): void {
  var content = document.getElementById('replay-card-content');
  if (!content) return;
  content.innerHTML = html ? `<div class="replay-daily-card">${html}</div>` : '<div style="color:var(--text-dim)">Карточка не найдена</div>';
}

export function loadDailyWarCard(id: string): void {
  var content = document.getElementById('replay-card-content');
  if (!content) return;
  content.innerHTML = '<div style="color:var(--text-dim)">Загрузка карточки с daily.heroeswm.ru...</div>';
  fetch('/api/daily-war-card/' + encodeURIComponent(id))
    .then(function(response) {
      if (!response.ok) throw new Error('Не удалось загрузить карточку');
      return response.json();
    })
    .then(function(data: { error?: string; html?: string }) {
      if (data.error) throw new Error(data.error);
      setReplayCardContent(data.html || '');
    })
    .catch(function(err: Error) {
      if (!content) return;
      content.innerHTML = `<div style="color:#ff6b6b">Не удалось загрузить карточку: ${err.message}</div>`;
    });
}

export function showReplayCard(id: string, rawInput: string): void {
  var modal = document.getElementById('replay-card-modal');
  var cardId = document.getElementById('replay-card-id');
  var cardSource = document.getElementById('replay-card-source');
  var cardOpen = document.getElementById('replay-card-open');
  var cardDaily = document.getElementById('replay-card-daily');
  
  if (!modal || !cardId || !cardSource || !cardOpen || !cardDaily) return;
  
  cardId.textContent = id;
  cardSource.textContent = rawInput || `https://www.heroeswm.ru/warlog.php?warid=${id}`;
  cardOpen.onclick = function() { openReplayById(id); };
  cardDaily.onclick = function() {
    var source = (rawInput || '').trim();
    var linkUrl = source && /^https?:\/\//i.test(source) ? source : `https://www.heroeswm.ru/warlog.php?warid=${id}`;
    window.open(linkUrl, '_blank');
  };
  if (modal.parentNode !== document.body) document.body.appendChild(modal);
  loadDailyWarCard(id);
  modal.style.display = 'flex';
}

export function closeReplayCard(): void {
  const modal = document.getElementById('replay-card-modal');
  if (modal) modal.style.display = 'none';
}

export function handleReplayInput(): void {
  var input = document.getElementById('replay-warid') as HTMLInputElement;
  var errEl = document.getElementById('replay-error');
  if (!input || !errEl) return;
  
  if (replayInputTimer) clearTimeout(replayInputTimer);
  replayInputTimer = setTimeout(function() {
    var id = extractWarId(input.value);
    var s = input.value.trim();
    var ready = id && (s.indexOf('warid=') >= 0 || /\/war\/id\//i.test(s) || /^\d{8,}$/.test(s));
    if (ready && id) {
      errEl!.style.display = 'none';
      showReplayCard(id, input.value);
    } else {
      errEl!.style.display = 'none';
      closeReplayCard();
    }
  }, 900);
}

export function startReplay(): void {
  var input = document.getElementById('replay-warid') as HTMLInputElement;
  if (!input) return;
  
  var id = extractWarId(input.value);
  var errEl = document.getElementById('replay-error');
  if (!errEl) return;
  
  if (!id) {
    errEl.textContent = 'Введите ID боя или ссылку (например, https://daily.heroeswm.ru/mt61/war/id/1644923289)';
    errEl.style.display = '';
    return;
  }
  errEl.style.display = 'none';
  showReplayCard(id, input.value);
}

