interface TooltipElement extends HTMLDivElement {
  _el?: Element;
}

let tip: TooltipElement | null = null;

function removeTooltip(): void {
  if (tip) { tip.remove(); tip = null; }
}

function showTooltip(el: Element): void {
  removeTooltip();
  var desc = el.getAttribute('data-label');
  if (!desc) return;
  tip = document.createElement('div') as TooltipElement;
  tip.className = 'tag-tooltip';
  tip.innerHTML = '<div class="tooltip-name">' + el.textContent + '</div><div class="tooltip-desc">' + desc + '</div>';
  document.body.appendChild(tip);
  var r = el.getBoundingClientRect();
  tip.style.left = r.left + r.width / 2 + 'px';
  tip.style.top = r.top - 8 + 'px';
  var tr = tip.getBoundingClientRect();
  if (tr.left < 8) tip.style.left = (8 + tr.width / 2) + 'px';
  if (tr.right > window.innerWidth - 8) tip.style.left = (window.innerWidth - 8 - tr.width / 2) + 'px';
  if (tr.top < 8) { tip.style.top = r.bottom + 8 + 'px'; }
}

function initTooltips(): void {
  document.addEventListener('mouseover', function(e: MouseEvent) {
    var el = (e.target as Element).closest('.tag[data-label]');
    if (!el) return;
    if (tip && tip._el === el) return;
    showTooltip(el);
    if (tip) tip._el = el;
  });
  document.addEventListener('mouseout', function(e: MouseEvent) {
    if ((e.target as Element).closest('.tag[data-label]')) removeTooltip();
  });
}

export { initTooltips };
