function spellSchool(sp: MagicRecord): string {
  // Карта задаёт ПОРЯДОК и группировку разделов, но не заменяет данные: у
  // заклинания, которого в ней ещё нет, школа берётся своя — иначе новая запись
  // молча проваливалась бы в «прочее», а его на странице больше нет.
  return SPELL_SCHOOL_MAP[sp.sys] || sp.school || 'other';
}

function spellLevel(sp: MagicRecord): number {
  return sp.lvl || SPELL_LEVEL_MAP[sp.sys] || 1;
}

function magicIconUrl(sp: MagicRecord): string {
  // Ровно та же иконка, что в боевой книге: и путь к картинкам оригинала, и
  // подмены для заклинаний, которых в ней не нарисовано, живут одним местом
  // (spellBookView.SPELL_ICON_OVERRIDES). Раньше карта подмен была своя, и
  // «Гипноз» со «Скорбью» показывались в справочнике, но не в бою.
  return sp.sys ? spellIconUrl(sp.sys) : '';
}

/** Что означает величина в таблице уровней — по типу заклинания.
 *
 * `stat` и `effect` — это не «урон», а прибавка к своей характеристике: у
 * «Каменной кожи» защита, у «Ускорения» инициатива, у «Рассеивания» доля
 * снимаемого эффекта. Без подписи строка «+3» ничего не значит. */
const LEVEL_VALUE_LABEL: Record<string, string> = {
  buff_att: 'нападение',
  buff_def: 'защита',
  buff_speed: 'инициатива',
  buff_shoot_protect: 'защита от стрел',
  buff_t: 'мин. урон',
  buff_SE: 'эффективность',
  morale: 'боевой дух',
  moraleluck: 'мораль и удача',
  hp: 'здоровье',
  count: 'существ',
};

/** Строка таблицы уровней: величина заклинания на этом уровне владения школой.
 *
 * Формы записи в `data/magics.json` разные, и раньше читались только две из
 * них (`_const`/`mul`) — поэтому у всей школы Света и Тьмы таблица была пустой:
 * у их заклинаний величина лежит в `effect` (проценты) или `stat` (плоская
 * прибавка). Пустой уровень (`false`) — заклинание на нём ещё недоступно.
 */
function levelValueHtml(sp: MagicRecord, lvlData: any): string {
  if (!lvlData) return '';    // уровня нет — строка остаётся с одним названием, без тире
  if (lvlData.text) return `<span class="lvl-dmg">${lvlData.text}</span>`;

  const label = LEVEL_VALUE_LABEL[sp.type || ''] || '';
  const parts: string[] = [];

  const base = lvlData._const ?? lvlData.cost;
  const mul = lvlData.mul ?? lvlData.mult;
  if (base !== undefined || mul !== undefined) {
    // Урон и счётные заклинания: величина = база + множитель × силу магии.
    // Часть значений в справочнике — заглушки ('?', '?600?'), и число из них не
    // достаётся: показываем как есть, это честное «в данных неизвестно».
    const num = (v: any): number | null => {
      if (typeof v === 'number') return v;
      const s = String(v).trim();
      return /^-?\d+(\.\d+)?$/.test(s) ? Number(s) : null;
    };
    const chunks: string[] = [];
    const b = num(base), m = num(mul);
    if (base !== undefined && (b === null || b !== 0)) chunks.push(b === null ? String(base) : String(b));
    if (mul !== undefined && (m === null || m !== 0)) chunks.push(`${m === null ? String(mul) : m}·СМ`);
    // Подпись величины ставится только там, где она однозначна: у `buff_SE`
    // формулой заданы разные вещи — у «Антимагии» защита, у «Телепорта»
    // дальность, и общее слово «эффективность» врало бы про половину из них.
    const withLabel = label && sp.type !== 'buff_SE' ? label + ': ' : '';
    if (chunks.length) parts.push(withLabel + chunks.join(' + '));
  }
  if (lvlData.effect !== undefined) {
    const v = lvlData.effect as number;
    // «Рассеивание» снимает 40% эффекта — это доля, а не прибавка, и «+40%»
    // читалось бы как усиление.
    const sign = v > 0 && sp.type !== 'buff_SE' ? '+' : '';
    parts.push(`${label ? label + ' ' : ''}${sign}${v}%`);
  }
  if (lvlData.stat !== undefined) {
    const v = lvlData.stat as number;
    parts.push(`${label ? label + ' ' : ''}${v > 0 ? '+' : ''}${v}`);
  }
  if (lvlData.step !== undefined) parts.push(`${lvlData.step} х. действия`);
  if (lvlData.atb !== undefined) parts.push(`отброс по ATB ${lvlData.atb}`);

  return parts.length ? `<span class="lvl-dmg">${parts.join(', ')}</span>` : '';
}

/** Формула заклинания типа `text`. В данных это HTML справки: оставляем только жирный, перенос и
 * иконки (их адреса идут через наш кэш), всё остальное — калькуляторы с полями и кнопками,
 * ссылки — отбрасываем. */
function spellFormulaHtml(sp: MagicRecord): string {
  const raw = (sp as any).text as string | undefined;
  if (!raw || /<input|<button|<select/i.test(raw)) return '';
  return raw
    .replace(/<img\b[^>]*>/gi, (tag: string) => {
      const src = /src="([^"]+)"/i.exec(tag)?.[1];
      const title = /title="([^"]*)"/i.exec(tag)?.[1] || '';
      return src ? `<img src="${cdnImg(src)}" alt="" title="${title}" class="formula-icon">` : '';
    })
    .replace(/<(?!\/?(?:b|br|img)\b)[^>]*>/gi, '');
}

function spellMana(sp: MagicRecord): number | null {
  if (SPELL_MANA_MAP[sp.sys] !== undefined) return SPELL_MANA_MAP[sp.sys];
  return sp.mana != null ? sp.mana : null;
}

function renderMagicCard(sp: MagicRecord): string {
  const iconUrl = magicIconUrl(sp);
  const mana = spellMana(sp);
  const element = ELEMENT_NAMES[sp.element] || (sp as any).elementRu || '';
  const level = spellLevel(sp);
  const schoolName = SCHOOL_META[spellSchool(sp)]?.nameRu || '';
  const desc = stripHtml((sp as any).descRu || sp.desc || '').trim();
  const eff = (sp as any).effect || (sp as any).eff || null;
  const massName = sp.sys ? ((allData.magics?.[MASS_COUNTERPARTS[sp.sys]] as any)?.nameRu || '') : '';
  const massNote = massName ? `<br><br>Есть массовая версия: ${massName}` : '';
  return `<div class="magic-card" onclick="navigateTo('/magics/${sp.sys || sp.name}')">
    <div class="magic-card-row">
      ${iconUrl ? `<img class="magic-icon" src="${iconUrl}" onerror="this.style.display='none'" loading="lazy">` : ''}
      <div class="magic-card-body">
        <div class="magic-card-header">
          <span class="name">${(sp as any).nameRu || sp.name}</span>
          <span class="level-badge">${level} ур.</span>
        </div>
        <div class="magic-card-tags">
          ${schoolName ? `<span class="school-tag">${schoolName}</span>` : ''}
${mana !== null ? `<span class="mana-tag"><img class="mana-icon" src="${MANA_ICON}"> ${mana}</span>` : ''}
          ${element ? `<span class="element-tag">${element}</span>` : ''}
          ${eff !== null ? `<span class="eff-tag">Эффект: ${eff}</span>` : ''}
        </div>
        ${desc || massNote ? `<div class="desc">${formatDescBase(desc)}${massNote}</div>` : ''}
      </div>
    </div>
  </div>`;
}

function renderElementalCard(): string {
  const elems = [
    { sys: 'summonel_f', label: 'Огонь' },
    { sys: 'summonel_e', label: 'Земля' },
    { sys: 'summonel_w', label: 'Вода' },
    { sys: 'summonel_a', label: 'Воздух' },
  ];
  const cells = elems.map(e => {
    const sp = allData.magics?.[e.sys];
    const url = sp ? magicIconUrl(sp) : '';
    const mana = sp ? spellMana(sp) : null;
    const eff = sp ? ((sp as any).effect || (sp as any).eff || null) : null;
    const desc = sp ? stripHtml((sp as any).descRu || sp.desc || '').trim() : '';
    return `<div class="elem-cell">
      ${url ? `<img class="elem-icon" src="${url}" onerror="this.style.display='none'" loading="lazy">` : ''}
      <div class="elem-cell-name">${sp ? ((sp as any).nameRu || sp.name || e.label) : e.label}</div>
      <div class="elem-cell-tags">
        ${mana !== null ? `<span class="mana-tag"><img class="mana-icon" src="//dcdn.heroeswm.ru/i/magic/mana.gif"> ${mana}</span>` : ''}
        ${eff !== null ? `<span class="eff-tag">${eff}</span>` : ''}
      </div>
      <div class="elem-cell-desc">${formatDesc(desc)}</div>
    </div>`;
  }).join('');
  return `<div class="magic-card elemental-card">
    <div class="magic-card-header" style="padding: 10px 14px; border-bottom: none;">
      <span class="name">Призыв элементалей</span>
      <span class="level-badge">4 ур.</span>
    </div>
    <div class="elem-grid">${cells}</div>
  </div>`;
}

function renderMagic(spells: MagicRecord[]): void {
  const container = document.getElementById('magic-list');
  const countEl = document.getElementById('magic-count');
  if (!container || !countEl) return;
  countEl.textContent = spells.length + ' заклинаний';

  const bySchool: Record<string, MagicRecord[]> = {};
  for (const sp of spells) {
    const s = spellSchool(sp);
    if (!bySchool[s]) bySchool[s] = [];
    bySchool[s].push(sp);
  }

  let html = '';
  for (const key of SCHOOL_ORDER) {
    const list = bySchool[key];
    if (!list || !list.length) continue;
    const meta = SCHOOL_META[key] || { nameRu: key, descRu: '' };

    const byLevel: Record<number, MagicRecord[]> = {};
    for (const sp of list) {
      const lvl = spellLevel(sp);
      if (!byLevel[lvl]) byLevel[lvl] = [];
      byLevel[lvl].push(sp);
    }

    const iconHtml = meta.icon ? `<img class="school-icon" src="${cdnImg(meta.icon)}" onerror="this.style.display='none'"> ` : '';
    html += `<div class="magic-school-section">
      <h3 class="magic-section-title">${iconHtml}${meta.nameRu}</h3>
      <p class="magic-school-desc">${meta.descRu}</p>`;

    for (let lvl = 1; lvl <= 5; lvl++) {
      const lvlSpells = byLevel[lvl];
      if (!lvlSpells || !lvlSpells.length) continue;
      let levelHtml = '';
      for (const sp of lvlSpells) {
        levelHtml += renderMagicCard(sp);
        if (key === 'summon' && lvl === 4 && sp.sys === 'summonel') {
          levelHtml += renderElementalCard();
        }
      }
      html += `<div class="magic-level-section">
        <h4 class="magic-level-title">${lvl} уровень</h4>
        ${levelHtml}
      </div>`;
    }

    html += `</div>`;
  }

  container.innerHTML = html;
}

function filterMagic(): void {
  const searchEl = document.getElementById('magic-search') as HTMLInputElement;
  const schoolEl = document.getElementById('school-filter') as HTMLSelectElement;
  if (!searchEl || !schoolEl || !allData.magics) return;
  
  const q = searchEl.value.toLowerCase();
  const school = schoolEl.value;
  // «Прочее» с этой страницы убрано: там лежали не заклинания книги героя, а
  // умения существ и построек — «Невидимость», «Соблазнение», «Прыжок»,
  // «Открытие врат», «Взрыв». Их место в разделе способностей.
  // Умения классов героев («Заколлованная стрела», «Надзор», «Поглощение
  // трупов») убраны по той же причине — см. HERO_ABILITIES.
  // «Армагеддон» на странице есть: в песочнице он кастуем (галочка
  // «Вся магия» снимает NOT_HERO_SPELLS), поэтому карточка честная.
  let list = Object.values(allData.magics).filter(sp => sp.sys !== 'mcurse'
    && spellSchool(sp) !== 'other' && !MASS_SPELLS.has(sp.sys) && !SUB_SPELLS.has(sp.sys)
    && !HERO_ABILITIES.has(sp.sys));
  if (school) list = list.filter(sp => (sp.school || '') === school);
  if (q) {
    list = list.filter(sp =>
      ((sp as any).nameRu || '').toLowerCase().includes(q) ||
      (sp.nameEn || '').toLowerCase().includes(q) ||
      ((sp as any).descRu || '').toLowerCase().includes(q)
    );
  }
  renderMagic(list);
}

function initMagic(): void {
  const sel = document.getElementById('school-filter') as HTMLSelectElement;
  if (!sel) return;
  for (const key of SCHOOL_ORDER) {
    const meta = SCHOOL_META[key];
    if (!meta) continue;
    const o = document.createElement('option');
    o.value = key;
    o.textContent = meta.nameRu;
    sel.appendChild(o);
  }
  // List render is lazy — navigation.ts TAB_RENDERERS runs filterMagic() on the tab's
  // first activation instead of at startup.
}

function openMagicModal(key: string): void {
  const sp = allData.magics?.[key];
  if (!sp) return;
  history.pushState(null, '', siteUrl('/magics/' + key));
  const modal = document.getElementById('magic-modal');
  if (!modal) return;
  modal.style.display = 'flex';
  const nameEl = document.getElementById('magic-modal-name');
  if (nameEl) nameEl.textContent = (sp as any).nameRu || sp.name || key;
  // Школа и уровень стоят в строке с маной (ниже), под названием остаётся только стихия.
  const schoolName = SCHOOL_META[spellSchool(sp)]?.nameRu || '';
  const lvl = spellLevel(sp);
  const element = ELEMENT_NAMES[sp.element] || '';
  const subParts: string[] = element ? [element] : [];
  const subEl = document.getElementById('magic-modal-sub');
  if (subEl) subEl.textContent = subParts.join(' · ');

  const iconUrl = magicIconUrl(sp);
  const iconContainer = document.getElementById('magic-modal-icon');
  if (iconContainer) {
    if (iconUrl) {
      iconContainer.innerHTML = '<img src="' + iconUrl + '" style="width:64px;height:64px;object-fit:contain" onerror="this.style.display=\'none\'">';
    } else {
      iconContainer.innerHTML = '';
    }
  }

  // Анимация заклинания — та же, что играет в бою. У части заклинаний своего
  // atlas'а нет (призывы, «Армагеддон», воскрешения — в оригинале тоже), тогда
  // блок остаётся скрытым, а не показывает пустой квадрат.
  const animEl = document.getElementById('magic-modal-anim');
  if (animEl) {
    const shown = mountSpellPreview(animEl, sp.sys);
    animEl.style.display = shown ? 'flex' : 'none';
  }

  let metaHtml = '';
  const mana = spellMana(sp);
  if (mana !== null) metaHtml += '<span><img src="' + MANA_ICON + '" style="width:14px;height:14px;vertical-align:middle"> ' + mana + '</span>';
  // Кличи стоят «ярости» (крови) и открываются залом: «Зал 17, БУ 3», а не «3 ур.» школы.
  if (sp.blood) metaHtml += '<span title="Ярость"><img src="' + BLOOD_ICON + '" style="width:14px;height:14px;vertical-align:middle"> ' + sp.blood + '</span>';
  const levelText = sp.blood && sp.blvl ? 'Зал ' + sp.blvl + ', БУ ' + lvl : (lvl ? lvl + ' ур.' : '');
  const schoolLevel = [schoolName, levelText].filter(Boolean).join(' · ');
  if (schoolLevel) metaHtml += '<span class="school-badge">' + schoolBadgeIcon(spellSchool(sp)) + schoolLevel + '</span>';
  const eff = (sp as any).effect || (sp as any).eff || null;
  if (eff !== null) metaHtml += '<span>Эффект: ' + eff + '</span>';
  const metaEl = document.getElementById('magic-modal-meta');
  if (metaEl) metaEl.innerHTML = metaHtml;

  const desc = stripHtml((sp as any).descRu || sp.desc || '');
  const massName = MASS_COUNTERPARTS[sp.sys] ? ((allData.magics?.[MASS_COUNTERPARTS[sp.sys]] as any)?.nameRu || '') : '';
  const massNote = massName ? '<br><br><span style="color:var(--gold)">✦ Есть массовая версия: ' + massName + '</span>' : '';
  const descEl = document.getElementById('magic-modal-desc');
  if (descEl) descEl.innerHTML = formatDesc(desc) + massNote;

  let levelsHtml = '';
  if (Array.isArray(sp.levels) && sp.levels.length) {
    // Четыре записи — это уровни ВЛАДЕНИЯ школой, а не уровни заклинания
    // (уровень самого заклинания один, он в бейдже рядом с названием).
    // Ступени владения: без школы → основы → сильная → искусная магия.
    const MASTERY_NAMES = ['Без школы', 'Основы', 'Сильная магия', 'Искусная магия'];
    levelsHtml = '<div style="font-size:13px;font-weight:600;color:var(--gold);margin-bottom:8px">Параметры заклинания</div>';
    sp.levels.forEach(function(lvlData: any, i: number) {
      const masteryName = MASTERY_NAMES[i] || (i + 1 + ' ур. школы');
      const manaCost = lvlData && (lvlData.mana || lvlData.mana_cost) || '';
      levelsHtml += '<div class="magic-level-row">' +
        '<span class="lvl-label">' + masteryName + '</span>' +
        (manaCost ? '<span class="lvl-mana">🧪 ' + manaCost + '</span>' : '') +
        levelValueHtml(sp, lvlData) +
      '</div>';
    });
  }
  // Заклинания типа text (кличи и др.) считают эффект формулой словами, таблицы уровней у них нет.
  const formula = spellFormulaHtml(sp);
  if (!levelsHtml && formula) {
    levelsHtml = '<div style="font-size:13px;font-weight:600;color:var(--gold);margin-bottom:8px">Параметры заклинания</div>' +
      '<div class="magic-level-row magic-formula">' + formula + '</div>';
  }
  const levelsEl = document.getElementById('magic-modal-levels');
  if (levelsEl) levelsEl.innerHTML = levelsHtml;

  const infoEl = document.getElementById('magic-modal-info');
  if (infoEl) {
    const info = ((sp as any).infoRu || sp.info || '').trim();
    if (info) {
      infoEl.innerHTML = '<b style="color:var(--text)">Дополнительно:</b><br>' + formatDesc(info);
      infoEl.style.display = 'block';
    } else {
      infoEl.style.display = 'none';
    }
  }
}

function closeMagicModal(): void {
  const modal = document.getElementById('magic-modal');
  if (modal) modal.style.display = 'none';
  // Закрытая карточка не должна крутить кадры в фоне: объект снимается с общего
  // цикла анимации, стейдж уничтожается.
  destroySpellPreview();
}

document.getElementById('magic-modal')?.addEventListener('click', function(e) {
  if (e.target === this) {
    closeMagicModal();
    if (appPath().startsWith('/magics/')) {
      history.pushState(null, '', siteUrl('/book_of_magic'));
    }
  }
});

