/** Заклятые враги эльфа: линии существ для выбора и набор uID для боя.
 *
 * Выбор живёт в браузере (конструктор на странице эльфов): {герой: {«фракция:класс»: уровень существ}}.
 * В бой уходит набор uID существ выбранных линий; по ним движок и бросает двойной урон
 * (`hero.favoured_units`). Пустой набор — крита нет: не выбраны цели, нет и шанса. */

export const FAV_STORE_KEY = 'fav-enemies-v1';

type Line = Record<string, string[]>;

/** Все существа линии уровня: базовое, улучшенное и альтернативное улучшение (ключи 0, 1, 2). */
export function lineUnits(line: Line | undefined): string[] {
  const out: string[] = [];
  for (const k of ['0', '1', '2']) for (const sys of line?.[k] || []) if (!out.includes(sys)) out.push(sys);
  return out;
}

/** uID существ выбранных линий героя (0 или 1); пусто, если ничего не выбрано. */
export function favoredUnitIds(heroIdx: number, factions: Record<string, any> | undefined, units: Record<string, any> | undefined): number[] {
  let store: Record<string, Record<string, number>> = {};
  try { store = JSON.parse(localStorage.getItem(FAV_STORE_KEY) || '{}'); } catch { return []; }
  const chosen = store[String(heroIdx)] || {};
  const ids = new Set<number>();
  for (const [rowKey, tier] of Object.entries(chosen)) {
    const faction = rowKey.split(':')[0];
    for (const sys of lineUnits(factions?.[faction]?.unitsTable?.[String(tier)])) {
      const uid = Number(units?.[sys]?.uID);
      if (uid) ids.add(uid);
    }
  }
  return [...ids].sort((a, b) => a - b);
}
