/**
 * Команды игрока в бою: типизированный контракт клиент → движок.
 *
 * feature-melee-contract/task-001. Зеркало Python-контракта
 * (battle/commands.py): поля команды ближней атаки совпадают по смыслу
 * с TaC-словарём сервера, и расхождение между сторонами ловится
 * тестами (web/tests/actionTypes.test.js ↔ tests/test_attack_command_contract.py).
 *
 * Команда — односторонний контракт (клиент шлёт, движок проверяет).
 * Тип фиксирует ФОРМУ; целевую семантику (живой враг, досягаемость)
 * проверяет сервер перед исполнением.
 */

/** Клетка сетки как [x, y]. */
export type Cell = [number, number];

/** Поля команды обычной атаки; навес имеет отдельный контракт. */
export const ATTACK_COMMAND_FIELDS = [
  'type', 'target_idx', 'move_to', 'no_return', 'melee', 'aim',
] as const;

/** Команда ближней атаки (type: 'attack', цель — стек target_idx). */
export interface MeleeAttackCommand {
  type: 'attack';
  /** Индекс стека-цели (живой враг атакующего). */
  target_idx: number;
  /** Клетка подхода; null/undefined = бить с места / сервер выбирает. */
  move_to?: Cell | null;
  /** Shift: «Удар и возврат» не срабатывает, отряд остаётся у цели. */
  no_return?: boolean;
  /** Тот же Shift у стрелка: подойти и ударить мечом вместо выстрела. */
  melee?: boolean;
  /** Клетка следа цели, по которой пришёлся удар (клик): у дыханий и
   * «Сглаза» определяет клетку «за целью» (см. zones.behind_cells). */
  aim?: Cell;
}

/** Является ли значение валидной клеткой [x, y]. */
export function isCell(value: unknown): value is Cell {
  return Array.isArray(value) && value.length === 2
    && Number.isInteger(value[0]) && Number.isInteger(value[1]);
}

/** Валидация формы команды ближней атаки (без целевой семантики). */
export function isMeleeAttackCommand(value: unknown): value is MeleeAttackCommand {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return false;
  const raw = value as Record<string, unknown>;
  if (Object.keys(raw).some((key) => !ATTACK_COMMAND_FIELDS.includes(key as typeof ATTACK_COMMAND_FIELDS[number]))) return false;
  if (raw.type !== 'attack') return false;
  if (!Number.isInteger(raw.target_idx) || (raw.target_idx as number) < 0) return false;
  if (raw.move_to !== undefined && raw.move_to !== null && !isCell(raw.move_to)) return false;
  if (raw.no_return !== undefined && typeof raw.no_return !== 'boolean') return false;
  if (raw.melee !== undefined && typeof raw.melee !== 'boolean') return false;
  if (raw.aim !== undefined && !isCell(raw.aim)) return false;
  return true;
}

/** Собрать команду ближней атаки из уже проверенных полей. */
export function attackCommand(
  targetIdx: number,
  opts: { move_to?: Cell | null; no_return?: boolean; melee?: boolean; aim?: Cell } = {},
): MeleeAttackCommand {
  if (!Number.isInteger(targetIdx) || targetIdx < 0) {
    throw new TypeError('target_idx must be a non-negative integer');
  }
  if (opts.move_to !== undefined && opts.move_to !== null && !isCell(opts.move_to)) {
    throw new TypeError('move_to must be [x, y] with integer coordinates');
  }
  if (opts.aim !== undefined && !isCell(opts.aim)) {
    throw new TypeError('aim must be [x, y] with integer coordinates');
  }
  const cmd: MeleeAttackCommand = { type: 'attack', target_idx: targetIdx };
  if (opts.move_to !== undefined) cmd.move_to = opts.move_to;
  if (opts.no_return !== undefined) {
    if (typeof opts.no_return !== 'boolean') {
      throw new TypeError('no_return must be a boolean');
    }
    cmd.no_return = opts.no_return;
  }
  if (opts.melee !== undefined) {
    if (typeof opts.melee !== 'boolean') {
      throw new TypeError('melee must be a boolean');
    }
    cmd.melee = opts.melee;
  }
  if (opts.aim !== undefined) cmd.aim = opts.aim;
  return cmd;
}