// Вкладка «Статистика»: что реализовано в движке, как он угадывает настоящие
// бои, баланс классов оригинала по уровням, чем воюют в приложении и что
// лежит в корпусе реальных боёв.
//
// Всё считает сервер (/api/stats/*): покрытие — по исходникам и реестрам,
// журнал запусков — data/usage.db, корпус и баланс — data/battles.db.
// Рукописных цифр здесь нет: они устарели бы на первой правке.
import { allData } from './data.js';
import { navigateTo } from './navigation.js';
import { harvestHtml, initHarvest } from './stats_harvest.js';
import { bindCharts, chartCard, esc, num, type Row } from './stats_charts.js';

/* eslint-disable @typescript-eslint/no-explicit-any */
type Json = any;

var _loaded = false;
var _balanceLevel = 0;
var _activeTab = 'engine';

function pct(x: number | null | undefined, digits = 0): string {
  return x == null || isNaN(x) ? '—' : (x * 100).toFixed(digits) + '%';
}

async function getJson(url: string): Promise<Json> {
  var res = await fetch(url);
  var data = await res.json().catch(function() { return {}; });
  if (!res.ok) throw new Error(data && data.error ? data.error : 'HTTP ' + res.status);
  return data;
}

function unitName(sys: string): string {
  var u = allData.units && allData.units[sys];
  return (u && u.nameRu) || sys;
}

function abilityName(key: string): string {
  var a = allData.abilities && allData.abilities[key];
  return (a && a.name) || key;
}

function spellName(key: string): string {
  var m = allData.magics && allData.magics[key];
  return (m && m.name) || key;
}

function artifactName(key: string): string {
  var list: any = allData.artifacts;
  var a = Array.isArray(list) ? list.find(function(x: any) { return x.key === key; }) : list && list[key];
  return (a && a.name) || key;
}

function factionName(key: string | null): string {
  if (!key) return 'без фракции';
  var f = allData.factions && allData.factions[key];
  return (f && f.nameRu) || key;
}


function section(id: string, title: string, note = ''): string {
  return '<section class="stats-section" id="' + id + '"><h2>' + esc(title) + '</h2>' +
    (note ? '<p class="stats-note">' + note + '</p>' : '') +
    '<div class="stats-body"><div class="stats-empty">Загрузка…</div></div></section>';
}

function setBody(id: string, html: string): void {
  var el = document.querySelector('#' + id + ' .stats-body');
  if (el) {
    el.innerHTML = html;
    el.classList.remove('loading');
  }
}

function fail(id: string, e: unknown): void {
  setBody(id, '<div class="stats-empty">Не удалось загрузить: ' + esc((e as Error)?.message || e) + '</div>');
}

function kpi(value: string, label: string, tone = ''): string {
  return '<div class="stats-kpi' + (tone ? ' ' + tone : '') + '"><b>' + value + '</b><span>' + esc(label) + '</span></div>';
}

/** Полоска доли: заполненная часть — доля, подпись — «сделано из всего». */
function meter(label: string, done: number, total: number, detail = ''): string {
  var share = total ? done / total : 0;
  return '<div class="stats-meter"><div class="stats-meter-head"><span>' + esc(label) + '</span><b>' +
    (share * 100).toFixed(share === 1 ? 0 : 1) + '%</b></div><div class="stats-bar"><i style="width:' +
    (share * 100).toFixed(1) + '%"></i></div><div class="stats-meter-foot"><span>' + num(done) + ' из ' + num(total) +
    '</span></div>' + (detail ? '<div class="stats-meter-detail">' + detail + '</div>' : '') + '</div>';
}

function cards(list: string[]): string {
  return '<div class="stats-cards">' + list.join('') + '</div>';
}

function top(rows: Array<[string, number, string?]>, id: string, title: string, unit: string, extra: object = {}): string {
  var data: Row[] = rows.map(function(r) { return { label: r[0], value: r[1], href: r[2] }; });
  return chartCard(data, Object.assign({ id: id, title: title, unit: unit }, extra) as any);
}

function renderCoverage(c: Json): void {
  var ab = c.abilities, cr = c.creatures, pk = c.perks, sp = c.spells, fc = c.factions;
  var pkGroups = pk.groups || {};
  var gaps: string[] = [];
  if (pkGroups.unsupported && pkGroups.unsupported.length) {
    gaps.push('<b>Навыки героя, которые движок пока не умеет:</b> <code>' + pkGroups.unsupported.map(esc).join('</code> <code>') + '</code>');
  }
  if (pkGroups.unknown && pkGroups.unknown.length) {
    gaps.push('<b>Неизвестные движку навыки:</b> <code>' + pkGroups.unknown.map(esc).join('</code> <code>') + '</code>');
  }
  if (sp.missing && sp.missing.length) {
    gaps.push('<b>Заклинания без исполнения:</b> ' + sp.missing.map(function(k: string) { return esc(spellName(k)); }).join(', '));
  }
  if (ab.missingKeys && ab.missingKeys.length) {
    gaps.push('<b>Способности без кода:</b> ' + ab.missingKeys.map(function(k: string) { return esc(abilityName(k)); }).join(', '));
  }
  var counts = ab.counts || {};
  setBody('stats-coverage',
    '<div class="stats-meters">' +
    meter('Способности существ', ab.implemented, ab.total,
      'реестр эффектов ' + num(counts.registry || 0) + ' · ядро движка ' + num(counts.core || 0) + ' · вне боя ' + num(counts.non_battle || 0)) +
    meter('Существа', cr.ready, cr.total, 'все способности существа реализованы') +
    meter('Навыки героя', pk.implemented, pk.total, 'ещё ' + num((pkGroups.out_of_battle || []).length) + ' действуют только вне боя') +
    meter('Заклинания', sp.implemented, sp.total, 'магия героя ' + num(sp.hero) + ' · умения существ ' + num(sp.creature)) +
    meter('Фракционные способности', fc.implemented, fc.total, 'механики вне боя считаются закрытыми') +
    '</div>' +
    (gaps.length ? '<div class="stats-gaps">' + gaps.map(function(g) { return '<div>' + g + '</div>'; }).join('') + '</div>' : ''));
}

function renderAccuracy(d: Json): void {
  var acc: Json[] = d.accuracy || [];
  var best = acc.reduce(function(m: Json, a: Json) { return !m || a.accuracy > m.accuracy ? a : m; }, null);
  var rows = acc.map(function(a: Json) {
    return '<tr><td>' + esc(a.label) + '</td><td class="num">' + num(a.battles) + '</td><td class="num"><b>' +
      pct(a.accuracy, 1) + '</b></td><td class="num">' + (a.brier == null ? '—' : a.brier.toFixed(3)) +
      '</td><td class="stats-dim"><code>' + esc(a.engine) + '</code> · ' + esc(a.date) + '</td></tr>';
  }).join('');
  var cls = d.classes || {};
  var clsRows = (cls.classes || []).map(function(c: Json) {
    var diff = c.engine - c.balance;
    return '<tr><td>' + esc(className(c.label)) + '</td><td class="num">' + num(c.sides) + '</td><td class="num">' +
      pct(c.real) + '</td><td class="num">' + pct(c.engine) + '</td><td class="num">' + pct(c.balance) +
      '</td><td class="num ' + (Math.abs(diff) >= 0.15 ? 'stats-bad' : '') + '">' +
      (diff >= 0 ? '+' : '') + (diff * 100).toFixed(0) + '%</td></tr>';
  }).join('');
  var table = function(head: string, body: string) {
    return '<div class="stats-scroll"><table class="stats-table"><thead>' + head + '</thead><tbody>' + body + '</tbody></table></div>';
  };
  setBody('stats-accuracy',
    (best ? '<div class="stats-kpis">' + kpi(pct(best.accuracy, 1), 'угадан победитель', 'good') +
      kpi(best.brier == null ? '—' : best.brier.toFixed(3), 'Brier (0.25 — монетка)') + kpi(num(best.battles), 'боёв в прогоне') + '</div>' : '') +
    (rows ? table('<tr><th>Бои</th><th class="num">Прогнано</th><th class="num">Угадано</th><th class="num">Brier</th><th>Версия движка</th></tr>', rows) : '') +
    '<p class="stats-note">Brier — средний квадрат ошибки вероятности: чем меньше, тем лучше.</p>' +
    (clsRows
      ? '<h3>Классы ГТ: доля побед</h3>' + table('<tr><th>Класс</th><th class="num">Сторон</th><th class="num">Реально</th>' +
        '<th class="num">Движок</th><th class="num">Баланс оригинала</th><th class="num">Движок − баланс</th></tr>', clsRows) +
        '<p class="stats-note">Красным — расхождение 15% и больше: там ошибка механики класса, а не случайность выборки.</p>'
      : ''));
}

function renderCorpusUnits(d: Json): void {
  var units = d.units || {};
  var rows = function(list: Json[]): Array<[string, number, string]> {
    return (list || []).map(function(r: Json) { return [unitName(r.unit), r.battles, '/units/' + r.unit] as [string, number, string]; });
  };
  setBody('stats-corpus', cards([
    top(rows(units.gl), 'corpus-gl', 'Чаще всего в ГЛ', 'боёв'),
    top(rows(units.gt), 'corpus-gt', 'Чаще всего в ГТ', 'боёв'),
  ]));
}

function renderUsage(u: Json): void {
  if (!u.runs) {
    setBody('stats-usage', '<div class="stats-empty">Журнал пуст: запусков боёв ещё не было. ' +
      'Каждый новый бой (симуляция или пошаговый) попадёт сюда.</div>');
    return;
  }
  var since = u.first ? new Date(u.first * 1000).toLocaleDateString('ru-RU') : '—';
  var modes = u.modes || {};
  var modeNames: Record<string, string> = { simulate: 'симуляция', session: 'пошаговый с ИИ', hotseat: 'хотсит' };
  var pairs = function(list: Json[], name: (k: string) => string, path: string): Array<[string, number, string]> {
    return (list || []).map(function(r: Json) { return [name(r[0]), r[1], '/' + path + '/' + r[0]] as [string, number, string]; });
  };
  var all: string[] = [
    top((u.factions || []).map(function(r: Json) {
      return [factionName(r.faction === '?' ? null : r.faction), r.sides, r.faction !== '?' ? '/factions/' + r.faction : undefined];
    }), 'use-factions', 'Фракции существ', 'сторон', { types: ['donut', 'hbar', 'table'], type: 'donut' }),
    top((u.heroFactions || []).map(function(r: Json) {
      return [factionName(r.faction) + (r.alt ? ' (альт.)' : ''), r.heroes];
    }), 'use-heroes', 'Фракции героев', 'героев', { types: ['donut', 'hbar', 'table'], type: 'donut' }),
    top((u.units || []).map(function(r: Json) { return [unitName(r.unit), r.runs, '/units/' + r.unit]; }), 'use-units', 'Существа', 'боёв'),
    top(pairs(u.abilities, abilityName, 'abilities'), 'use-abilities', 'Способности в бою', 'боёв'),
    top((u.perks || []).map(function(r: Json) { return [r[0], r[1]]; }), 'use-perks', 'Навыки героя', 'героев'),
    top(pairs(u.spells, spellName, 'magics'), 'use-spells', 'Заклинания в книге', 'героев'),
    top(pairs(u.artifacts, artifactName, 'artifacts'), 'use-artifacts', 'Артефакты', 'героев'),
    top((u.days || []).slice().reverse().map(function(r: Json) { return [String(r.day).slice(5), r.runs]; }), 'use-days', 'По дням', 'боёв',
      { types: ['column', 'hbar', 'table'], type: 'column', ordered: true, top: 0 }),
  ].filter(function(h) { return h.indexOf('sc-empty') < 0; });
  setBody('stats-usage',
    '<div class="stats-kpis">' + kpi(num(u.runs), 'боёв с ' + since) +
    Object.keys(modes).map(function(m) { return kpi(num(modes[m]), modeNames[m] || m); }).join('') +
    kpi(num(u.unitsUsed), 'разных существ') + '</div>' + cards(all));
}

function cellColor(share: number): string {
  // 30% и меньше — красный, 50% — нейтральный, 70% и больше — зелёный.
  var t = Math.max(-1, Math.min(1, (share - 0.5) / 0.2));
  return t >= 0 ? 'rgba(70,170,90,' + (0.12 + 0.6 * t).toFixed(2) + ')'
    : 'rgba(210,70,60,' + (0.12 + 0.6 * -t).toFixed(2) + ')';
}

/** «тёмный эльф 2 (r106)» → «Темный эльф-укротитель»; без справочника — «Тёмный эльф · альт. класс». */
function className(label: string): string {
  // Настоящие названия классов — из справочника фракций (иконка rNNN → «Тёмный эльф-укротитель»).
  var code = /\((r\d+)\)\s*$/.exec(String(label || ''));
  if (code) {
    var found = classNames()[code[1]];
    if (found) return found;
  }
  var m = /^(.*?)(?:\s+(\d+))?\s*(?:\(r\d+\))?\s*$/.exec(String(label || ''));
  var name = m ? m[1] : String(label);
  name = name.charAt(0).toUpperCase() + name.slice(1);
  var n = m && m[2] ? parseInt(m[2], 10) : 1;
  return n > 1 ? name + ' · альт. класс' + (n > 2 ? ' ' + n : '') : name;
}

var _classNames: Record<string, string> | null = null;
function classNames(): Record<string, string> {
  if (_classNames) return _classNames;
  var map: Record<string, string> = {};
  var fs: any = allData.factions || {};
  Object.keys(fs).forEach(function(k) {
    ((fs[k] as any).classes || []).forEach(function(c: Json) {
      var m = /\/(r\d+)\.png/.exec(c.icon || '');
      if (m && c.nameRu) map[m[1]] = c.nameRu;
    });
  });
  if (Object.keys(map).length) _classNames = map;
  return map;
}

/** Порядок и иконки классов — как на daily.heroeswm.ru/gt/balance. */
const CLASS_ORDER = ['r1', 'r2', 'r3', 'r4', 'r5', 'r6', 'r7', 'r8', 'r9', 'r10',
  'r101', 'r102', 'r103', 'r104', 'r105', 'r205', 'r106', 'r107', 'r108', 'r109'];

function classIcon(cls: string): string {
  return '/api/img?url=' + encodeURIComponent('https://dcdn.heroeswm.ru/i/f/' + cls + '.png');
}

var _balOwn: string[] = [];
var _balOpp: string[] = [];
var _balCells: 'pct' | 'abs' = 'pct';
var _balSrc: 'site' | 'engine' | 'diff' = 'site';
var _balData: Json = null;

function chips(group: 'own' | 'opp', order: string[], labels: Record<string, string>, picked: string[]): string {
  return '<div class="stats-chips" data-group="' + group + '"><button type="button" data-cls="" class="' + (picked.length ? '' : 'on') + '">все</button>' +
    order.map(function(c) {
      return '<button type="button" data-cls="' + c + '" class="' + (picked.indexOf(c) >= 0 ? 'on' : '') + '" title="' + esc(className(labels[c])) +
        '" aria-label="' + esc(className(labels[c])) + '"><img src="' + classIcon(c) + '" alt=""></button>';
    }).join('') + '</div>';
}

function diffColor(d: number): string {
  // + (движок ставит строку выше оригинала) — синий, − — оранжевый; ±25 п.п. и больше — насыщенный.
  var t = Math.max(-1, Math.min(1, d / 0.25));
  return t >= 0 ? 'rgba(74,163,223,' + (0.1 + 0.6 * t).toFixed(2) + ')' : 'rgba(224,138,60,' + (0.1 + 0.6 * -t).toFixed(2) + ')';
}

function signed(d: number, digits = 0): string {
  return (d >= 0 ? '+' : '−') + Math.abs(d * 100).toFixed(digits);
}

interface Cell { v: number; text: string; sub: string; color: string; title: string; }

function renderBalance(b: Json): void {
  _balData = b;
  var levels: number[] = b.levels || [];
  var pills = '<div class="stats-pills" role="group" aria-label="Уровень">' + levels.map(function(l) {
    return '<button type="button" data-level="' + l + '" class="' + (l === _balanceLevel ? 'on' : '') + '">' + (l ? l : 'все') + '</button>';
  }).join('') + '</div>';
  if (!b.snapshot) {
    setBody('stats-balance', pills + '<div class="stats-empty">Снимка баланса нет. Скачать: ' +
      '<code>.venv/bin/python scripts/harvest_battles.py balance</code></div>');
    return;
  }
  var eng: Json = b.engine;
  var hasEng = !!(eng && eng.pairs && eng.pairs.length);
  var src = hasEng ? _balSrc : 'site';
  var classes: Json[] = b.classes || [];
  var labels: Record<string, string> = {};
  classes.forEach(function(c) { labels[c.cls] = c.label; });
  var present = classes.map(function(c) { return c.cls; });
  var order = CLASS_ORDER.filter(function(c) { return present.indexOf(c) >= 0; })
    .concat(present.filter(function(c) { return CLASS_ORDER.indexOf(c) < 0; }));
  var name = function(c: string) { return className(labels[c] || c); };
  var pairs: Record<string, Json> = {}, epairs: Record<string, Json> = {};
  (b.pairs || []).forEach(function(p: Json) { pairs[p.own + '|' + p.opp] = p; });
  (hasEng ? eng.pairs : []).forEach(function(p: Json) { epairs[p.own + '|' + p.opp] = p; });
  var own = _balOwn.filter(function(c) { return order.indexOf(c) >= 0; });
  var opp = _balOpp.filter(function(c) { return order.indexOf(c) >= 0; });
  var rowsOf = own.length ? order.filter(function(c) { return own.indexOf(c) >= 0; }) : order;
  var colsOf = opp.length ? order.filter(function(c) { return opp.indexOf(c) >= 0; }) : order;
  var abs = _balCells === 'abs';

  /** Клетка выбранного источника: оригинал / движок / разница. */
  var cell = function(r: string, o: string): Cell | null {
    var sp = pairs[r + '|' + o], ep = epairs[r + '|' + o];
    var pair = name(r) + ' против ' + name(o);
    if (src === 'site') {
      if (!sp || !sp.total) return null;
      var sh = sp.wins / sp.total;
      return { v: sh, text: String(Math.round(sh * 100)), sub: num(sp.wins) + '/' + num(sp.total), color: cellColor(sh),
        title: pair + ': ' + sp.wins + ' из ' + sp.total };
    }
    if (src === 'engine') {
      if (!ep || !ep.n) return null;
      return { v: ep.p, text: String(Math.round(ep.p * 100)), sub: ep.n + ' боёв', color: cellColor(ep.p),
        title: pair + ': движок даёт ' + (ep.p * 100).toFixed(0) + '% по ' + ep.n + ' реальным боям' };
    }
    if (!sp || !sp.total || !ep || !ep.n) return null;
    var d = ep.p - sp.wins / sp.total;
    return { v: d, text: signed(d), sub: pct(ep.p) + ' / ' + pct(sp.wins / sp.total), color: diffColor(d),
      title: pair + ': движок ' + (ep.p * 100).toFixed(0) + '%, оригинал ' + (sp.wins / sp.total * 100).toFixed(0) + '% (по ' + ep.n + ' боям движка)' };
  };

  /** Итог класса по показанным соперникам: оригинал, автопрогоны движка и его точность. */
  var siteRows: Row[] = [], engRows: Row[] = [], accRows = '';
  rowsOf.forEach(function(r) {
    var sw = 0, st = 0, en = 0, ep = 0, ea = 0, eb = 0;
    colsOf.forEach(function(o) {
      var sp = pairs[r + '|' + o], e = epairs[r + '|' + o];
      if (sp && sp.total) { sw += sp.wins; st += sp.total; }
      if (e && e.n) { en += e.n; ep += e.p * e.n; ea += e.acc * e.n; eb += e.brier * e.n; }
    });
    if (st) siteRows.push({ label: name(r), value: sw / st, note: 'из ' + num(st), icon: classIcon(r) });
    if (en) {
      engRows.push({ label: name(r), value: ep / en, note: 'угадал ' + pct(ea / en) + ' · ' + num(en) + ' боёв', icon: classIcon(r) });
      accRows += '<tr><td><img class="sc-ico" src="' + classIcon(r) + '" alt="">' + esc(name(r)) + '</td><td class="num">' + num(en) +
        '</td><td class="num">' + (st ? pct(sw / st, 1) : '—') + '</td><td class="num">' + pct(ep / en, 1) +
        '</td><td class="num"><b>' + pct(ea / en, 1) + '</b></td><td class="num">' + (eb / en).toFixed(3) + '</td></tr>';
    }
  });
  var head = '<tr><th class="corner">против →</th>' + colsOf.map(function(c) {
    return '<th class="col" title="' + esc(name(c)) + '"><img class="sc-ico" src="' + classIcon(c) + '" alt="' + esc(name(c)) + '"></th>';
  }).join('') + '<th class="col total">Всего</th></tr>';
  var example = '';
  var body = rowsOf.map(function(r) {
    var tsum = 0, tn = 0, ssum = 0, esum = 0;
    var cells = colsOf.map(function(o) {
      var c = cell(r, o);
      if (!c) return '<td class="stats-mx-empty"></td>';
      var sp = pairs[r + '|' + o], ep = epairs[r + '|' + o];
      if (src === 'site') { tsum += sp.wins; tn += sp.total; }
      else if (src === 'engine') { tsum += ep.p * ep.n; tn += ep.n; }
      else { tsum += c.v; tn += 1; ssum += sp.wins / sp.total; esum += ep.p; }
      if (!example && r !== o && src === 'site' && sp.total >= 100) {
        example = '<b>' + esc(name(r)) + '</b> против <b>' + esc(name(o)) + '</b>: ' + c.text +
          ' — из ' + num(sp.total) + ' дуэлей ' + num(sp.wins) + ' выиграл ' + esc(name(r)) + '.';
      }
      return '<td style="background:' + c.color + '" title="' + esc(c.title) + '">' +
        (abs ? '<small>' + esc(c.sub) + '</small><br>' : '') + c.text + (abs && src !== 'diff' ? '%' : '') + '</td>';
    }).join('');
    var total = '<td class="stats-mx-empty"></td>';
    if (tn) {
      if (src === 'diff') {
        var dd = (esum - ssum) / tn;
        total = '<td class="total" style="background:' + diffColor(dd) + '">' + signed(dd) + '</td>';
      } else {
        var v = tsum / tn;
        total = '<td class="total" style="background:' + cellColor(v) + '">' + (abs ? '<small>' + num(Math.round(tsum)) + '/' + num(tn) + '</small><br>' : '') +
          Math.round(v * 100) + (abs ? '%' : '') + '</td>';
      }
    }
    return '<tr><th title="' + esc(name(r)) + '"><img class="sc-ico" src="' + classIcon(r) + '" alt="">' + esc(name(r)) + '</th>' + cells + total + '</tr>';
  }).join('');

  var seg = function(id: string, label: string, hint: string) {
    return '<button type="button" data-src="' + id + '" title="' + esc(hint) + '" class="' + (src === id ? 'on' : '') + '">' + label + '</button>';
  };
  var srcRow = hasEng
    ? '<div class="stats-frow"><span>Матрица</span><div class="stats-pills">' +
      seg('site', 'Оригинал', 'Реальные дуэли с daily.heroeswm.ru') + seg('engine', 'Наш движок', 'Что выдают автопрогоны движка по тем же боям') +
      seg('diff', 'Сравнение', 'Движок минус оригинал') + '</div></div>' : '';
  var filterNote = (own.length || opp.length)
    ? ' Показано: свои — ' + (own.length ? own.map(name).join(', ') : 'все') + '; чужие — ' + (opp.length ? opp.map(name).join(', ') : 'все') + '.' : '';
  var kpis = hasEng
    ? '<div class="stats-kpis">' + kpi(pct(eng.accuracy, 1), 'движок угадал победителя', 'good') + kpi(eng.brier.toFixed(3), 'Brier (0.25 — монетка)') +
      kpi(num(eng.battles), 'боёв в автопрогонах') + '</div>' : '';
  var pctFmt = function(v: number) { return pct(v, 1); };
  var chartOpts = { unit: '% побед', types: ['hbar', 'column', 'table'] as any, top: 0, max: 1, mark: 0.5, fmt: pctFmt };
  var vs = opp.length ? 'против выбранных «чужих»' : 'против всех';
  var top = kpis + cards([
    chartCard(siteRows, Object.assign({ id: 'bal-win', title: 'Оригинал: доля побед класса (ГТ)', hint: vs }, chartOpts)),
    hasEng ? chartCard(engRows, Object.assign({ id: 'bal-eng', title: 'Наши автопрогоны: доля побед класса', hint: vs + ' · подпись — как часто движок угадал исход' }, chartOpts)) : '',
  ]) + (hasEng && accRows
    ? '<h3>Точность движка по классам</h3><div class="stats-scroll"><table class="stats-table"><thead><tr><th>Класс</th><th class="num">Боёв</th>' +
      '<th class="num">Оригинал</th><th class="num">Наш движок</th><th class="num">Угадано</th><th class="num">Brier</th></tr></thead><tbody>' + accRows +
      '</tbody></table></div><p class="stats-note">«Угадано» — доля боёв, где движок дал победителю больше 50%. Строка — класс героя; бои, где он встречался с выбранными соперниками.</p>' : '');
  var legend: Record<string, string> = {
    site: 'Число на пересечении — процент побед <b>строки</b> над столбцом в настоящих дуэлях. 50 — силы равны; ' +
      '<span class="stats-lg stats-lg-good">зелёное</span> — строка сильнее, <span class="stats-lg stats-lg-bad">красное</span> — слабее. ',
    engine: 'Число на пересечении — сколько раз из ста <b>строка</b> побеждает <b>столбец</b> по автопрогонам нашего движка: он заново играет настоящие бои ГТ ' +
      '(по 10 прогонов на бой) и выдаёт вероятность победы. Цвета те же: <span class="stats-lg stats-lg-good">зелёное</span> — строка сильнее. ' +
      'Боёв на пару немного, наведите на клетку — увидите их число. ',
    diff: 'Число — на сколько процентных пунктов наш движок ставит <b>строку</b> выше (+) или ниже (−), чем настоящие дуэли оригинала. ' +
      '<span class="stats-lg stats-lg-up">Синее</span> — движок переоценивает класс, <span class="stats-lg stats-lg-down">оранжевое</span> — недооценивает. ' +
      'Чем светлее клетка, тем точнее движок повторяет оригинал. ',
  };
  setBody('stats-balance', pills +
    '<p class="stats-note">Оригинал: дуэли ' + esc(b.period ? b.period[0] + ' — ' + b.period[1] : '') + ', снимок ' + esc(b.snapshot) +
    ', всего <b>' + num(b.battles) + '</b> боёв. Обновление: <code>harvest_battles.py balance</code>.' +
    (hasEng ? ' Наш движок: <code>' + esc(eng.engine) + '</code>, прогнано <b>' + num(eng.battles) + '</b> реальных боёв ГТ' + (_balanceLevel ? ' этого уровня' : '') + '.' : '') +
    '</p><div class="stats-filterbox">' + srcRow +
    '<div class="stats-frow"><span>Свои</span>' + chips('own', order, labels, own) + '</div>' +
    '<div class="stats-frow"><span>Чужие</span>' + chips('opp', order, labels, opp) + '</div>' +
    (src === 'diff' ? '' : '<div class="stats-frow"><span>Клетки</span><div class="stats-pills"><button type="button" data-cells="pct" class="' + (abs ? '' : 'on') +
      '">проценты</button><button type="button" data-cells="abs" class="' + (abs ? 'on' : '') + '">' +
      (src === 'engine' ? 'проценты и число боёв' : 'победы / бои и %') + '</button></div></div>') + '</div>' +
    top +
    '<h3>Класс против класса</h3>' +
    '<div class="stats-howto"><b>Как читать.</b> Строка слева — класс героя, столбец сверху — его соперник. ' + legend[src] +
    'Колонка «Всего» — итог строки против всех показанных соперников. Пустая клетка — данных нет; клетки с малым числом боёв ненадёжны. ' +
    'Классы с добавкой («Рыцарь света», «Темный эльф-укротитель») — альтернативные классы той же фракции. Иконки и порядок — как на daily.heroeswm.ru/gt/balance.' +
    (example ? '<br>Пример: ' + example : '') + filterNote + '</div>' +
    (rowsOf.length && colsOf.length
      ? '<div class="stats-matrix-wrap"><table class="stats-matrix' + (abs && src !== 'diff' ? ' abs' : '') + '">' + head + body + '</table></div>'
      : '<div class="stats-empty">Нет данных для выбранных классов.</div>'));
}

async function loadBalance(): Promise<void> {
  var body = document.querySelector('#stats-balance .stats-body') as HTMLElement | null;
  if (body) body.classList.add('loading');
  try { renderBalance(await getJson('/api/stats/balance?level=' + _balanceLevel)); }
  catch (e) { fail('stats-balance', e); }
}

function bindLinks(root: HTMLElement): void {
  root.addEventListener('click', function(ev) {
    var t = ev.target as HTMLElement;
    var a = t.closest('a[data-href]') as HTMLElement | null;
    if (a && a.dataset.href && !(ev as MouseEvent).metaKey && !(ev as MouseEvent).ctrlKey) {
      ev.preventDefault();
      navigateTo(a.dataset.href);
      return;
    }
    var pill = t.closest('button[data-level]') as HTMLElement | null;
    if (pill) {
      _balanceLevel = parseInt(pill.dataset.level as string, 10) || 0;
      void loadBalance();
      return;
    }
    var chip = t.closest('.stats-chips button') as HTMLElement | null;
    if (chip) {
      var grp = (chip.closest('.stats-chips') as HTMLElement).dataset.group;
      var cls = chip.dataset.cls as string;
      var cur = grp === 'own' ? _balOwn : _balOpp;
      var next = !cls ? [] : cur.indexOf(cls) >= 0 ? cur.filter(function(c) { return c !== cls; }) : cur.concat(cls);
      if (grp === 'own') _balOwn = next; else _balOpp = next;
      renderBalance(_balData);
      return;
    }
    var srcBtn = t.closest('button[data-src]') as HTMLElement | null;
    if (srcBtn) {
      _balSrc = srcBtn.dataset.src as 'site' | 'engine' | 'diff';
      renderBalance(_balData);
      return;
    }
    var cells = t.closest('button[data-cells]') as HTMLElement | null;
    if (cells) {
      _balCells = cells.dataset.cells === 'abs' ? 'abs' : 'pct';
      renderBalance(_balData);
      return;
    }
    var tab = t.closest('button[data-stab]') as HTMLElement | null;
    if (tab) showTab(root, tab.dataset.stab as string);
  });
}

const TABS: Array<[string, string]> = [
  ['engine', 'Движок'], ['balance', 'Баланс ГТ'], ['usage', 'В приложении'], ['corpus', 'Корпус боёв'],
];

function showTab(root: HTMLElement, id: string): void {
  if (!TABS.some(function(t) { return t[0] === id; })) id = 'engine';
  _activeTab = id;
  try { localStorage.setItem('stats.tab', id); } catch { /* ignore */ }
  root.querySelectorAll('[data-stab]').forEach(function(b) {
    var on = (b as HTMLElement).dataset.stab === id;
    b.classList.toggle('on', on);
    b.setAttribute('aria-selected', String(on));
  });
  root.querySelectorAll('[data-spanel]').forEach(function(p) {
    (p as HTMLElement).hidden = (p as HTMLElement).dataset.spanel !== id;
  });
}

async function initStats(): Promise<void> {
  var root = document.getElementById('stats-root');
  if (!root || _loaded) return;
  _loaded = true;
  try { _activeTab = localStorage.getItem('stats.tab') || _activeTab; } catch { /* ignore */ }
  var panel = function(id: string, html: string) { return '<div class="stats-panel" data-spanel="' + id + '" role="tabpanel">' + html + '</div>'; };
  root.innerHTML =
    '<nav class="stats-tabs" role="tablist">' + TABS.map(function(t) {
      return '<button type="button" role="tab" data-stab="' + t[0] + '">' + t[1] + '</button>';
    }).join('') + '</nav>' +
    panel('engine',
      section('stats-coverage', 'Что реализовано в движке',
        'По коду и реестрам. «Есть в коде» ещё не значит «работает как в игре» — это видно ниже.') +
      section('stats-accuracy', 'Точность на настоящих боях', 'Последний большой прогон движка по корпусу: угадал ли он победителя.')) +
    panel('balance', section('stats-balance', 'Баланс классов ГТ',
      'Настоящие дуэли гильдии тактиков (daily.heroeswm.ru/gt/balance) и то, что выдают автопрогоны нашего движка по тем же боям.')) +
    panel('usage', section('stats-usage', 'Бои в приложении', 'Журнал запусков: симуляции и пошаговые бои.')) +
    panel('corpus',
      section('stats-harvest', 'Загрузка боёв',
        'Сколько боёв ГЛ и ГТ скачано, сколько места занимают, какие фракции чаще. Кнопки запускают загрузку с daily.heroeswm.ru.') +
      section('stats-corpus', 'Что воюет в корпусе', 'База data/battles.db: самые частые существа в собранных боях.'));
  bindLinks(root);
  bindCharts(root);
  showTab(root, _activeTab);
  setBody('stats-harvest', harvestHtml());
  initHarvest(root);

  getJson('/api/stats/coverage').then(renderCoverage).catch(function(e) { fail('stats-coverage', e); });
  getJson('/api/stats/usage').then(renderUsage).catch(function(e) { fail('stats-usage', e); });
  void loadBalance();
  getJson('/api/stats/corpus').then(function(d) { renderAccuracy(d); renderCorpusUnits(d); }).catch(function(e) {
    fail('stats-accuracy', e);
    fail('stats-corpus', e);
  });
}

export { initStats };
