// Раздел «Загрузка боёв» вкладки «Статистика»: сколько боёв ГЛ и ГТ в базе, сколько
// места они занимают, какие фракции чаще, диаграммы и кнопки запуска загрузки с daily.
//
// Данные отдаёт /api/stats/harvest*, запуск — POST /api/stats/harvest/start|stop
// (процесс scripts/harvest_battles.py на сервере, только с локальной машины).
import { allData } from './data.js';
import { chartCard, esc, num, type Row } from './stats_charts.js';

/* eslint-disable @typescript-eslint/no-explicit-any */
type Json = any;

var _famKind: 'gt' | 'gl' = 'gt';
var _famLevel = 0;
var _famFmt = 'all';
var _pollTimer: number | null = null;
var _overview: Json = null;

function bytes(n: number): string {
  if (n >= 1 << 30) return (n / (1 << 30)).toFixed(2) + ' ГБ';
  if (n >= 1 << 20) return (n / (1 << 20)).toFixed(1) + ' МБ';
  if (n >= 1 << 10) return (n / (1 << 10)).toFixed(0) + ' КБ';
  return n + ' Б';
}

async function getJson(url: string, init?: RequestInit): Promise<Json> {
  var res = await fetch(url, init);
  var data = await res.json().catch(function() { return {}; });
  if (!res.ok) throw new Error(data && data.error ? data.error : 'HTTP ' + res.status);
  return data;
}

function el(id: string): HTMLElement | null { return document.getElementById(id); }

function factionLabel(key: string): string {
  if (key === '?') return 'без фракции';
  var f = allData.factions && allData.factions[key];
  return (f && f.nameRu) || key;
}

function groupLabel(g: Json): string {
  if (g.kind === 'gl_daily') return 'ГЛ · ежедневные';
  if (g.kind === 'gl_kit') return 'ГЛ · наборы';
  return g.format === '2v2' ? 'ГТ · парные 2×2' : 'ГТ · дуэли';
}

function controls(kind: 'gl' | 'gt', title: string, defaults: { days: number; limit: number }): string {
  return '<div class="stats-job" data-job="' + kind + '"><h3>' + esc(title) + '</h3>' +
    '<div class="stats-job-form"><label>за последние дней <input type="number" min="1" max="400" value="' + defaults.days +
    '" data-field="days"></label><label>скачать не больше боёв <input type="number" min="1" max="20000" value="' +
    defaults.limit + '" data-field="limit"></label>' +
    '<button class="stats-btn" data-action="start">Загрузить</button></div>' +
    '<div class="stats-job-state" data-role="state">Не запускалась.</div>' +
    '<pre class="stats-job-log" data-role="log" hidden></pre></div>';
}

function renderJobs(jobs: Json): void {
  var running = false;
  (['gl', 'gt'] as const).forEach(function(kind) {
    var root = document.querySelector('.stats-job[data-job="' + kind + '"]');
    if (!root) return;
    var j = jobs[kind];
    var state = root.querySelector('[data-role="state"]') as HTMLElement;
    var log = root.querySelector('[data-role="log"]') as HTMLElement;
    var start = root.querySelector('[data-action="start"]') as HTMLButtonElement;
    var setBtn = function(running: boolean) {
      start.dataset.action = running ? 'stop' : 'start';
      start.textContent = running ? 'Остановить' : 'Загрузить';
      start.classList.toggle('stats-btn-stop', running);
      start.disabled = false;
    };
    if (!j) { setBtn(false); return; }
    var names: Record<string, string> = { running: 'идёт', done: 'готово', error: 'ошибка', stopped: 'остановлена' };
    var title = j.steps[j.step] || '';
    state.innerHTML = '<b class="stats-job-' + esc(j.state) + '">' + esc(names[j.state] || j.state) + '</b> · шаг ' +
      (j.step + 1) + ' из ' + j.steps.length + ': ' + esc(title) + ' · с ' + new Date(j.started * 1000).toLocaleTimeString('ru-RU');
    log.hidden = !j.log.length;
    var atEnd = log.scrollTop + log.clientHeight >= log.scrollHeight - 8;
    log.textContent = j.log.join('\n');
    if (atEnd) log.scrollTop = log.scrollHeight;
    setBtn(j.state === 'running');
    if (j.state === 'running') running = true;
  });
  if (running && _pollTimer == null) _pollTimer = window.setInterval(pollJobs, 3000);
  if (!running && _pollTimer != null) {
    window.clearInterval(_pollTimer);
    _pollTimer = null;
    void loadAll(true);   // загрузка закончилась — цифры изменились
  }
}

async function pollJobs(): Promise<void> {
  try { renderJobs(await getJson('/api/stats/harvest/jobs')); } catch { /* сервер перезапускается */ }
}

function bindJobs(root: HTMLElement): void {
  root.addEventListener('click', async function(ev) {
    var btn = (ev.target as HTMLElement).closest('button[data-action]') as HTMLButtonElement | null;
    var job = btn && (btn.closest('.stats-job') as HTMLElement | null);
    if (!btn || !job) return;
    var kind = job.dataset.job as string;
    var field = function(n: string) { return parseInt((job!.querySelector('[data-field="' + n + '"]') as HTMLInputElement).value, 10); };
    btn.disabled = true;
    try {
      var body: Json = btn.dataset.action === 'start'
        ? { kind: kind, days: field('days'), limit: field('limit') } : { kind: kind };
      await getJson('/api/stats/harvest/' + btn.dataset.action, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
    } catch (e) {
      var st = job.querySelector('[data-role="state"]') as HTMLElement;
      st.textContent = 'Не удалось: ' + ((e as Error).message || e);
    }
    await pollJobs();
  });
}

function renderOverview(o: Json): void {
  _overview = o;
  var groups: Json[] = o.groups || [];
  var ok = function(f: (g: Json) => boolean) { return groups.filter(f).reduce(function(s, g) { return s + g.ok; }, 0); };
  var pending = groups.reduce(function(s, g) { return s + g.pending; }, 0);
  var closed = groups.reduce(function(s, g) { return s + g.other; }, 0);
  var gl = ok(function(g) { return g.kind.indexOf('gl') === 0; });
  var gtDuel = ok(function(g) { return g.kind === 'gt' && g.format === 'duel'; });
  var gt2 = ok(function(g) { return g.kind === 'gt' && g.format === '2v2'; });
  var span = o.span || {};
  var kpi = function(v: string, l: string, id = '') {
    return '<div class="stats-kpi"' + (id ? ' id="' + id + '"' : '') + '><b>' + v + '</b><span>' + l + '</span></div>';
  };
  var span2 = function(s: Json) { return s && s.first ? s.first + ' — ' + s.last : '—'; };
  el('stats-harvest-summary')!.innerHTML =
    '<div class="stats-kpis">' + kpi(num(gl), 'боёв ГЛ') + kpi(num(gtDuel), 'дуэлей ГТ') + kpi(num(gt2), 'парных 2×2') +
    kpi(num(pending), 'ждут скачивания') + kpi(num(closed), 'закрыто / ошибка') + kpi('…', 'на диске', 'stats-harvest-disk-kpi') + '</div>' +
    '<p class="stats-note">Даты боёв: ГЛ ' + esc(span2(span.gl)) + ' · ГТ ' + esc(span2(span.gt)) + '.' +
    (gt2 ? '' : ' Парных 2×2 в базе нет: сборщик берёт только дуэли ГТ.') + '</p>';
  var levelRows = function(kind: string): Row[] {
    return ((o.levels && o.levels[kind]) || []).map(function(r: Json) { return { label: String(r.level), value: r.battles }; });
  };
  el('stats-harvest-charts')!.innerHTML = '<div class="stats-cards">' +
    chartCard(groups.filter(function(g) { return g.ok; }).map(function(g) { return { label: groupLabel(g), value: g.ok }; }),
      { id: 'h-kinds', title: 'Что скачано', unit: 'боёв', types: ['donut', 'hbar', 'table'], type: 'donut' }) +
    chartCard((o.daily || []).map(function(d: Json) { return { label: d.day.slice(5), value: d.gl + d.gt, parts: [d.gl, d.gt] }; }),
      { id: 'h-daily', title: 'По дням', unit: 'боёв', hint: 'последние 45', types: ['column', 'hbar', 'table'], ordered: true, top: 0, series: ['ГЛ', 'ГТ'] }) +
    chartCard(levelRows('gl'), { id: 'h-lvl-gl', title: 'ГЛ по уровням', unit: 'боёв', types: ['column', 'hbar', 'donut', 'table'], type: 'column', ordered: true, top: 0 }) +
    chartCard(levelRows('gt'), { id: 'h-lvl-gt', title: 'ГТ по уровням', unit: 'боёв', types: ['column', 'hbar', 'donut', 'table'], type: 'column', ordered: true, top: 0 }) +
    '<article class="sc-card" id="stats-harvest-disk"><header><h3>Место на диске</h3></header><div class="sc-body"><div class="sc-empty">Считаю… (до полуминуты)</div></div></article></div>';
}

function renderStorage(s: Json): void {
  var tot = s.files.db;
  var k = el('stats-harvest-disk-kpi');
  if (k) k.innerHTML = '<b>' + bytes(tot) + '</b><span>база data/battles.db</span>';
  var box = el('stats-harvest-disk');
  if (!box) return;
  box.outerHTML = chartCard([
    { label: 'ГЛ · логи боёв', value: s.gl.bytes }, { label: 'ГТ · логи боёв', value: s.gt.bytes },
    { label: 'Отряды, списки, билды, индексы', value: s.other }],
  { id: 'h-disk', title: 'Место на диске', unit: 'размер', types: ['donut', 'hbar', 'table'], type: 'donut', fmt: bytes,
    hint: 'сжатый бой: ГЛ ' + bytes(s.perBattle.gl) + ', ГТ ' + bytes(s.perBattle.gt) + ' · WAL ' + bytes(s.files.wal) }).replace('<article ', '<article id="stats-harvest-disk" ');
}

function famControls(): string {
  var levels = ((_overview && _overview.levels && _overview.levels[_famKind]) || []) as Json[];
  return '<div class="stats-filters"><label>Вид <select id="fam-kind"><option value="gt">ГТ — классы героев</option>' +
    '<option value="gl">ГЛ — фракции существ</option></select></label>' +
    '<label>Уровень <select id="fam-level"><option value="0">все</option>' +
    levels.map(function(l) { return '<option value="' + l.level + '">' + l.level + '</option>'; }).join('') + '</select></label>' +
    (_famKind === 'gt' ? '<label>Формат <select id="fam-fmt"><option value="all">все</option><option value="duel">дуэли</option>' +
      '<option value="2v2">2×2</option></select></label>' : '') + '</div>';
}

async function loadFactions(): Promise<void> {
  var box = el('stats-harvest-factions');
  if (!box) return;
  box.innerHTML = famControls() + '<div id="fam-chart" class="stats-empty">Загрузка…</div>';
  (el('fam-kind') as HTMLSelectElement).value = _famKind;
  (el('fam-level') as HTMLSelectElement).value = String(_famLevel);
  var fmt = el('fam-fmt') as HTMLSelectElement | null;
  if (fmt) fmt.value = _famFmt;
  (el('fam-kind') as HTMLSelectElement).onchange = function() {
    _famKind = (el('fam-kind') as HTMLSelectElement).value as 'gl' | 'gt'; _famLevel = 0; void loadFactions();
  };
  (el('fam-level') as HTMLSelectElement).onchange = function() {
    _famLevel = parseInt((el('fam-level') as HTMLSelectElement).value, 10) || 0; void loadFactions();
  };
  if (fmt) fmt.onchange = function() { _famFmt = fmt!.value; void loadFactions(); };
  try {
    var d = await getJson('/api/stats/harvest/factions?kind=' + _famKind + '&level=' + _famLevel + '&fmt=' + _famFmt);
    var items: Row[] = d.items.map(function(i: Json) {
      return { label: d.kind === 'gt' ? i.label : factionLabel(i.faction), value: i.sides };
    });
    (el('fam-chart') as HTMLElement).className = '';
    (el('fam-chart') as HTMLElement).innerHTML = chartCard(items, { id: 'h-fam-' + d.kind, title: d.kind === 'gt' ? 'Классы героев' : 'Фракции существ',
      unit: d.unit, types: ['hbar', 'donut', 'column', 'table'], top: 10 });
  } catch (e) {
    (el('fam-chart') as HTMLElement).textContent = 'Не удалось загрузить: ' + ((e as Error).message || e);
  }
}

async function loadAll(refresh = false): Promise<void> {
  try { renderOverview(await getJson('/api/stats/harvest')); }
  catch (e) { el('stats-harvest-summary')!.innerHTML = '<div class="stats-empty">Не удалось загрузить: ' + esc((e as Error).message) + '</div>'; return; }
  void loadFactions();
  getJson('/api/stats/harvest/storage').then(renderStorage).catch(function(e) {
    var box = el('stats-harvest-disk');
    if (box) box.innerHTML = '<header><h3>Место на диске</h3></header><div class="sc-empty">' + esc((e as Error).message) + '</div>';
  });
  if (refresh) void pollJobs();
}

/** Каркас раздела; вызывается из stats.ts после того, как внутри `.stats-body` появилось место. */
export function harvestHtml(): string {
  return '<div class="stats-jobs">' + controls('gl', 'Загрузить бои ГЛ', { days: 3, limit: 1000 }) +
    controls('gt', 'Загрузить дуэли ГТ', { days: 3, limit: 2000 }) + '</div>' +
    '<p class="stats-note">Скрипт <code>scripts/harvest_battles.py</code> запускается на сервере: сначала списки боёв за ' +
    'период, потом скачивание логов (идёт в фоне, страницу можно закрыть). Работает только с этого компьютера.</p>' +
    '<div id="stats-harvest-summary"><div class="stats-empty">Загрузка…</div></div>' +
    '<div id="stats-harvest-charts"></div>' +
    '<h3 class="stats-h3">Какие фракции чаще</h3><div id="stats-harvest-factions"></div>';
}

export function initHarvest(root: HTMLElement): void {
  bindJobs(root);
  void loadAll();
  void pollJobs();
}
