/**
 * Предупреждение на разделах, которых нет у опубликованного справочника.
 *
 * Флаг `window.HWM_STATIC` ставит сборщик статического сайта
 * (scripts/build_static_site.py) — тем же приёмом, каким сервер ставит
 * `HWM_LOCAL_ONLY`. Каталог на статике полон, а бой и реплеи считает Python:
 * без сервера их не будет.
 *
 * Без этой подсказки расстановка армий выглядит рабочей ровно до нажатия «в
 * бой», после чего в статусе появляется невнятное «Недоступно в статической
 * версии сайта» — и непонятно, сломался сайт или так задумано.
 */

/**
 * Куда вешать подсказку. Для боя это НЕ сам `#tab-battle`: он flex-строка
 * (поле, палитры, панель противника), и лишний ребёнок встал бы четвёртой
 * колонкой, сплющив доску. Внутри боковой панели — обычный блочный поток.
 */
const NOTICES: { selector: string; fallback: string; text: string }[] = [
  {
    selector: '#tab-battle .tac-sidebar',
    fallback: 'tab-battle',
    text: 'Бой считает сервер — на веб-версии его нет. '
      + 'Расставить армию и поделиться расстановкой по ссылке можно, но начать бой не выйдет.',
  },
  {
    selector: '#tab-replay',
    fallback: 'tab-replay',
    text: 'Реплеи разбирает Python-сервер: он скачивает и парсит страницу боя '
      + 'с heroeswm.ru. На опубликованном справочнике этого нет.',
  },
];

export function initStaticNotice(): void {
  if (!(window as unknown as { HWM_STATIC?: boolean }).HWM_STATIC) return;
  for (const notice of NOTICES) {
    const host = document.querySelector(notice.selector)
      || document.getElementById(notice.fallback);
    if (!host || host.querySelector('.static-notice')) continue;
    const box = document.createElement('div');
    box.className = 'static-notice';
    box.textContent = 'ℹ️ ' + notice.text;
    host.prepend(box);
  }
}
