/**
 * Всплывающее окно артефакта при наведении (Примерочная): название, уровень, прочность, ОА, модификаторы и
 * прибавки по уровню героя — по образцу подсказки оригинала. Элемент помечается `data-art="<ключ>"`.
 */
import { activeHero, artLevelValues, findArt, fittingHeroes } from './fitting.js';
import { ICON_BASE, MODIFIER_ICONS, MODIFIER_LABELS, isPctModifier } from './artifacts.js';

let tip: HTMLDivElement | null = null;
let curKey = '';

function esc(t: string): string {
  return t.replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' } as Record<string, string>)[c]);
}

function labelOf(key: string): string {
  return key === 'oa' ? 'ОА' : (MODIFIER_LABELS[key] || key);
}

function iconOf(key: string): string {
  return key === 'oa' ? 'attr_oa.png' : (MODIFIER_ICONS[key] || '');
}

export function artTipHtml(key: string, heroIdx?: number): string {
  const a: any = findArt(key);
  if (!a) return '';
  // Параметры уже с учётом БУ героя (как в превью оригинала): база + прибавки по уровню.
  const hero = fittingHeroes[heroIdx ?? activeHero] || fittingHeroes[0];
  const extra = artLevelValues(a, Number(hero.level) || 0);
  const vals: Record<string, number> = {};
  for (const k of Object.keys(a.modifiers || {})) vals[k] = Number(a.modifiers[k]) || 0;
  for (const k of Object.keys(extra)) if (k !== 'oa') vals[k] = (vals[k] || 0) + extra[k];
  const oa = (Number(a.oa) || 0) + (extra.oa || 0);
  const dur = a.durability ? '<div>Прочность: ' + a.durability + '/' + a.durability + '</div>' : '';
  const mods = Object.keys(vals).filter(k => vals[k]).map(k =>
    '<div class="art-tip-mod">' + (iconOf(k) ? '<img src="' + ICON_BASE + iconOf(k) + '" alt="">' : '') + '<span>' + esc(labelOf(k)) + ': ' + (vals[k] > 0 ? '' : '') + vals[k] + (k === 'muf' || isPctModifier(k) ? '%' : '') + '</span></div>').join('');
  return '<div class="art-tip-name">' + esc(a.name || a.nameRu || key) + '</div>' +
    (a.level ? '<div>Уровень: ' + a.level + '</div>' : '') + dur +
    (oa ? '<div>ОА: ' + oa + '</div>' : '') +
    (mods ? '<div class="art-tip-sep">Модификаторы:</div>' + mods : '');
}

function place(e: MouseEvent): void {
  if (!tip) return;
  const pad = 14, w = tip.offsetWidth, h = tip.offsetHeight;
  let x = e.clientX + pad, y = e.clientY + pad;
  if (x + w > window.innerWidth - 8) x = e.clientX - w - pad;
  if (y + h > window.innerHeight - 8) y = window.innerHeight - h - 8;
  tip.style.left = Math.max(8, x) + 'px';
  tip.style.top = Math.max(8, y) + 'px';
}

function hide(): void {
  curKey = '';
  if (tip) { tip.remove(); tip = null; }
}

export function initArtTips(): void {
  document.addEventListener('mouseover', (e: MouseEvent) => {
    const el = (e.target as Element | null)?.closest?.('[data-art]') as HTMLElement | null;
    if (!el) { if (curKey) hide(); return; }
    const key = el.dataset.art || '';
    if (key === curKey && tip) { place(e); return; }
    const html = artTipHtml(key, el.dataset.hero !== undefined ? Number(el.dataset.hero) : undefined);
    if (!html) { hide(); return; }
    hide();
    curKey = key;
    tip = document.createElement('div');
    tip.className = 'art-tip';
    tip.innerHTML = html;
    document.body.appendChild(tip);
    place(e);
  });
  document.addEventListener('mousemove', e => { if (tip) place(e); });
  document.addEventListener('mouseleave', hide);
  document.addEventListener('click', hide, true);
}
