      if(typeof o.name==='string')h.name=o.name;
      if(Number(o.faction)>0)h.faction=Number(o.faction);
      if(Number(o.level)>=1&&Number(o.level)<=24)h.level=Number(o.level);
      if(o.alloc&&typeof o.alloc==='object')h.alloc=o.alloc;
