// ===== АДРЕС: /dressroom/<герой 1>/<герой 2> =====
//
// Код героя — id артефактов по порядку слотов, по 2 символа base62 (`0-9a-zA-Z`, как на сайте):
// `5ifv5d5b5c5j5h5e5f` — девять предметов. Регистр важен. Id сайта = наш id − 10 (сверено по
// комплекту «Имперский»: `5i` = imp_ring, `5d` = imp_helmet, `5b` = imp_amul …), поэтому ссылки
// с сайта открываются здесь. Наши id < 10 (`~` + 1 символ) в формат сайта не ложатся. Герой 2 —
// второй сегмент адреса; пустой герой 1 пишется `_`. Крафт, самоцветы, фракция и БУ в адрес не входят.

var B62 = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
var SITE_ID_OFFSET = 10;
function encId(id: number): string {
  var n = id - SITE_ID_OFFSET;
  if (n < 0) return '~' + B62[id];
  return B62[Math.floor(n / 62) % 62] + B62[n % 62];
}
function artById(): Record<number, ArtifactRecord> {
  var m: Record<number, ArtifactRecord> = {};
  allArts().forEach(function(a) { var n = Number((a as any).id); if (a && !isNaN(n)) m[n] = a; });
  return m;
}

/** Код одеяния одного героя. */
export function encodeHero(h: FittingHero): string {
  var out = '';
  for (var i = 0; i < SLOT_DOLL.length; i++) {
    var a = h.equipment[SLOT_DOLL[i][0]], n = a ? Number((a as any).id) : NaN;
    if (a && !isNaN(n)) out += encId(n);
  }
  return out;
}
/** Адресная часть: `<герой 1>` или `<герой 1>/<герой 2>`. Пусто — героев никто не одевал. */
export function encodeBuild(): string {
  var c1 = encodeHero(fittingHeroes[0]), c2 = encodeHero(fittingHeroes[1]);
  return c2 ? (c1 || '_') + '/' + c2 : c1;
}

/** Предметы по коду героя. Незнакомый id и обрывки молча пропускаются. */
export function decodeHero(code: string): ArtifactRecord[] {
  var map = artById(), out: ArtifactRecord[] = [], i = 0;
  while (i < code.length) {
    var n: number;
    if (code[i] === '_') { i++; continue; }
    if (code[i] === '~') { n = B62.indexOf(code[i + 1] || ''); i += 2; }
    else { var hi = B62.indexOf(code[i]), lo = B62.indexOf(code[i + 1] || ''); n = hi < 0 || lo < 0 ? -1 : hi * 62 + lo + SITE_ID_OFFSET; i += 2; }
    if (n >= 0 && map[n]) out.push(map[n]);
  }
  return out;
}

/** Одеть героев из кода адреса (`<герой 1>/<герой 2>`). Возвращает false, если кода нет. */
export function loadFromCode(code: string): boolean {
  code = (code || '').trim();
  if (!code || !/^[0-9a-zA-Z_~/]+$/.test(code)) return false;
  var parts = code.split('/');
  for (var hi = 0; hi < HERO_COUNT; hi++) {
    var h = fittingHeroes[hi];
    h.equipment = {}; h.gems = {}; h.craft = {};
    var decoded=decodeHero(parts[hi] || '');
    // Код адреса не хранит БУ: если в нём предметы выше текущего уровня, уровень поднимается до них.
    decoded.forEach(function(a) { if((Number(a.level)||0)>h.level) h.level=Number(a.level); });
    decoded.forEach(function(a) { putArt(h, a); });
  }
  _pendingCode = '';
  syncUrl();
  if (document.getElementById('fit-doll-0')) { renderAll(); renderPane(); }
  return true;
}

/** Код из адреса при заходе по /dressroom/<код>: читается сразу при загрузке модуля, пока
 *  ничто не успело переписать адрес, и применяется, когда комната построена. */
