/** Параметры, которые можно улучшать очками. */
var ALLOC_KEYS: string[] = ['attack','defence','spellpower','knowledge'];

/** Очки образования: «Начальное/Среднее/Высшее образование» (колесо навыков героя) — по одному очку за каждый
 *  4-й / 3-й / 2-й уровень героя; ступени одного навыка заменяют друг друга (берётся высшая). */
var FACTION_KEYS: string[] = ['','knight','necromance','magi','elf','barbarian','telf','demon','dwarf','stepbarbarian','faraon'];

function educationPoints(i: number, level: number): number {
  var b: {faction?: string, perks?: string[]}|null=null;
  try{b=(window as any).swGetBattleBuild?(window as any).swGetBattleBuild(i):null}catch(e){b=null}
  // Колесо собрано для конкретного класса: чужой набор навыков герою не принадлежит.
  if(b&&b.faction&&b.faction!==FACTION_KEYS[(Number(fittingHeroes[i]&&fittingHeroes[i].faction)||0)%100])b=null;
  var rank=0;
  (b&&b.perks||[]).forEach(function(p){var m=/^enlightenment([123])$/.exec(p);if(m)rank=Math.max(rank,Number(m[1]))});
  var step=rank===3?2:rank===2?3:rank===1?4:0;
  return step?Math.floor(level/step):0;
}

/** Всего очков героя: по одному за каждый уровень начиная со 2-го (на 15-м — 14) плюс образование. */
function allocTotal(h: FittingHero, i: number): number {
  var lv=Number(h.level)||0;
  return Math.max(0,lv-1)+educationPoints(i,lv);
}
function allocSpent(h: FittingHero): number {
  var n=0;for(var k=0;k<ALLOC_KEYS.length;k++)n+=h.alloc[ALLOC_KEYS[k]]||0;return n;
}
/** Лишнее (после смены уровня или навыков) срезается с последних по списку параметров. */
function fixAlloc(h: FittingHero, i: number): void {
  var over=allocSpent(h)-allocTotal(h,i);
  for(var k=ALLOC_KEYS.length-1;k>=0&&over>0;k--){
    var key=ALLOC_KEYS[k],cut=Math.min(h.alloc[key]||0,over);
    if(cut){h.alloc[key]-=cut;over-=cut}
  }
}
/** Прибавки к параметрам от распределённых очков — для боя (в итоги артефактов не входят). */
export function fittingAllocTotals(i: number): Record<string, number> {
  var h=fittingHeroes[i]||fittingHeroes[0];fixAlloc(h,i);
  var out: Record<string, number>={};ALLOC_KEYS.forEach(function(k){out[k]=h.alloc[k]||0});return out;
}
export function onAlloc(i: number, key: string, delta: number): void {
  var h=fittingHeroes[i];
  if(delta>0&&allocSpent(h)>=allocTotal(h,i))return;
  if(delta<0&&!(h.alloc[key]>0))return;
  h.alloc[key]=(h.alloc[key]||0)+delta;
  renderEffects();
}
export function onAllocReset(i: number): void {fittingHeroes[i].alloc={};renderEffects()}

