/** Empties every doll slot ("снять всё" button on the original). */
export function clearDoll(i?: number): void {
  var h=fittingHero(i);
  for(var k=0;k<SLOT_DOLL.length;k++){delete h.equipment[SLOT_DOLL[k][0]];delete h.craft[SLOT_DOLL[k][0]];delete h.gems[SLOT_DOLL[k][0]]}
  renderAll();
}
export function remSlot(s: string, i?: number): void {
  var h=fittingHero(i);delete h.equipment[s];delete h.gems[s];delete h.craft[s];
  renderAll();
}

function renderAll(): void { renderDoll(); renderEffects(); renderPane(); renderCraftPanel(); }

// ===== ПРАВАЯ ПАНЕЛЬ: числа =====

interface HeroResult {
  totals: Record<string, number>;
  specs: string[];
  setC: Record<string, number>;
  extraNum: Record<string, {label: string, sum: number, pct: boolean}>;
  craftItems: Array<{art: ArtifactRecord, craft?: Craft}>;
}

/** Комплекты с одинаковой таблицей бонусов — одно семейство и считаются вместе: «Зверобоя» и «Лесной»
 *  (Остриё леса из рюкзака идёт в зачёт Зверобоя: с ним набирается 10 предметов). Ключ семейства —
 *  наименьший id среди комплектов с той же непустой таблицей. */
function setGroup(id: number): number {
  if(!fittingSets||!fittingSets[id])return id;
  var sig=JSON.stringify(fittingSets[id].bonuses);
  if(sig==='{}')return id;
  var best=id;
  for(var k in fittingSets){var n=Number(k);if(n<best&&JSON.stringify(fittingSets[k].bonuses)===sig)best=n}
  return best;
}

/** Прибавки артефакта по уровню героя (`level_modifiers`): {параметр: значение}, включая `oa`. */
export function artLevelValues(art: ArtifactRecord, level: number): Record<string, number> {
  var out: Record<string, number>={};
  var lm=art.level_modifiers;if(!lm)return out;
  for(var lk in lm){
    var lr=lm[lk] as {step?: number, per?: number, tiers?: Array<{from?: number, to?: number, value?: number}>},lv=0;
    if(Number(lr.step)>0)lv+=Math.floor(level/Number(lr.step))*(Number(lr.per)||0);
    if(lr.tiers)for(var ti=0;ti<lr.tiers.length;ti++){var tr=lr.tiers[ti];if(level>=(tr.from||0)&&level<=(tr.to||1e6))lv+=Number(tr.value)||0}
    if(lv)out[lk]=lv;
  }
  return out;
}

/** Параметры героя: фракция + предметы + самоцветы + крафт. Без DOM. */
function heroTotals(h: FittingHero, withFaction = true): HeroResult {
  var totals: Record<string, number>={};for(var i=0;i<FITTING_STATS.length;i++)totals[FITTING_STATS[i]]=0;
  var specs: string[]=[],setC: Record<string, number>={};
  var extraNum: Record<string, {label: string, sum: number, pct: boolean}>={};
  var craftItems: Array<{art: ArtifactRecord, craft?: Craft}>=[];
  var fb=withFaction?(FITTING_FACTION[h.faction]||{}):{};
  if(withFaction)ALLOC_KEYS.forEach(function(ak){totals[ak]+=h.alloc[ak]||0});
  for(var bk in fb)if(FITTING_STATS.indexOf(bk)!==-1)totals[bk]+=fb[bk];
  for(var slot in h.equipment){
    if(!h.equipment.hasOwnProperty(slot))continue;
    var art=h.equipment[slot],am: Record<string, number>={};
    if(art.modifiers)for(var mk in art.modifiers)if(art.modifiers.hasOwnProperty(mk))am[mk]=(am[mk]||0)+Number(art.modifiers[mk]);
    // Прибавки по уровню героя (БУ): шаг («+1 за каждый второй уровень») и диапазоны («+12% с 17 уровня»).
    var lvlOa=0,lvlDirect: Record<string, number>={},lvv=artLevelValues(art,Number(h.level)||0);
    for(var lk in lvv){
      if(lk==='oa')lvlOa+=lvv[lk];else if(lk==='muf')lvlDirect[lk]=(lvlDirect[lk]||0)+lvv[lk];else am[lk]=(am[lk]||0)+lvv[lk];
    }
    var sg=h.gems[slot]||[];
    for(var gi=0;gi<sg.length;gi++){var gm=GEM_STATS[sg[gi]]&&GEM_STATS[sg[gi]].modifiers;if(gm)for(var gk in gm)if(gm.hasOwnProperty(gk))am[gk]=(am[gk]||0)+Number(gm[gk])}
    var ents=modEntries(am);
    for(var e=0;e<ents.length;e++){if(FITTING_STATS.indexOf(ents[e].key)!==-1)totals[ents[e].key]+=ents[e].value}
    // «Особые» записи дублируют числовые параметры текстом («Нападение: +3»): числа идут
    // в таблицу, в «Эффекты» — только нечисловое (флаги). Числовой параметр без строки
    // в таблице уходит в «Прочее» (extraNum), а не пропадает.
    if(Array.isArray(art.specials))for(var j=0;j<art.specials.length;j++){
      var sp=art.specials[j] as {text_ru?: string, stat?: string, value?: number, unit?: string} | string;
      if(typeof sp==='string'){if(sp)specs.push(sp);continue}
      if(sp.unit==='flag'||typeof sp.value!=='number'){if(sp.text_ru)specs.push(sp.text_ru);continue}
      if(sp.stat&&FITTING_STATS.indexOf(sp.stat)===-1&&sp.value){
        var ex=extraNum[sp.stat]||(extraNum[sp.stat]={label:(sp.text_ru||sp.stat).replace(/:.*$/,''),sum:0,pct:sp.unit==='%'});
        ex.sum+=sp.value}
    }
    if(art.set&&art.set>0){var sg2=setGroup(art.set);setC[sg2]=(setC[sg2]||0)+1}
    // ОА считаются от поля предмета (в modifiers их нет); крафт даёт +2% за каждый 1%.
    totals.oa+=craftOa(Number((art as any).oa)||0,craftCategory(art),h.craft[slot]);
    totals.oa+=lvlOa;
    for(var ldk in lvlDirect)totals[ldk]=(totals[ldk]||0)+lvlDirect[ldk];
    craftItems.push({art:art,craft:h.craft[slot]});
  }
  // Бонусы комплектов: действующая ступень (наибольшая из набранных) прибавляется к параметрам.
  if(fittingSets)for(var scid in setC){
    var scd=fittingSets[scid];if(!scd)continue;
    var sbest: Record<string, number>|null=null,sbc=0;
    for(var sb in scd.bonuses){var sbn=parseInt(sb);if(sbn<=setC[scid]&&sbn>=sbc){sbc=sbn;sbest=scd.bonuses[sb]}}
    if(sbest)for(var sk in sbest){if(FITTING_STATS.indexOf(sk)!==-1)totals[sk]+=Number(sbest[sk])||0}
  }
  return {totals:totals,specs:specs,setC:setC,extraNum:extraNum,craftItems:craftItems};
}

/** Суммы параметров героя куклы только от предметов (без бонуса фракции) — для карточки героя в
 *  редакторе боя: так же, как сервер складывает артефакты в `Hero`. */
export function fittingArtifactTotals(i: number): Record<string, number> {
  applyPendingEquipment();
  return heroTotals(fittingHeroes[i] || fittingHeroes[0], false).totals;
}

/** Подпись и значение параметра — как на сайте (`set.js`, `MODIFIER_LABELS`): «Доп. стрелковый
 *  урон: +24%», «Снижение всего получаемого урона: +10%». Своих догадок о подписях тут нет. */
function modLabel(key: string): string { return MODIFIER_LABELS[key] || FITTING_STAT_LABELS[key] || key; }
/** Бонус комплекта одной строкой: у комплектов инициатива — проценты («Инициатива: +8%»), «damage» — «Урон существ». */
function setBonusText(key: string, v: number): string {
  if(key==='initiative')return 'Инициатива: '+(v>0?'+':'')+v+'%';
  if(key==='damage')return 'Урон существ: '+(v>0?'+':'')+v;
  return modLabel(key)+': '+modValue(key,v);
}
/** Инициатива — плоское число (у предметов «Инициатива: +3»), `isPctModifier` её считает процентом. */
function modValue(key: string, v: number): string { return (v>0?'+':'')+v+(key!=='initiative'&&(key==='muf'||isPctModifier(key))?'%':''); }

/** Кнопки «−»/«+» у параметра в центральной таблице: «+» — пока остались очки, «−» — если на параметре они есть. */
function allocCtl(i: number, key: string, val: number): string {
  // Блок кнопок всегда занимает одно и то же место (даже пустой): иначе «+»/«−» то появляются, то исчезают, и колонка
  // с числами уезжает вбок.
  var ctl='';
  if(ALLOC_KEYS.indexOf(key)!==-1){
    var h=fittingHeroes[i],left=allocTotal(h,i)-allocSpent(h);
    ctl=((h.alloc[key]||0)>0?'<button class="vs-alloc" title="Убрать очко" onclick="onAlloc('+i+',\''+key+'\',-1)">−</button>':'')+
      (left>0?'<button class="vs-alloc" title="Улучшить параметр на 1" onclick="onAlloc('+i+',\''+key+'\',1)">+</button>':'');
  }
  var c='<span class="vs-ctl vs-ctl-'+(i===0?'l':'r')+'">'+ctl+'</span>',n='<span class="vs-num">'+val+'</span>';
  return i===0?c+n:n+c;
}

/** Подпись под героем: сколько очков осталось и кнопка сброса (когда есть что сбрасывать). */
function renderPoints(): void {
  for(var i=0;i<HERO_COUNT;i++){
    var box=document.getElementById('fit-points-'+i);if(!box)continue;
    var h=fittingHeroes[i],total=allocTotal(h,i),left=total-allocSpent(h),edu=educationPoints(i,Number(h.level)||0);
    box.innerHTML='Очки параметров: <b>'+left+'</b> из '+total+(edu?' <small>(образование: '+edu+')</small>':'')+
      (allocSpent(h)>0?' <button class="fit-reset" onclick="onAllocReset('+i+')">Сбросить параметры</button>':'');
  }
}

export function renderEffects(): void {
  applyPendingEquipment();
  for(var fi=0;fi<HERO_COUNT;fi++)fixAlloc(fittingHeroes[fi],fi);
  var res=[heroTotals(fittingHeroes[0]),heroTotals(fittingHeroes[1])];
  renderPoints();
  // Центр: числа обоих героев рядом, у большего — подсветка.
  var vs=document.getElementById('fit-vs');
  if(vs){
    var rows='';
    for(var r=0;r<VS_ROWS.length;r++){
      var key=VS_ROWS[r][0],a=res[0].totals[key]||0,b=res[1].totals[key]||0;
      rows+='<tr><td class="vs-val'+(a>b?' lead':'')+'">'+allocCtl(0,key,a)+'</td><td class="vs-lab" title="'+VS_ROWS[r][1]+'"><img class="vs-ico" src="'+ICON_BASE+VS_ROWS[r][2]+'" alt="'+VS_ROWS[r][1]+'"><small>'+VS_ROWS[r][1]+'</small></td><td class="vs-val'+(b>a?' lead':'')+'">'+allocCtl(1,key,b)+'</td></tr>';
    }
    vs.innerHTML=rows;
  }
  // Под каждым героем — его эффекты: числовые бонусы боя, нечисловые свойства предметов,
  // крафт и действующие бонусы комплектов. Сами параметры (атака, защита…) — в центре.
  for(var hi=0;hi<HERO_COUNT;hi++)renderHeroEffects(hi,res[hi]);
  // Панель героя в бою показывает итог с учётом Примерочной — обновляем её сразу.
  try{var tw=window as any;if(typeof tw.tacSyncHeroStats==='function')tw.tacSyncHeroStats()}catch(e){}
  syncUrl();
}

function renderHeroEffects(hi: number, cur: HeroResult): void {
  var box=document.getElementById('fit-fx-'+hi);
  if(!box)return;
  var totals=cur.totals,lines: string[]=[];
  var line=function(key: string): void{
    var t=totals[key];if(!t)return;
    lines.push('<div class="fx-row"><span>'+modLabel(key)+'</span><b class="'+(t>0?'pos':'neg')+'">'+modValue(key,t)+'</b></div>');
  };
  var combatKeys=['attack_percent','defence_percent','attack_war','defence_war','defence_range','attack_range','reload','critical','magic_resist','magic_immunity','mbf','mkf','mua','hp','muw','sin','ign','pdi','pat','tactics','petrify'];
  var otherKeys=['damage','muf','attack_nature','defence_nature','initiative_hero','initiative_percent','spellpower_percent','knowledge_percent','luck_percent','morale_percent'];
  combatKeys.concat(otherKeys).forEach(line);
  for(var xk in cur.extraNum){var xe=cur.extraNum[xk];if(!xe.sum)continue;lines.push('<div class="fx-row"><span>'+escHtml(xe.label)+'</span><b class="'+(xe.sum>0?'pos':'neg')+'">'+(xe.sum>0?'+':'')+xe.sum+(xe.pct?'%':'')+'</b></div>')}
  var crEff=combineCraftEffects(cur.craftItems);
  for(var ck in crEff)lines.push('<div class="fx-row"><span>'+(CRAFT_EFFECT_LABELS[ck]||ck)+'</span><b class="pos">+'+crEff[ck]+'%</b></div>');
  cur.specs.forEach(function(sp){lines.push('<div class="fx-flag">✦ '+escHtml(sp)+'</div>')});
  if(fittingSets) for(var sid in cur.setC){
    var sd=fittingSets[sid];if(!sd)continue;
    var cnt=cur.setC[sid],best: Record<string, number> | null=null,bc=0;
    for(var bc2 in sd.bonuses){var bc3=parseInt(bc2);if(bc3<=cnt&&bc3>=bc){bc=bc3;best=sd.bonuses[bc2]}}
    if(!best)continue;
    var bt='';for(var bk in best){if(bt)bt+=', ';bt+=setBonusText(bk,best[bk])}
    lines.push('<div class="fx-set"><b>'+escHtml(sd.name)+'</b> ('+cnt+'/'+bc+')'+(bt?': '+escHtml(bt):'')+'</div>');
  }
  box.innerHTML=lines.length?'<div class="fx-title">Эффекты</div>'+lines.join(''):'';
  box.style.display=lines.length?'':'none';
}

// ===== ЦЕНТРАЛЬНАЯ КОЛОНКА: артефакты / комплекты / сборки =====

var BR_MODES: Array<['arts' | 'sets' | 'craft' | 'builds', string]> = [['arts','Артефакты'],['sets','Готовые комплекты'],['craft','Крафт'],['builds','Мои сборки']];

function renderModes(): void {
  var el=document.getElementById('br-modes');
  if(!el)return;
  el.innerHTML=BR_MODES.map(function(m){return'<button class="br-mode'+(m[0]===_brMode?' active':'')+'" onclick="setBrMode(\''+m[0]+'\')">'+m[1]+'</button>'}).join('')+
    '<span class="br-target">Одеваем: <b>'+(bothMode?'обоих':'Героя '+(activeHero+1))+'</b></span>';
}
export function setBrMode(m: 'arts' | 'sets' | 'craft' | 'builds'): void { _brMode=m; _brSet=null; renderModes(); renderPane(); }
export function clearBrSet(): void { _brSet=null; renderPane(); }

function renderPane(): void {
  renderModes();
  var pane=document.getElementById('br-pane');
  if(!pane)return;
  if(_brMode==='sets'){renderSetsPane(pane);return}
  if(_brMode==='builds'){renderBuildsPane(pane);return}
  if(_brMode==='craft'){pane.innerHTML='<div class="fitting-craft" id="fit-craft"></div>';renderCraftPanel();return}
  var setChip=(_brSet!==null&&fittingSets&&fittingSets[_brSet])?'<div class="br-setchip">Предметы комплекта «'+escHtml(fittingSets[_brSet].name)+'» — меняйте их под слоты <a onclick="clearBrSet()">показать все артефакты</a></div>':'';
  pane.innerHTML=setChip+'<div class="br-cats" id="br-cats"></div>'+
    '<div class="br-search"><input id="br-s" '+INPUT_HINT_ATTR+'="Поиск..." oninput="onBrSearch()">'+
      '<select id="br-sort" title="Сортировка" onchange="onBrSort()">'+BR_SORTS.map(function(o){return'<option value="'+o[0]+'"'+(o[0]===_brSort?' selected':'')+'>'+o[1]+'</option>'}).join('')+'</select></div>'+
    '<div class="br-grid" id="br-grid"></div>';
  var s=document.getElementById('br-s') as HTMLInputElement|null; if(s)s.value=_brQuery;
  renderCats(); renderGrid();
}

export function renderCats(): void {
  var el=document.getElementById('br-cats');
  if (!el) return;
  el.innerHTML=BR_CATS.map(function(c){return'<span class="cat'+(c.id===_brCat?' active':'')+'" onclick="setBrCat(\''+c.id+'\')">'+c.label+'</span>'}).join('');
}
export function setBrCat(c: string): void {_brCat=c;renderCats();renderGrid()}
export function onBrSort(): void {_brSort=(document.getElementById('br-sort') as HTMLSelectElement|null)?.value||'level';renderGrid()}
export function onBrSearch(): void {_brQuery=((document.getElementById('br-s') as HTMLInputElement | null)?.value||'').toLowerCase();renderGrid()}

/** Подсказки комплектов под «Поиском по названию»: клик (или Enter) надевает комплект. */
export function onHeroSearch(i: number): void {
  var inp=document.getElementById('fit-q-'+i) as HTMLInputElement|null,box=document.getElementById('fit-sg-'+i);
  if(!inp||!box)return;
  var q=inp.value.trim().toLowerCase();
  if(!q){box.style.display='none';return}
  if(!fittingSets){box.innerHTML='<div class="sg-empty">Загружаю комплекты…</div>';box.style.display='';return}
  var list=setList().filter(function(x){return x.name.toLowerCase().indexOf(q)!==-1}).slice(0,8);
  box.innerHTML=list.length?list.map(function(x){
    var ic=x.items[0]&&x.items[0].icon?'<img src="/api/img?url='+encodeURIComponent(artIconB(x.items[0].icon))+'" alt="">':'';
    return '<div class="sg-item" data-id="'+x.id+'" onmousedown="pickSetFromSearch('+x.id+','+i+')">'+ic+'<b>'+escHtml(x.name)+'</b><span>'+x.items.length+' шт.</span></div>';
  }).join(''):'<div class="sg-empty">Комплект не найден</div>';
  box.style.display='';
}
export function onHeroSearchKey(ev: KeyboardEvent, i: number): void {
  if(ev.key==='Escape'){hideSuggest(i);return}
  if(ev.key!=='Enter')return;
  var first=document.querySelector('#fit-sg-'+i+' .sg-item') as HTMLElement|null;
  if(first)pickSetFromSearch(Number(first.getAttribute('data-id')),i);
}
export function hideSuggest(i: number): void {
  var box=document.getElementById('fit-sg-'+i);if(box)box.style.display='none';
}
export function pickSetFromSearch(id: number, i: number): void {
  var inp=document.getElementById('fit-q-'+i) as HTMLInputElement|null;if(inp)inp.value='';
  hideSuggest(i);
  activeHero=i;
  equipSet(id,bothMode?[0,1]:[i]);
  renderHeroBars();
}

function equippedSlot(h: FittingHero, key: string): string | null {
  for(var s in h.equipment){if(h.equipment[s]&&h.equipment[s].key===key)return s}
  return null;
}

export function renderGrid(): void {
  var g=document.getElementById('br-grid');
  if (!g) return;
  var flt=allArts().filter(function(a){if(_brSet!==null&&setGroup(Number(a.set))!==setGroup(_brSet))return false;if(_brCat!=='all'&&getArtCat(a)!==_brCat)return false;if(_brQuery&&artName(a).toLowerCase().indexOf(_brQuery)===-1)return false;return true});
  if(!flt.length){g.innerHTML='<div class="no-items">Нет артефактов</div>';return}
  var idx=heroIndexes(),h='';
  var lvl=Number(fittingHero(idx[0]).level)||0;
  // Значение параметра у предмета: прямые модификаторы + прибавки по уровню героя.
  var statOf=function(a: ArtifactRecord,key: string): number{
    var v=Number((a.modifiers as Record<string,number>|undefined)?.[key])||0;
    return v+(artLevelValues(a,lvl)[key]||0)+(key==='oa'?(Number((a as any).oa)||0):0);
  };
  var isLocked=function(a: ArtifactRecord): boolean{return !idx.some(function(hi){return !!equippedSlot(fittingHeroes[hi],a.key)})&&idx.some(function(hi){return !canWear(fittingHeroes[hi],a)})};
  var byName=function(a: ArtifactRecord,b: ArtifactRecord){return artName(a).localeCompare(artName(b))};
  // Недоступные (уровень выше БУ героя) — всегда в самом низу; внутри групп — выбранная сортировка.
  flt.sort(function(a,b){
    var la=isLocked(a)?1:0,lb=isLocked(b)?1:0;
    if(la!==lb)return la-lb;
    if(_brSort==='name')return byName(a,b);
    if(_brSort==='level_asc')return(a.level||0)-(b.level||0)||byName(a,b);
    if(_brSort!=='level')return statOf(b,_brSort)-statOf(a,_brSort)||(b.level||0)-(a.level||0)||byName(a,b);
    return(b.level||0)-(a.level||0)||byName(a,b);
  });
  for(var i=0;i<flt.length;i++){
    var a=flt[i],eq=idx.some(function(hi){return !!equippedSlot(fittingHeroes[hi],a.key)}),lock=!eq&&idx.some(function(hi){return !canWear(fittingHeroes[hi],a)});
    h+='<div class="br-item'+(eq?' equipped':'')+(lock?' br-locked':'')+'" data-art="'+a.key+'" onclick="onBrClk(\''+a.key+'\')">'+
      (a.icon&&a.icon_ok!==false?'<img src="/api/img?url='+encodeURIComponent(artIconB(a.icon))+'" onerror="this.style.display=\'none\'">':'<span class="doll-empty">?</span>')+'</div>';
  }
  g.innerHTML=h;
}

/** Слот под предмет: свободный подходящий, иначе первый подходящий (заменяет). */
function slotFor(h: FittingHero, art: ArtifactRecord): string | null {
  for(var i=0;i<SLOT_DOLL.length;i++){var sl=SLOT_DOLL[i][0];if(slotMatch(art,sl)&&!h.equipment[sl])return sl}
  for(var j=0;j<SLOT_DOLL.length;j++){var sl2=SLOT_DOLL[j][0];if(slotMatch(art,sl2))return sl2}
  return null;
}

/** Артефакт можно надеть, если его уровень не выше БУ героя. */
function canWear(h: FittingHero, art: ArtifactRecord): boolean {return (Number(art.level)||0)<=(Number(h.level)||0)}

function putArt(h: FittingHero, art: ArtifactRecord): boolean {
  if(!canWear(h,art))return false;
  var bs=slotFor(h,art);
  if(!bs)return false;
  delete h.gems[bs];delete h.craft[bs];h.equipment[bs]=art;
  return true;
}

export function onBrClk(key: string): void {
  var found=findArt(key);if(!found)return;
  var art: ArtifactRecord=found;
  heroIndexes().forEach(function(hi){
    var h=fittingHeroes[hi],ts=equippedSlot(h,key);
    // Кольца бывают парой: надетое кольцо при втором клике встаёт во второй свободный слот,
    // а не снимается (одинаковые кольца в оригинале носить можно). Снять — крестиком на слоте
    // или третьим кликом, когда оба слота заняты.
    if(!ts&&!canWear(h,art)){showToast('«'+artName(art)+'»: нужен уровень героя '+art.level+' (сейчас '+h.level+')',true);return}
    if(ts&&getArtCat(art)==='ring'){
      var free=['ring_top','ring_bottom'].filter(function(sl){return !h.equipment[sl]});
      if(free.length){delete h.gems[free[0]];delete h.craft[free[0]];h.equipment[free[0]]=art;return}
    }
    if(ts){delete h.equipment[ts];delete h.gems[ts];delete h.craft[ts]}
    else putArt(h,art);
  });
  renderAll();
}

// ===== ГОТОВЫЕ КОМПЛЕКТЫ =====

/** Предметы комплекта: самые высокие уровни вперёд. */
function setItems(id: number): ArtifactRecord[] {
  return allArts().filter(function(a){return Number(a.set)===id}).sort(function(a,b){return(b.level||0)-(a.level||0)});
}

function setList(): Array<{id: number, name: string, items: ArtifactRecord[]}> {
  var out: Array<{id: number, name: string, items: ArtifactRecord[]}>=[];
  if(!fittingSets)return out;
  for(var sid in fittingSets){
    var items=setItems(Number(sid));
    if(items.length)out.push({id:Number(sid),name:fittingSets[sid].name,items:items});
  }
  return out.sort(function(a,b){return a.name.localeCompare(b.name)});
}

/** Надеть комплект: предметы встают в свободные слоты, при нехватке — заменяют. */
export function equipSet(id: number, heroes?: number[]): void {
  var items=setItems(id),idx=heroes||heroIndexes(),name=fittingSets&&fittingSets[id]?fittingSets[id].name:String(id);
  if(!items.length){showToast('В комплекте «'+name+'» нет предметов',true);return}
  var put=0;
  // Комплект надевается на ЧИСТОГО героя: прежние предметы (с самоцветами и крафтом) снимаются.
  idx.forEach(function(hi){var h=fittingHeroes[hi];for(var k=0;k<SLOT_DOLL.length;k++){var sk=SLOT_DOLL[k][0];delete h.equipment[sk];delete h.gems[sk];delete h.craft[sk]}});
  idx.forEach(function(hi){var h=fittingHeroes[hi];items.forEach(function(a){if(equippedSlot(h,a.key)||putArt(h,a))put++})});
  showToast('«'+name+'»: надето '+Math.round(put/idx.length)+' из '+items.length+(idx.length>1?' (на обоих)':''));
  // Дальше — вкладка «Артефакты» с предметами комплекта: у большого комплекта слотов не хватает, и
  // лишнее меняют вручную.
  _brMode='arts';_brSet=id;_brCat='all';_brQuery='';
  renderAll();
}

function renderSetOptions(): void {
  var list=setList();
  for(var i=0;i<HERO_COUNT;i++){
    var sel=document.getElementById('fit-set-'+i) as HTMLSelectElement|null;
    if(!sel)continue;
    sel.innerHTML='<option value="">Надеть комплект</option>'+list.map(function(s){return'<option value="'+s.id+'">'+escHtml(s.name)+' ('+s.items.length+')</option>'}).join('');
  }
}

export function onSetPick(i: number): void {
  var sel=document.getElementById('fit-set-'+i) as HTMLSelectElement|null;
  if(!sel||!sel.value)return;
  var id=Number(sel.value);sel.value='';
  activeHero=i;
  equipSet(id,bothMode?[0,1]:[i]);
  renderHeroBars();
}

export function onSetQuery(): void {
  _setQuery=((document.getElementById('set-q') as HTMLInputElement|null)?.value||'').toLowerCase();
  var pane=document.getElementById('br-pane');if(pane)renderSetsPane(pane,true);
}

function renderSetsPane(pane: HTMLElement, keepFocus?: boolean): void {
  if(!fittingSets){pane.innerHTML='<div class="no-items">Загружаю комплекты…</div>';return}
  var list=setList().filter(function(s){return!_setQuery||s.name.toLowerCase().indexOf(_setQuery)!==-1});
  var cards=list.map(function(s){
    var best=fittingSets![s.id].bonuses,top=0;for(var k in best){if(parseInt(k)>top)top=parseInt(k)}
    var bonus=best[top]||{},bt=Object.keys(bonus).map(function(b){return setBonusText(b,bonus[b])}).join(', ');
    var icons=s.items.slice(0,8).map(function(a){return a.icon?'<img data-art="'+a.key+'" src="/api/img?url='+encodeURIComponent(artIconB(a.icon))+'" onerror="this.style.display=\'none\'">':''}).join('');
    return '<div class="set-card"><div class="set-card-head"><b>'+escHtml(s.name)+'</b><span>'+s.items.length+' шт.</span></div>'+
      '<div class="set-card-icons">'+icons+'</div>'+
      (bt?'<div class="set-card-bonus">'+(top?top+' шт.: ':'')+escHtml(bt)+'</div>':'')+
      '<button class="set-card-btn" onclick="equipSet('+s.id+')">Надеть '+(bothMode?'обоим':'Герою '+(activeHero+1))+'</button></div>';
  }).join('');
  pane.innerHTML='<div class="br-search"><input id="set-q" '+INPUT_HINT_ATTR+'="Поиск комплекта..." oninput="onSetQuery()"></div>'+
    '<div class="set-grid">'+(cards||'<div class="no-items">Нет комплектов</div>')+'</div>';
  var q=document.getElementById('set-q') as HTMLInputElement|null;
  if(q){q.value=_setQuery;if(keepFocus){q.focus();q.setSelectionRange(q.value.length,q.value.length)}}
}

// ===== МОИ СБОРКИ =====

export function loadBuilds(): Record<string, any> {try{return JSON.parse(localStorage.getItem('fitting_builds')||'{}')}catch(e){return{}}}
export function saveBuilds(b: Record<string, any>): void {try{localStorage.setItem('fitting_builds',JSON.stringify(b))}catch(e){}}

function hasItems(h: FittingHero): boolean {for(var s in h.equipment){if(h.equipment.hasOwnProperty(s)&&h.equipment[s])return true}return false}

function renderBuildsPane(pane: HTMLElement): void {
  var builds=loadBuilds(),names=Object.keys(builds);
  var local=names.map(function(n){return'<div class="build-item"><span class="build-name" onclick="loadBld(\''+escAttr(n)+'\')">'+escHtml(n)+'</span>'+
    '<button class="build-del" onclick="armDel(this,\'local\',\''+escAttr(n)+'\')" title="Удалить">&times;</button></div>'}).join('');
  pane.innerHTML='<div class="build-save"><input id="bld-inp" '+INPUT_HINT_ATTR+'="Название сборки" maxlength="30">'+
    '<button onclick="saveBld()">Сохранить Героя '+(activeHero+1)+'</button></div>'+
    '<div class="build-title">В этом браузере</div><div class="build-list">'+(local||'<div class="no-items">Пока пусто</div>')+'</div>'+
    '<div class="build-title">На сервере</div><div class="build-list" id="fit-server-list"></div>';
  serverList(function(){renderBldServer()});
}
function escAttr(t: string): string {return escHtml(t).replace(/\\/g,'\\\\')}

export function renderBld(): void { if(_brMode==='builds')renderPane(); }

function buildPayload(h: FittingHero): Record<string, any> {
  var data: Record<string, string>={};for(var s in h.equipment)if(h.equipment.hasOwnProperty(s))data[s]=h.equipment[s].key;
  return {items:data,gems:JSON.parse(JSON.stringify(h.gems)),craft:JSON.parse(JSON.stringify(h.craft)),faction:h.faction,level:h.level,alloc:JSON.parse(JSON.stringify(h.alloc)),name:h.name};
}

/** Применить сборку к герою (в режиме «обоих» — к обоим). */
function applyBuild(bd: any): void {
  var data=bd.items||bd,gems=bd.gems||{};
  heroIndexes().forEach(function(hi){
    var h=fittingHeroes[hi];
    if(bd.faction)h.faction=bd.faction;
    if(bd.level)h.level=bd.level;
    h.alloc=bd.alloc?JSON.parse(JSON.stringify(bd.alloc)):{};
    if(typeof bd.name==='string'&&bd.name)h.name=bd.name;
    h.equipment={};h.gems={};h.craft={};
    for(var slot in data){if(data.hasOwnProperty(slot)&&slot!==CRAFT_KEY){var art=findArt(data[slot]);if(art&&slotMatch(art,slot)){h.equipment[slot]=art;if(gems[slot])h.gems[slot]=gems[slot].slice();restoreCraft(h,slot,art,bd.craft&&bd.craft[slot])}}}
  });
  renderRoom();
}

export function saveBld(): void {
  var inp=document.getElementById('bld-inp') as HTMLInputElement | null,name=inp?.value.trim();
  if(!name){showToast('Введите название сборки',true);return}
  var h=fittingHero();
  if(!hasItems(h)){showToast('Сначала наденьте артефакты',true);return}
  var builds=loadBuilds();builds[name]=buildPayload(h);saveBuilds(builds);
  showToast('Сборка «'+name+'» сохранена');
  serverSave(name);
  renderPane();
}
export function serverSaveBld(): void { saveBld(); }

export function loadBld(name: string): void {
  var bd=loadBuilds()[name];if(!bd)return;
  applyBuild(bd);
  showToast('Сборка «'+name+'» надета');
}

/** Удаление в два нажатия: первое превращает × в «Удалить?», второе удаляет. `confirm()` не
 *  годится — во встроенных браузерах он молча возвращает «нет», и кнопка ничего не делала. */
export function armDel(btn: HTMLElement, kind: 'local' | 'server', name: string): void {
  if(btn.dataset.armed==='1'){if(kind==='local')delBld(name);else serverDelete(name);return}
  btn.dataset.armed='1';btn.textContent='Удалить?';btn.classList.add('armed');
  setTimeout(function(){if(btn.isConnected){btn.dataset.armed='';btn.innerHTML='&times;';btn.classList.remove('armed')}},3000);
}

export function delBld(name: string): void {
  var builds=loadBuilds();delete builds[name];saveBuilds(builds);renderPane();
}

interface ServerBuild {
  name: string;
  updated_at: number;
}

export function renderBldServer(): void {
  var list=document.getElementById('fit-server-list');
  if(!list)return;
  list.innerHTML='';
  if(!_serverBuilds.length){list.innerHTML='<div class="no-items">Нет сборок</div>';return}
  // DOM API вместо конкатенации в innerHTML: имя сборки приходит с сервера
  // (его может сохранить кто угодно) — b.name как текст, не как разметка.
  for(var i=0;i<_serverBuilds.length;i++){
    var b=_serverBuilds[i];
    var item=document.createElement('div');item.className='build-item';
    var nameEl=document.createElement('span');nameEl.className='build-name';
    nameEl.title='Загрузить';nameEl.textContent=b.name;
    nameEl.onclick=function(name:string){return function(){serverLoad(name)}}(b.name);
    var dateEl=document.createElement('span');dateEl.className='build-date';
    dateEl.textContent=new Date(b.updated_at*1000).toLocaleDateString();
    var delEl=document.createElement('button');delEl.className='build-del';delEl.innerHTML='&times;';
    delEl.title='Удалить';
    delEl.onclick=function(el:HTMLElement,name:string){return function(){armDel(el,'server',name)}}(delEl,b.name);
    item.appendChild(nameEl);item.appendChild(dateEl);item.appendChild(delEl);
    list.appendChild(item);
  }
}

// ===== CRAFT (гильдия оружейников) =====

/** Служебный ключ крафта внутри `data` серверной сборки (рядом со слотами). */
export var CRAFT_KEY = '_craft';

/** Вернуть крафт слота из сохранённой сборки: только то, что допустимо для предмета. */
export function restoreCraft(h: FittingHero, slot: string, art: ArtifactRecord, raw: unknown): void {
  var cr=normalizeCraft(raw,craftCategory(art));
  if(Object.keys(cr).length) h.craft[slot]=cr;
}

/** Слоты куклы активного героя, где стоит предмет, которому доступен крафт. */
export function craftableSlots(): string[] {
  var h=fittingHero(),out: string[]=[];
  for(var i=0;i<SLOT_DOLL.length;i++){var sl=SLOT_DOLL[i][0],a=h.equipment[sl];if(a&&craftCategory(a))out.push(sl)}
  return out;
}

export function renderCraftPanel(): void {
  var box=document.getElementById('fit-craft');
  if(!box)return;
  var h=fittingHero(),slots=craftableSlots();
  if(!h.craftSlot||slots.indexOf(h.craftSlot)===-1)h.craftSlot=slots[0]||null;
  var head='<div class="craft-title">Крафт · гильдия оружейников</div>'+
    '<div class="craft-import"><input id="fit-art-url" '+INPUT_HINT_ATTR+'="Ссылка на art_info.php вашего артефакта">'+
    '<button onclick="importArtInfo()">Загрузить</button></div>';
  if(!h.craftSlot){
    box.innerHTML=head+'<div class="craft-note">Наденьте оружие, броню или украшение — и задайте модификаторы.</div>';
    return;
  }
  var art=h.equipment[h.craftSlot],cat=craftCategory(art)!,cr=h.craft[h.craftSlot]||{};
  var opts=slots.map(function(sl){var a=h.equipment[sl];return'<option value="'+sl+'"'+(sl===h.craftSlot?' selected':'')+'>'+escHtml(artName(a))+'</option>'}).join('');
  var html=head+'<div class="craft-slot"><select id="fit-craft-slot" onchange="onCraftSlot()">'+opts+'</select>'+
    '<span class="craft-cat">'+CRAFT_CAT_LABEL[cat]+'</span></div><table class="craft-mods">';
  CRAFT_CODES[cat].forEach(function(code){
    var o='';for(var v=0;v<=MAX_CRAFT_LEVEL;v++)o+='<option value="'+v+'"'+(v===(cr[code]||0)?' selected':'')+'>'+(v?v+' ур. · '+v*pctPerLevel(cat,code)+'%':'—')+'</option>';
    html+='<tr><td class="craft-code">'+code+'</td><td class="craft-label">'+CRAFT_LABELS[cat][code]+'</td><td><select data-code="'+code+'" onchange="onCraftMod(this)">'+o+'</select></td></tr>';
  });
  var baseOa=Number((art as any).oa)||0,total=craftOa(baseOa,cat,cr);
  html+='</table><div class="craft-foot"><span>Модификаторов: '+Object.keys(cr).length+'/'+MAX_CRAFT_MODS+' · ОА: '+baseOa+(total!==baseOa?' → '+total:'')+'</span>'+
    '<button onclick="clearCraft()">Сбросить</button></div>';
  box.innerHTML=html;
}

export function onCraftSlot(): void {
  fittingHero().craftSlot=(document.getElementById('fit-craft-slot') as HTMLSelectElement).value;
  renderCraftPanel();
}

/** Поставить процент модификатора выбранного предмета (0 — снять). Больше пяти — отказ. */
export function onCraftMod(el: HTMLSelectElement): void {
  var h=fittingHero();
  if(!h.craftSlot)return;
  var code=el.getAttribute('data-code')||'',pct=parseInt(el.value)||0;
  var cr: Craft=Object.assign({},h.craft[h.craftSlot]||{});
  if(pct>0&&!(code in cr)&&Object.keys(cr).length>=MAX_CRAFT_MODS){
    showToast('На предмет — не больше '+MAX_CRAFT_MODS+' разных модификаторов',true);
    renderCraftPanel();return;
  }
  if(pct>0)cr[code]=pct;else delete cr[code];
  if(Object.keys(cr).length)h.craft[h.craftSlot]=cr;else delete h.craft[h.craftSlot];
  renderDoll();renderEffects();renderCraftPanel();
}

export function clearCraft(): void {
  var h=fittingHero();
  if(h.craftSlot)delete h.craft[h.craftSlot];
  renderDoll();renderEffects();renderCraftPanel();
}

/** Слот под предмет импорта: уже надетый тот же ключ, иначе свободный подходящий, иначе первый подходящий. */
function slotForImport(h: FittingHero, art: ArtifactRecord): string | null {
  return equippedSlot(h,art.key)||slotFor(h,art);
}

/** Применить разобранный сервером экземпляр (`/api/art_info`) к кукле активного героя. */
export function applyArtInfo(info: {key: string, name?: string, craft?: Craft, known?: boolean, oa?: number | null, oa_mismatch?: number}): boolean {
  var art=findArt(info.key),h=fittingHero();
  if(!art){showToast('Артефакта «'+(info.name||info.key)+'» нет в справочнике',true);return false}
  var slot=slotForImport(h,art);
  if(!slot){showToast('Для «'+(info.name||info.key)+'» нет подходящего слота',true);return false}
  h.equipment[slot]=art;delete h.gems[slot];delete h.craft[slot];
  restoreCraft(h,slot,art,info.craft);
  h.craftSlot=slot;
  renderAll();
  var applied=h.craft[slot]||{};
  var codes=Object.keys(applied).map(function(c){return c+applied[c]}).join(' ');
  showToast('Загружено: '+(info.name||info.key)+(codes?' · крафт '+codes:' · без крафта'));
  if(info.oa_mismatch!==undefined&&info.oa!=null)showToast('ОА по странице игры: '+info.oa+', по формуле: '+info.oa_mismatch,true);
  return true;
}

export function importArtInfo(): void {
  var inp=document.getElementById('fit-art-url') as HTMLInputElement | null,url=(inp?.value||'').trim();
  if(!url){showToast('Вставьте ссылку на артефакт (art_info.php)',true);return}
  fetch('/api/art_info?url='+encodeURIComponent(url)).then(function(r){return r.json()}).then(function(data){
    if(!data||data.error){showToast('Ошибка: '+(data?data.error:'нет ответа'),true);return}
    if(applyArtInfo(data)&&inp)inp.value='';
  }).catch(function(err){showToast('Не удалось загрузить: '+err.message,true)});
}

// ===== SERVER BUILD FUNCTIONS =====

export var _serverBuilds: ServerBuild[] = [];

export function serverList(callback?: () => void): void {
  fetch('/api/fitting?action=list').then(function(r){return r.json()}).then(function(data){
    _serverBuilds = data||[];
    if(callback) callback();
  }).catch(function(err){
    console.warn('serverList error:', err);
    _serverBuilds = [];
    if(callback) callback();
  });
}
(window as any).serverList = serverList;

export function serverLoad(name: string): void {
  fetch('/api/fitting?action=get&name='+encodeURIComponent(name)).then(function(r){return r.json()}).then(function(data){
    if(!data||data.error){showToast('Ошибка загрузки: '+(data?data.error:'unknown'), true);return}
    var items = data.data||{};
    var bd: Record<string, any> = {items:{},gems:data.gems||{},craft:items[CRAFT_KEY]||{},faction:data.faction||1,level:data.level||DEFAULT_HERO_LEVEL};
    for(var slot in items){if(items.hasOwnProperty(slot)&&slot!==CRAFT_KEY)bd.items[slot]=items[slot]}
    applyBuild(bd);
    showToast('Сборка "'+name+'" загружена с сервера');
  }).catch(function(err){
    showToast('Ошибка загрузки с сервера: '+err.message, true);
  });
}
(window as any).serverLoad = serverLoad;

export function serverSave(name: string): void {
  var h=fittingHero(),data: Record<string, any> = {};for(var s in h.equipment){if(h.equipment.hasOwnProperty(s)&&h.equipment[s]){data[s]=h.equipment[s].key}}
  // Сервер хранит `data` как есть (слот → ключ); крафт едет рядом под служебным ключом.
  if(Object.keys(h.craft).length) data[CRAFT_KEY]=JSON.parse(JSON.stringify(h.craft));
  fetch('/api/fitting',{
    method:'POST',
    headers:{'Content-Type':'application/json'},
    body:JSON.stringify({name:name,data:data,gems:h.gems,faction:h.faction,level:h.level})
  }).then(function(r){return r.json()}).then(function(resp){
    if(resp&&resp.error){showToast('Ошибка: '+resp.error, true);return}
    showToast('Сборка "'+name+'" сохранена на сервер');
    serverList(function(){renderBldServer()});
  }).catch(function(err){
    showToast('Ошибка сохранения: '+err.message, true);
  });
}
(window as any).serverSave = serverSave;

export function serverDelete(name: string): void {
  fetch('/api/fitting?name='+encodeURIComponent(name),{method:'DELETE'}).then(function(r){return r.json()}).then(function(resp){
    if(resp&&resp.error){showToast('Ошибка: '+resp.error, true);return}
    showToast('Сборка "'+name+'" удалена с сервера');
    serverList(function(){renderBldServer()});
  }).catch(function(err){
    showToast('Ошибка удаления: '+err.message, true);
  });
}
(window as any).serverDelete = serverDelete;
