/** Потолок умения фракции героя. */
export const MAX_FACTION_LEVEL = 14;

/** «Заклятый враг» эльфа: шанс двойного урона = BASE + PER_LVL · умение, не выше MAX (%). */
export const ELF_CRIT_BASE_PCT = 5;
export const ELF_CRIT_PER_LVL = 4;
export const ELF_CRIT_MAX_PCT = 100;

/** Шанс крита эльфа при данном умении фракции (то же считает battle/abilities/playable.py). */
export function elfCritChance(factionLevel: number): number {
  return Math.min(ELF_CRIT_MAX_PCT, ELF_CRIT_BASE_PCT + ELF_CRIT_PER_LVL * factionLevel);
}

/** Коэффициенты при [1, L, A, L·A, L²] для вилки удара героя (hwm/hero_damage.py). */
