export const HERO_DMG_MAX_FIT: readonly number[] = [9.517, -1.887, 1.083, -0.032, 0.172];

/** Пороги уровней ярости (0, 1, 2, 3 уровень). */
export const RAGE_LEVEL_THRESHOLDS: readonly number[] = [0, 200, 500, 1000];
