// Настраиваемые диаграммы вкладки «Статистика».
//
// Одна карточка = заголовок + панель настроек (вид, сколько строк, порядок) +
// тело. Настройки каждой диаграммы запоминаются в localStorage по её `id`.
// Данные и опции регистрируются при создании карточки, перерисовка по
// событиям делегируется на корень вкладки (`bindCharts`).

export type ChartType = 'hbar' | 'column' | 'donut' | 'table';

export interface Row {
  label: string;
  value: number;
  /** Значения по рядам для стопки (сумма = value). */
  parts?: number[];
  href?: string;
  /** URL иконки слева от названия. */
  icon?: string;
  /** Подпись справа от значения (например «из 5 154»). */
  note?: string;
}

export interface ChartOpts {
  id: string;
  title: string;
  /** Что считают: колонка таблицы и подсказки. */
  unit: string;
  types?: ChartType[];
  type?: ChartType;
  top?: number;
  /** Порядок строк задан данными (дни, уровни): не сортировать по значению. */
  ordered?: boolean;
  series?: string[];
  fmt?: (v: number) => string;
  /** Шкала 0..max вместо «от максимума ряда». */
  max?: number;
  /** Риска на шкале (например 50% у винрейта). */
  mark?: number;
  hint?: string;
}

interface Settings { type: ChartType; top: number; sort: 'desc' | 'asc' | 'name'; }

const COLORS = ['#d4a537', '#4aa3df', '#5fb36b', '#d9604c', '#a77bd1', '#e08a3c', '#47b5a8', '#c46f9d', '#8a9a5b', '#7a8ba8'];
const TYPE_NAMES: Record<ChartType, string> = { hbar: 'Полосы', column: 'Столбцы', donut: 'Кольцо', table: 'Таблица' };
const TYPE_ICONS: Record<ChartType, string> = {
  hbar: '<svg viewBox="0 0 16 16"><path d="M2 3h10v2H2zM2 7h7v2H2zM2 11h12v2H2z"/></svg>',
  column: '<svg viewBox="0 0 16 16"><path d="M2 8h3v6H2zM6.5 3h3v11h-3zM11 6h3v8h-3z"/></svg>',
  donut: '<svg viewBox="0 0 16 16"><path d="M8 1a7 7 0 1 0 7 7h-3a4 4 0 1 1-4-4z"/></svg>',
  table: '<svg viewBox="0 0 16 16"><path d="M2 3h12v2H2zM2 7h12v2H2zM2 11h12v2H2z" opacity=".85"/></svg>',
};
const TOPS = [5, 10, 20, 0];

const registry = new Map<string, { rows: Row[]; opts: ChartOpts }>();

export function esc(s: unknown): string {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

export function num(n: number): string { return (n || 0).toLocaleString('ru-RU'); }

function load(opts: ChartOpts): Settings {
  var d: Settings = { type: opts.type || (opts.types || ['hbar'])[0], top: opts.top == null ? 10 : opts.top, sort: 'desc' };
  try {
    var raw = JSON.parse(localStorage.getItem('stats.chart.' + opts.id) || 'null');
    if (raw) {
      if ((opts.types || ALL).indexOf(raw.type) >= 0) d.type = raw.type;
      if (TOPS.indexOf(raw.top) >= 0) d.top = raw.top;
      if (['desc', 'asc', 'name'].indexOf(raw.sort) >= 0) d.sort = raw.sort;
    }
  } catch { /* приватный режим */ }
  return d;
}

const ALL: ChartType[] = ['hbar', 'column', 'donut', 'table'];

function save(id: string, s: Settings): void {
  try { localStorage.setItem('stats.chart.' + id, JSON.stringify(s)); } catch { /* ignore */ }
}

function fmtOf(o: ChartOpts): (v: number) => string { return o.fmt || num; }

function prepare(rows: Row[], o: ChartOpts, s: Settings): Row[] {
  var list = rows.slice();
  if (!o.ordered) {
    if (s.sort === 'name') list.sort(function(a, b) { return a.label.localeCompare(b.label, 'ru'); });
    else list.sort(function(a, b) { return s.sort === 'asc' ? a.value - b.value : b.value - a.value; });
  }
  return list;
}

function limited(list: Row[], top: number, o: ChartOpts, withRest: boolean): Row[] {
  if (!top || list.length <= top) return list;
  if (o.ordered) return list.slice(list.length - top);          // последние N точек
  var head = list.slice(0, top);
  if (withRest) {
    var rest = list.slice(top).reduce(function(a, r) { return a + r.value; }, 0);
    if (rest) head.push({ label: 'остальные', value: rest });
  }
  return head;
}

function tip(r: Row, o: ChartOpts): string {
  var f = fmtOf(o);
  var extra = r.parts && o.series ? ' (' + r.parts.map(function(p, i) { return o.series![i] + ' ' + f(p); }).join(', ') + ')' : '';
  return esc(r.label + ': ' + f(r.value) + extra + (r.note ? ' · ' + r.note : ''));
}

function link(r: Row, inner: string): string {
  if (r.icon) inner = '<img class="sc-ico" src="' + esc(r.icon) + '" alt="">' + inner;
  return r.href ? '<a class="sc-link" href="' + esc(r.href) + '" data-href="' + esc(r.href) + '">' + inner + '</a>' : inner;
}

function drawHbar(rows: Row[], o: ChartOpts): string {
  var f = fmtOf(o);
  var max = o.max || rows.reduce(function(m, r) { return Math.max(m, r.value); }, 1);
  return '<ol class="sc-hbar">' + rows.map(function(r, i) {
    var segs = (r.parts && r.parts.length > 1 ? r.parts : [r.value]).map(function(v, k) {
      return v ? '<i style="width:' + (v / max * 100).toFixed(2) + '%;background:' +
        (r.parts && r.parts.length > 1 ? COLORS[k % COLORS.length] : 'var(--gold)') + '"></i>' : '';
    }).join('');
    return '<li title="' + tip(r, o) + '"><span class="sc-rank">' + (o.ordered ? '' : i + 1) + '</span>' +
      '<span class="sc-name">' + link(r, esc(r.label)) + '</span>' +
      '<span class="sc-track">' + segs + (o.mark != null ? '<u style="left:' + (o.mark / max * 100) + '%"></u>' : '') + '</span>' +
      '<b class="sc-val">' + esc(f(r.value)) + '</b></li>';
  }).join('') + '</ol>';
}

function drawColumn(rows: Row[], o: ChartOpts): string {
  var f = fmtOf(o);
  var max = o.max || rows.reduce(function(m, r) { return Math.max(m, r.value); }, 1);
  var every = rows.length > 24 ? Math.ceil(rows.length / 7) : 1;
  var cols = rows.map(function(r, i) {
    var segs = (r.parts && r.parts.length > 1 ? r.parts : [r.value]).map(function(v, k) {
      return v ? '<i style="height:' + (v / max * 100).toFixed(2) + '%;background:' +
        (r.parts && r.parts.length > 1 ? COLORS[k % COLORS.length] : 'var(--gold)') + '"></i>' : '';
    }).join('');
    return '<div class="sc-col" title="' + tip(r, o) + '"><span class="sc-colval">' + (rows.length <= 8 ? esc(f(r.value)) : '') +
      '</span><div class="sc-colbar">' + segs + '</div><span class="sc-collabel">' + (i % every === 0 ? esc(r.label) : '') + '</span></div>';
  }).join('');
  return '<div class="sc-columns" style="--n:' + rows.length + '">' + cols + '</div>' + legendRow(o);
}

function legendRow(o: ChartOpts): string {
  if (!o.series || o.series.length < 2) return '';
  return '<ul class="sc-legend sc-legend-row">' + o.series.map(function(n, i) {
    return '<li><i style="background:' + COLORS[i % COLORS.length] + '"></i><span>' + esc(n) + '</span></li>';
  }).join('') + '</ul>';
}

function drawDonut(rows: Row[], o: ChartOpts): string {
  var total = rows.reduce(function(s, r) { return s + r.value; }, 0);
  if (!total) return '<div class="sc-empty">Нет данных.</div>';
  var f = fmtOf(o), acc = 0;
  var arcs = rows.map(function(r, i) {
    var share = r.value / total * 100;
    var seg = '<circle r="15.9155" cx="21" cy="21" fill="none" stroke="' + COLORS[i % COLORS.length] +
      '" stroke-width="5.5" stroke-dasharray="' + Math.max(share - 0.4, 0.1).toFixed(2) + ' ' + (100 - share + 0.4).toFixed(2) +
      '" stroke-dashoffset="' + (25 - acc).toFixed(2) + '"><title>' + tip(r, o) + '</title></circle>';
    acc += share;
    return seg;
  }).join('');
  var legend = rows.map(function(r, i) {
    return '<li><i style="background:' + COLORS[i % COLORS.length] + '"></i><span>' + link(r, esc(r.label)) + '</span><b>' +
      esc(f(r.value)) + '</b><em>' + (r.value / total * 100).toFixed(1) + '%</em></li>';
  }).join('');
  return '<div class="sc-donut"><svg viewBox="0 0 42 42" role="img"><g>' + arcs + '</g>' +
    '<text x="21" y="21.6" text-anchor="middle" class="sc-donut-total">' + esc(f(total)) + '</text>' +
    '<text x="21" y="26" text-anchor="middle" class="sc-donut-unit">всего</text></svg>' +
    '<ul class="sc-legend">' + legend + '</ul></div>';
}

function drawTable(rows: Row[], o: ChartOpts): string {
  var f = fmtOf(o);
  var total = rows.reduce(function(s, r) { return s + r.value; }, 0) || 1;
  var max = o.max || rows.reduce(function(m, r) { return Math.max(m, r.value); }, 1);
  return '<table class="sc-table"><thead><tr><th>' + esc(o.title) + '</th><th class="num">' + esc(o.unit) +
    '</th>' + (o.max ? '' : '<th class="num">Доля</th>') + '</tr></thead><tbody>' + rows.map(function(r) {
      return '<tr><td><div class="sc-cell"><i style="width:' + (r.value / max * 100).toFixed(1) + '%"></i><span>' +
        link(r, esc(r.label)) + '</span></div></td><td class="num">' + esc(f(r.value)) + (r.note ? ' <small>' + esc(r.note) + '</small>' : '') +
        '</td>' + (o.max ? '' : '<td class="num">' + (r.value / total * 100).toFixed(1) + '%</td>') + '</tr>';
    }).join('') + '</tbody></table>';
}

function body(rows: Row[], o: ChartOpts, s: Settings): string {
  if (!rows.length) return '<div class="sc-empty">Пока пусто.</div>';
  var sorted = prepare(rows, o, s);
  switch (s.type) {
    case 'donut': return drawDonut(limited(sorted, s.top || 9, o, true), o);
    case 'column': return drawColumn(limited(sorted, s.top, o, false), o);
    case 'table': return drawTable(limited(sorted, s.top, o, false), o);
    default: return drawHbar(limited(sorted, s.top, o, false), o);
  }
}

function toolbar(rows: Row[], o: ChartOpts, s: Settings): string {
  var types = o.types || ALL;
  var seg = types.length > 1 ? '<div class="sc-seg" role="group" aria-label="Вид диаграммы">' + types.map(function(t) {
    return '<button type="button" class="' + (t === s.type ? 'on' : '') + '" data-ctl="type" data-v="' + t + '" title="' +
      TYPE_NAMES[t] + '" aria-label="' + TYPE_NAMES[t] + '" aria-pressed="' + (t === s.type) + '">' + TYPE_ICONS[t] + '</button>';
  }).join('') + '</div>' : '';
  var topSel = rows.length > 5 ? '<select data-ctl="top" aria-label="Сколько показывать">' + TOPS.map(function(t) {
    var label = t ? (o.ordered ? 'последние ' + t : 'топ ' + t) : 'все ' + rows.length;
    return '<option value="' + t + '"' + (t === s.top ? ' selected' : '') + '>' + label + '</option>';
  }).join('') + '</select>' : '';
  var sortSel = !o.ordered && rows.length > 1 && s.type !== 'donut'
    ? '<select data-ctl="sort" aria-label="Порядок"><option value="desc"' + (s.sort === 'desc' ? ' selected' : '') + '>по убыванию</option>' +
      '<option value="asc"' + (s.sort === 'asc' ? ' selected' : '') + '>по возрастанию</option>' +
      '<option value="name"' + (s.sort === 'name' ? ' selected' : '') + '>по названию</option></select>' : '';
  return '<div class="sc-tools">' + seg + topSel + sortSel + '</div>';
}

/** HTML карточки; данные регистрируются, чтобы настройки перерисовывали её без запроса. */
export function chartCard(rows: Row[], o: ChartOpts): string {
  registry.set(o.id, { rows: rows, opts: o });
  var s = load(o);
  return '<article class="sc-card" data-chart="' + esc(o.id) + '"><header><h3>' + esc(o.title) +
    (o.hint ? '<small>' + esc(o.hint) + '</small>' : '') + '</h3>' + toolbar(rows, o, s) + '</header>' +
    '<div class="sc-body">' + body(rows, o, s) + '</div></article>';
}

function redraw(card: HTMLElement, s: Settings): void {
  var id = card.dataset.chart as string;
  var reg = registry.get(id);
  if (!reg) return;
  save(id, s);
  var tools = card.querySelector('.sc-tools');
  if (tools) tools.outerHTML = toolbar(reg.rows, reg.opts, s);
  (card.querySelector('.sc-body') as HTMLElement).innerHTML = body(reg.rows, reg.opts, s);
}

/** Один раз на корень: переключатели в карточках. */
export function bindCharts(root: HTMLElement): void {
  root.addEventListener('click', function(ev) {
    var btn = (ev.target as HTMLElement).closest('button[data-ctl="type"]') as HTMLElement | null;
    var card = btn && (btn.closest('.sc-card') as HTMLElement | null);
    if (!btn || !card) return;
    var reg = registry.get(card.dataset.chart as string);
    if (reg) redraw(card, Object.assign(load(reg.opts), { type: btn.dataset.v as ChartType }));
  });
  root.addEventListener('change', function(ev) {
    var sel = (ev.target as HTMLElement).closest('select[data-ctl]') as HTMLSelectElement | null;
    var card = sel && (sel.closest('.sc-card') as HTMLElement | null);
    if (!sel || !card) return;
    var reg = registry.get(card.dataset.chart as string);
    if (!reg) return;
    var s = load(reg.opts);
    if (sel.dataset.ctl === 'top') s.top = parseInt(sel.value, 10) || 0;
    else s.sort = sel.value as Settings['sort'];
    redraw(card, s);
  });
}
