/**
 * Карточка героя — окно характеристик, как карточка отряда: заголовок («Вы» / «Противник», класс и
 * звезда боевого уровня), строки с оригинальными значками, внизу «Эффекты» и «Закрыть».
 *
 * Открывается кликом по кукле героя на поле и по его фишке в ленте. В бою числа берутся у сервера
 * (`hero_card` в состоянии: те же, с которыми герой идёт в бой), в расстановке — из панели героя и
 * предметов Примерочной (так же, как сервер складывает их в `Hero`).
 */
import { tacById, tacCloseUnitInfo, tacPlaceInfoWindow, tacArmInfoDismiss, TACTIC_UNITS } from './battle.js';
import { battleBoard } from './battleState.js';
import { tacPortraitUrl } from './battlePalette.js';
import { hs } from './battleHotseatState.js';
import { allData, FACTIONS_META } from './data.js';
import { cdnImg } from './utils.js';
import { ICON_BASE } from './artifacts.js';
import { fittingHero, fittingHeroName, fittingArtifactTotals, fittingDollStatic } from './fitting.js';
import { staticsIconUrl } from './staticsIcons.js';
import {
  tacGetHeroData, tacGetEnemyHeroData, tacHeroArtifactEntries, tacHeroPerkKeys,
} from './battleHero.js';
import { HERO_SKILL_DESCS } from './skillwheels.js';
import { HERO_DMG_MIN_FIT, HERO_DMG_MAX_FIT } from './gameConstants.js';

type Side = 'player' | 'enemy';

interface HeroCard {
  name: string;
  faction: string;
  level: number | null;
  attack: number;
  defense: number;
  damage: [number, number];
  spell_power: number;
  knowledge: number;
  initiative: number | null;
  mana: number;
  mana_max: number;
  morale: number;
  luck: number;
  perks: string[];
  artifacts: string[];
  /** Процентные эффекты героя (урон/защита/магия) — у сервера из `Hero`, в редакторе из Примерочной. */
  bonuses?: Array<{ label: string; value: number }>;
}

/** Ключи итогов Примерочной → подписи «Эффектов» (те же эффекты сервер отдаёт в `hero_card.bonuses`). */
const EFFECT_KEYS: Array<[string, string]> = [
  ['attack_percent', 'Доп. урон в ближнем бою'], ['attack_range', 'Доп. стрелковый урон'],
  ['defence_percent', 'Защита в ближнем бою'], ['defence_war', 'Защита от магии'],
  ['defence_range', 'Защита от стрелков'], ['magic_resist', 'Пробивание магической защиты'],
  ['muf', 'Урон магией огня'], ['mua', 'Урон магией воздуха'], ['mue', 'Урон магией земли'],
  ['muw', 'Урон магией воды'], ['attack_nature', 'Доп. урон по нейтральным существам'],
];

let cardSide: Side | null = null;
/** Три экрана оригинала: характеристики → «Подробнее» (кукла, умения, армия) → «Эффекты» → «Информация» (назад). */
let cardTab: 'stats' | 'doll' | 'effects' = 'stats';
let cardAnchor: Element | null = null;

/** Показатели героя: у сервера, если бой идёт; иначе из панели героя и Примерочной. */
function heroCardData(side: Side): HeroCard | null {
  const live = hs.state && hs.state.hero_card && hs.state.hero_card[side === 'player' ? '0' : '1'];
  if (live) return live as HeroCard;
  const data = side === 'player' ? tacGetHeroData() : tacGetEnemyHeroData();
  if (!data) return null;
  const i = side === 'player' ? 0 : 1;
  const useArts = tacHeroArtifactEntries(i).length > 0;
  const art = useArts ? fittingArtifactTotals(i) : {};
  const a = (k: string) => art[k] || 0;
  const worn = fittingHero(i).equipment;
  return {
    name: fittingHeroName(i) || data.name || '',
    faction: data.faction || '',
    level: fittingHero(i).level || null,
    attack: (data.attack_bonus || 0) + a('attack'),
    defense: (data.defense_bonus || 0) + a('defence'),
    damage: heroDmgRange(fittingHero(i).level, (data.attack_bonus || 0) + a('attack')),
    spell_power: (data.spell_power || 0) + a('spellpower'),
    knowledge: (data.knowledge || 0) + a('knowledge'),
    initiative: 10 + a('initiative_hero'),
    mana: data.mana_max || 0,
    mana_max: data.mana_max || 0,
    morale: (data.morale_bonus || 0) + a('morale'),
    luck: (data.luck_bonus || 0) + a('luck'),
    perks: tacHeroPerkKeys(i),
    bonuses: EFFECT_KEYS.map(([k, label]) => ({ label, value: a(k) })).filter(b => b.value),
    artifacts: useArts
      ? Object.keys(worn).map(s => String((worn[s] as any).nameRu || worn[s].name || worn[s].key)) : [],
  };
}

/** Вилка удара героя по БУ и Нападению: коэффициенты — из `hwm/hero_damage.py` (gameConstants.ts, генерируется). */
function heroDmgRange(level: number, attack: number): [number, number] {
  const L = Math.max(0, level || 0), A = Math.max(0, attack || 0);
  const fit = (c: readonly number[]) => c[0] + c[1] * L + c[2] * A + c[3] * L * A + c[4] * L * L;
  const lo = Math.max(1, Math.round(fit(HERO_DMG_MIN_FIT)));
  return [lo, Math.max(lo, Math.round(fit(HERO_DMG_MAX_FIT)))];
}

function escapeHtml(t: string): string {
  return t.replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' } as Record<string, string>)[c]);
}

function statsHtml(c: HeroCard): string {
  const row = (icon: string, label: string, val: string) =>
    `<div class="tac-info-row"><img src="${ICON_BASE}${icon}" alt=""><span>${label}</span>`
    + `<span class="tac-info-val">${val}</span></div>`;
  const dmg = c.damage[0] === c.damage[1] ? String(c.damage[0]) : `${c.damage[0]} - ${c.damage[1]}`;
  return '<div class="tac-hero-card-rows">'
    + row('attr_attack.png', 'Нападение', String(c.attack))
    + row('attr_defense.png', 'Защита', String(c.defense))
    + row('attr_damage.png', 'Урон', dmg)
    + row('attr_magicpower.png', 'Сила магии', String(c.spell_power))
    + row('attr_knowledge.png', 'Знания', String(c.knowledge))
    + row('attr_initiative.png', 'Инициатива', c.initiative == null ? '—' : String(Math.round(c.initiative * 10) / 10))
    + row('attr_mana.png', 'Мана', c.mana_max > 0 ? `${c.mana}/${c.mana_max}` : '-')
    + row('attr_morale.png', 'Боевой дух', String(c.morale))
    + row('attr_fortune.png', 'Удача', String(c.luck))
    + '</div>';
}

/** Номера фракций в значках `i/f/r<N>.png` и умениях героя (`umelka`): порядок оригинала. */
const FACTION_ICON_NO: Record<string, number> = {
  knight: 1, necromance: 2, magi: 3, elf: 4, barbarian: 5,
  telf: 6, demon: 7, dwarf: 8, stepbarbarian: 9, faraon: 10,
};

interface ArmyUnit { img: string; count: number; name: string }

/** Отряды стороны: в бою — из состояния сервера, до боя — с доски расстановки. До семи портретов. */
function armyOf(side: Side): ArmyUnit[] {
  const stacks: any[] = (hs.state && (hs.state as any).stacks) || [];
  if (stacks.length) {
    const want = side === 'player' ? 0 : 1;
    return stacks
      .filter(s => s.side === want && s.count > 0 && s.alive !== false)
      .slice(0, 7)
      .map(s => ({ img: portraitUrl(String(s.sys_name)), count: Number(s.count), name: String(s.name || s.sys_name) }));
  }
  const team = side === 'player' ? 1 : 2;
  const out: ArmyUnit[] = [];
  for (const row of battleBoard.data) {
    for (const cell of row || []) {
      if (!cell || cell === true || cell.team !== team) continue;
      const u = TACTIC_UNITS[cell.id];
      if (u) out.push({ img: tacPortraitUrl(u.pic), count: Number(cell.cnt) || 1, name: u.name });
    }
  }
  return out.slice(0, 7);
}

function portraitUrl(sys: string): string {
  const u: any = (allData as any).units?.[sys] || {};
  const anim = u.animUnit || u.anim_unit || '';
  return staticsIconUrl(anim) || (anim ? `/images/portraits/${anim}p60.png` : '');
}

/** Экран «Подробнее» (win_InfoHero2 оригинала): слева параметры, в центре кукла с предметами,
 * справа умения героя по фракциям, внизу армия. */
function dollHtml(c: HeroCard, side: Side): string {
  const i = side === 'player' ? 0 : 1;
  const art = fittingArtifactTotals(i) as Record<string, number>;
  const data: any = (side === 'player' ? tacGetHeroData() : tacGetEnemyHeroData()) || {};
  const flvl = Number(data.faction_lvl) || 0;
  const own = FACTION_ICON_NO[c.faction] || 0;
  const ico = (file: string) => `<img src="${ICON_BASE}${file}" alt="">`;
  const left = (icon: string, val: string | number, hint = '') =>
    `<div class="bhc-stat" title="${escapeHtml(hint)}">${icon}<b>${val}</b></div>`;
  const special = c.bonuses || [];
  const initPct = art.initiative_percent || 0;
  const leftCol = '<div class="bhc-col bhc-col-l">'
    + left(ico('attr_attack.png'), c.attack, 'Нападение')
    + left(ico('attr_defense.png'), c.defense, 'Защита')
    + left(ico('attr_magicpower.png'), c.spell_power, 'Сила магии')
    + left(ico('attr_knowledge.png'), c.knowledge, 'Знания')
    + left(ico('attr_fortune.png'), c.luck, 'Удача')
    + left(ico('attr_morale.png'), c.morale, 'Боевой дух')
    + left(ico('attr_initiative.png'), c.initiative == null ? '—' : Math.round(c.initiative * 10) / 10, 'Инициатива')
    + left('<span class="bhc-orb">🔮</span>', special.length,
           special.length ? special.map(b => `${b.label}: +${b.value}%`).join('\n') : 'Особых эффектов артефактов нет')
    + left(ico('attr_oa.png'), art.oa || 0, 'ОА')
    + left(ico('attr_initiative2.png'), `${initPct}`, 'Инициатива, %')
    + '</div>';
  let rows = '';
  for (let k = 1; k <= 10; k++) {
    const val = k === own ? flvl : 0;
    rows += `<div class="bhc-stat${k === own ? ' own' : ''}"><img src="${cdnImg('https://dcdn.heroeswm.ru/i/f/r' + k + '.png')}" alt="">`
      + `<b>${val}</b></div>`;
  }
  const rightCol = `<div class="bhc-col bhc-col-r">${rows}</div>`;
  const army = armyOf(side);
  let armyHtml = '';
  for (let k = 0; k < 7; k++) {
    const u = army[k];
    armyHtml += u
      ? `<div class="bhc-unit" title="${escapeHtml(u.name)}"><img src="${u.img}" alt="" onerror="this.style.visibility='hidden'">`
        + `<span>${u.count}</span></div>`
      : '<div class="bhc-unit empty"></div>';
  }
  return `<div class="bhc-doll-row">${leftCol}${fittingDollStatic(i)}${rightCol}</div>`
    + `<div class="bhc-army">${armyHtml}</div>`;
}

/** Экран «Эффекты» (show_effects оригинала): значки навыков героя и таблица «Тип / Эффект / Время». */
function effectsHtml(c: HeroCard): string {
  const icons = c.perks.map(k => {
    const d = HERO_SKILL_DESCS[k];
    const src = d?.img || '';
    return src ? `<div class="bhc-perk" title="${escapeHtml(d?.name || k)}"><img src="${src}" alt="" onerror="this.parentElement.style.display='none'"></div>` : '';
  }).join('');
  const bonuses = c.bonuses || [];
  // Фракционное умение в эффектах не пишем — оно отдельным блоком в панели героя.
  const rows = bonuses.map(b => `<tr><td class="t">${escapeHtml(b.label)}</td><td>+${b.value}%</td><td>-</td></tr>`).join('');
  return (icons ? `<div class="bhc-perks">${icons}</div>` : '')
    + (rows
      ? `<table class="bhc-eff"><thead><tr><th>Тип</th><th>Эффект</th><th>Время</th></tr></thead><tbody>${rows}</tbody></table>`
      : '<div class="tac-info-note">Эффектов нет.</div>');
}

function render(): void {
  if (!cardSide) return;
  const c = heroCardData(cardSide);
  const old = tacById('tac-unit-tooltip');
  if (old) old.remove();
  const tip = document.createElement('div');
  tip.id = 'tac-unit-tooltip';
  tip.className = 'hwm-window tac-info-window tac-hero-card';
  if (!c) {
    tip.innerHTML = '<div class="tac-info-title">Герой не выбран</div>';
  } else {
    const meta = FACTIONS_META[c.faction];
    const icon = allData.factions?.[c.faction]?.icon || allData.factions?.[c.faction]?.classes?.[0]?.icon || '';
    const who = cardSide === 'player' ? 'Вы' : 'Противник';
    const title = `<div class="tac-info-title">`
      + (icon ? `<img class="tac-hero-card-icon" src="${cdnImg(icon)}" alt="" title="${meta?.nameRu || c.faction}">` : '')
      + escapeHtml(c.name || who) + (c.level ? `<span class="tac-info-cnt tac-hero-card-star">★ ${c.level}</span>` : '')
      + '</div><div class="hwm-sep"></div>';
    const next = cardTab === 'stats' ? 'Подробнее' : cardTab === 'doll' ? 'Эффекты' : 'Информация';
    const actions = '<div class="hwm-sep"></div><div class="tac-info-actions">'
      + `<button type="button" class="hwm-btn" onclick="tacHeroCardEffects()">${next}</button>`
      + '<button type="button" class="hwm-btn" onclick="tacCloseUnitInfo()">Закрыть</button></div>';
    const body = cardTab === 'doll' ? dollHtml(c, cardSide) : cardTab === 'effects' ? effectsHtml(c) : statsHtml(c);
    tip.classList.toggle('tac-hero-card--wide', cardTab !== 'stats');
    tip.innerHTML = title + body + actions;
  }
  document.body.appendChild(tip);
  tacPlaceInfoWindow(tip, cardAnchor && cardAnchor.isConnected ? cardAnchor : tacById('tac-field'));
}

/** Открыть карточку героя стороны `side` у `anchor` (кукла или фишка). Повторный клик закрывает. */
export function tacShowHeroCard(side: Side, anchor?: Element | null): void {
  const open = tacById('tac-unit-tooltip');
  if (open && open.classList.contains('tac-hero-card') && cardSide === side) {
    tacCloseUnitInfo();
    cardSide = null;
    return;
  }
  tacCloseUnitInfo();
  cardSide = side;
  cardTab = 'stats';
  cardAnchor = anchor || null;
  render();
  tacArmInfoDismiss();
}

/** Кнопка слева в карточке: «Подробнее» → «Эффекты» → «Информация» (назад к характеристикам). */
export function tacHeroCardEffects(): void {
  cardTab = cardTab === 'stats' ? 'doll' : cardTab === 'doll' ? 'effects' : 'stats';
  render();
}
