// Вкладка «Заглушки»: способности, объявленные в реестре эффектов, за которыми
// нет кода. Запись есть, в карточке существа умение показывается — а в бою оно
// не делает ничего.
//
// Список считает сервер по исходникам (battle/effects/introspect.py). Держать
// его в данных нельзя: он меняется от каждой правки боевого кода, и рукописная
// версия врала бы — показывала бы починенное как мёртвое и наоборот.
import { allData } from './data.js';
import { navigateTo } from './navigation.js';

interface StubItem {
  key: string;
  isStub: boolean;
  isAura: boolean;
  codeTotal: number;
  testsTotal: number;
  stats: string[];
  triggers: string[];
  types: string[];
}
interface StubSummary {
  items: StubItem[];
  total: number;
  stubs: number;
  stubsUntested: number;
  nonBattle: number;
  descMismatch: number;
}

var _summary: StubSummary | null = null;
var _carriers: Record<string, number> | null = null;

function carriersByAbility(): Record<string, number> {
  if (_carriers) return _carriers;
  var map: Record<string, number> = {};
  var units = allData.units || {};
  for (var key in units) {
    var skills = units[key].skills;
    if (!Array.isArray(skills)) continue;
    for (var i = 0; i < skills.length; i++) map[skills[i]] = (map[skills[i]] || 0) + 1;
  }
  _carriers = map;
  return map;
}

function escapeHtml(s: unknown): string {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function abilityName(key: string): string {
  var a = allData.abilities && allData.abilities[key];
  return (a && a.name) || key;
}

function renderStubs(): void {
  var body = document.getElementById('stub-body');
  var countEl = document.getElementById('stub-count');
  if (!body || !_summary) return;

  var searchEl = document.getElementById('stub-search') as HTMLInputElement | null;
  var untestedEl = document.getElementById('stub-untested') as HTMLInputElement | null;
  var q = (searchEl ? searchEl.value : '').toLowerCase();
  var onlyUntested = !!(untestedEl && untestedEl.checked);

  var carriers = carriersByAbility();
  var list = _summary.items.filter(function(it) { return it.isStub; });
  if (onlyUntested) list = list.filter(function(it) { return !it.testsTotal; });
  if (q) {
    list = list.filter(function(it) {
      return it.key.toLowerCase().indexOf(q) >= 0 ||
        abilityName(it.key).toLowerCase().indexOf(q) >= 0;
    });
  }
  // По числу носителей: это порядок, в котором их стоит чинить — умение на
  // четырнадцати отрядах важнее умения на одном.
  list.sort(function(a, b) {
    return (carriers[b.key] || 0) - (carriers[a.key] || 0) || a.key.localeCompare(b.key);
  });

  var slots = list.reduce(function(sum, it) { return sum + (carriers[it.key] || 0); }, 0);
  if (countEl) {
    countEl.textContent = list.length + ' из ' + _summary.stubs + ' · ' + slots + ' слотов существ';
  }

  body.innerHTML = list.length
    ? '<table class="stub-table"><thead><tr>' +
      '<th>Способность</th><th>Ключ</th><th class="num">Носителей</th>' +
      '<th class="num">Тестов</th><th>Что объявлено</th>' +
      '</tr></thead><tbody>' +
      list.map(function(it) {
        var declared = it.types.concat(it.triggers).join(' · ');
        return '<tr data-key="' + escapeHtml(it.key) + '">' +
          '<td class="stub-name">' + escapeHtml(abilityName(it.key)) +
          (it.isAura ? ' <span class="stub-tag">аура</span>' : '') + '</td>' +
          '<td><code>' + escapeHtml(it.key) + '</code></td>' +
          '<td class="num">' + (carriers[it.key] || 0) + '</td>' +
          '<td class="num' + (it.testsTotal ? '' : ' stub-zero') + '">' + it.testsTotal + '</td>' +
          '<td class="stub-declared">' + escapeHtml(declared) +
          (it.stats.length ? ' <code>' + escapeHtml(it.stats.join(', ')) + '</code>' : '') +
          '</td></tr>';
      }).join('') + '</tbody></table>'
    : '<div class="stub-empty">Ничего не найдено.</div>';

  body.querySelectorAll('tr[data-key]').forEach(function(row) {
    row.addEventListener('click', function() {
      navigateTo('/abilities/' + (row as HTMLElement).dataset.key);
    });
  });
}

async function initStubs(): Promise<void> {
  var body = document.getElementById('stub-body');
  var summaryEl = document.getElementById('stub-summary');
  if (!body) return;
  if (_summary) { renderStubs(); return; }

  body.innerHTML = '<div class="stub-empty">Считаем по исходникам…</div>';
  try {
    var res = await fetch('/api/abilities/impl');
    if (!res.ok) throw new Error('HTTP ' + res.status);
    _summary = await res.json() as StubSummary;
  } catch (e) {
    body.innerHTML = '<div class="stub-empty">Не удалось получить сводку: ' +
      escapeHtml((e as Error)?.message || e) + '</div>';
    return;
  }
  if (summaryEl) {
    var carriers = carriersByAbility();
    var slots = _summary.items
      .filter(function(i) { return i.isStub; })
      .reduce(function(s, i) { return s + (carriers[i.key] || 0); }, 0);
    summaryEl.innerHTML =
      '<b>' + _summary.stubs + '</b> заглушек из <b>' + _summary.total + '</b> записей реестра. ' +
      'Их носят <b>' + slots + '</b> отрядов, и в бою эти умения не делают ничего. ' +
      '<b>' + _summary.stubsUntested + '</b> из них не упомянуты ни в одном тесте.' +
      (_summary.nonBattle
        ? ' Ещё <b>' + _summary.nonBattle + '</b> помечены как механики вне боя ' +
          'и в список не входят: чинить в симуляторе у них нечего.'
        : '') +
      (_summary.descMismatch
        ? ' Отдельно: у <b>' + _summary.descMismatch + '</b> записей реализация ' +
          'расходится с игровым описанием — это видно на карточке способности.'
        : '') +
      '<div class="stub-note">Список считается по исходникам при каждом открытии вкладки — ' +
      'починенное умение уходит из него само.</div>';
  }
  renderStubs();
}

function filterStubs(): void { renderStubs(); }

export { initStubs, filterStubs, renderStubs };
