/**
 * «Огненная стена» в карточке справочника — тем же рендерером, что у боя оригинала и
 * справки daily-help (`firewall_new_effect = 1`): не покадровый атлас движка
 * (`anim_data40/firewall.js`), а описание `effects/atlases/firewall.json` + одна
 * картинка, по которой кадры идут прямо с `fps` из описания.
 *
 * Три пламени стоят по диагонали «верхняя клетка → средняя → нижняя», каждое с
 * случайным стартовым кадром и зеркалом (так в бою `firewall_effect_start()`), растут за
 * первые 100 мс и дальше просто крутятся по кругу — плавно и без пауз. Порт
 * `FirewallEffectCanvasRenderer` из справки.
 */

const EFFECT_VERSION = 1012;
const ATLAS_BASE = '/api/cache/i/effects/atlases/';

interface FirewallEffect {
  image: string; frameWidth: number; frameHeight: number; cols: number; rows: number;
  frames: number; fps: number; drawWidth: number; drawHeight: number;
  anchorX: number; anchorY: number; blend: string; atlasX: number; atlasY: number;
}

interface Instance { x: number; y: number; startFrame: number; sx: number; sy: number }

function num(raw: any, name: string, fallback: number, min = 0): number {
  const v = Number(raw[name]);
  return isFinite(v) && v > min ? v : fallback;
}

function loadImage(url: string): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error('firewall atlas: ' + url));
    img.src = url;
  });
}

let resources: Promise<{ effect: FirewallEffect; image: HTMLImageElement }> | null = null;

function loadResources() {
  if (resources) return resources;
  resources = fetch(`${ATLAS_BASE}firewall.json?v=${EFFECT_VERSION}`)
    .then(r => { if (!r.ok) throw new Error('firewall.json ' + r.status); return r.json(); })
    .then(async (raw: any) => {
      const effect: FirewallEffect = {
        image: String(raw.image || ''),
        frameWidth: num(raw, 'frameWidth', 0), frameHeight: num(raw, 'frameHeight', 0),
        cols: Math.max(1, Math.floor(num(raw, 'cols', 1))), rows: Math.max(1, Math.floor(num(raw, 'rows', 1))),
        frames: Math.max(1, Math.floor(num(raw, 'frames', 1))), fps: num(raw, 'fps', 30),
        drawWidth: num(raw, 'drawWidth', 0), drawHeight: num(raw, 'drawHeight', 0),
        anchorX: num(raw, 'anchorX', 0, -1), anchorY: num(raw, 'anchorY', 0, -1),
        blend: String(raw.blend || 'normal').toLowerCase(),
        atlasX: num(raw, 'atlasX', 0, -1), atlasY: num(raw, 'atlasY', 0, -1),
      };
      if (!/^[A-Za-z0-9_-]+\.png$/.test(effect.image) || !effect.frameWidth || !effect.frameHeight
          || !effect.drawWidth || !effect.drawHeight) throw new Error('firewall.json: bad descriptor');
      effect.frames = Math.min(effect.frames, effect.cols * effect.rows);
      const image = await loadImage(`${ATLAS_BASE}${encodeURIComponent(effect.image)}?v=${EFFECT_VERSION}`);
      return { effect, image };
    })
    .catch(e => { resources = null; throw e; });
  return resources;
}

export interface FirewallPreview { destroy(): void }

/** Нарисовать стену на canvas внутри `host`. Резолвится `null`, если ресурсов нет. */
export async function mountFirewallEffect(host: HTMLElement, size: number): Promise<FirewallPreview | null> {
  let res;
  try { res = await loadResources(); } catch { return null; }
  const { effect, image } = res;
  const canvas = document.createElement('canvas');
  const ratio = Math.max(1, Math.min(2, window.devicePixelRatio || 1));
  canvas.width = Math.round(size * ratio);
  canvas.height = Math.round(size * ratio);
  canvas.style.width = size + 'px';
  canvas.style.height = size + 'px';
  host.appendChild(canvas);
  const ctx = canvas.getContext('2d');
  if (!ctx) { canvas.remove(); return null; }

  // Три смежные клетки: верхняя → средняя → нижняя, глубина вдоль диагонали сетки боя.
  const dx = Math.max(24, Math.min(42, effect.drawWidth * 0.16));
  const dy = Math.max(58, Math.min(88, effect.drawHeight * 0.34));
  const instances: Instance[] = [{ x: -dx, y: -dy }, { x: 0, y: 0 }, { x: dx, y: dy }].map(p => ({
    ...p,
    startFrame: Math.min(effect.frames - 1, Math.floor(Math.random() * effect.frames)),
    sx: (Math.random() < 0.5 ? -1 : 1) * (0.97 + Math.random() * 0.06),
    sy: 0.95 + Math.random() * 0.05,
  }));
  const anchorX = effect.anchorX / effect.frameWidth * effect.drawWidth;
  const anchorY = effect.anchorY / effect.frameHeight * effect.drawHeight;
  const xr = Math.max(anchorX, effect.drawWidth - anchorX) * 1.035;
  const yr = Math.max(anchorY, effect.drawHeight - anchorY) * 1.005;
  const b = { l: Infinity, t: Infinity, r: -Infinity, b: -Infinity };
  for (const i of instances) {
    b.l = Math.min(b.l, i.x - xr); b.r = Math.max(b.r, i.x + xr);
    b.t = Math.min(b.t, i.y - yr); b.b = Math.max(b.b, i.y + yr);
  }
  const pad = Math.max(12, size * 0.055);
  let scale = Math.min((size - pad * 2) / Math.max(1, b.r - b.l), (size - pad * 2) / Math.max(1, b.b - b.t), 3);
  if (!isFinite(scale) || scale <= 0) scale = 1;
  const cx = size / 2 - (b.l + b.r) * 0.5 * scale;
  const cy = size / 2 - (b.t + b.b) * 0.5 * scale;

  let raf = 0;
  let start = 0;
  const render = (time: number) => {
    const elapsed = start ? Math.max(0, time - start) : 0;
    const growth = elapsed >= 100 ? 1 : 0.1 + 0.9 * Math.min(1, elapsed / 100);
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
    for (const i of instances) {
      const frame = (i.startFrame + Math.floor(elapsed * effect.fps / 1000)) % effect.frames;
      const sx = effect.atlasX + (frame % effect.cols) * effect.frameWidth;
      const sy = effect.atlasY + Math.floor(frame / effect.cols) * effect.frameHeight;
      ctx.save();
      ctx.globalCompositeOperation = effect.blend === 'lighter' ? 'lighter' : 'source-over';
      ctx.translate(cx + i.x * scale, cy + i.y * scale);
      ctx.scale(i.sx * growth * scale, i.sy * growth * scale);
      ctx.drawImage(image, sx, sy, effect.frameWidth, effect.frameHeight,
                    -anchorX, -anchorY, effect.drawWidth, effect.drawHeight);
      ctx.restore();
    }
  };
  const tick = (time: number) => {
    if (!start) start = time;
    render(time);
    raf = requestAnimationFrame(tick);
  };
  render(0);
  raf = requestAnimationFrame(tick);
  return { destroy() { cancelAnimationFrame(raf); canvas.remove(); } };
}
