/** Номер куклы героя у игровой фракции: `i/kukla_png/premium/p<N>ap.png` (та же нумерация, что у Примерочной). */
/** Манифест платных образов (`web/images/kukla_premium/index.json`: {фракция: [файлы]}). */
let premiumDolls: Record<string, string[]> | null = null;
let premiumDollsLoading: Promise<void> | null = null;

function loadPremiumDolls(): Promise<void> {
  if (premiumDolls) return Promise.resolve();
  if (!premiumDollsLoading) {
    premiumDollsLoading = fetch('/images/kukla_premium/index.json')
      .then(r => (r.ok ? r.json() : {}))
      .then(j => { premiumDolls = j || {}; })
      .catch(() => { premiumDolls = {}; });
  }
  return premiumDollsLoading;
}

/** Два РАЗНЫХ случайных образа фракции — свои при каждом открытии вкладки. */
function pickDolls(fname: string): string[] {
  const all = (premiumDolls?.[fname] || []).slice();
  for (let i = all.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [all[i], all[j]] = [all[j], all[i]];
  }
  return all.slice(0, 2);
}

