/** Куклы нейтральных фракций (daily-help `img/dolls`, лежат в `web/images/dolls_neutral/`). */
const NEUTRAL_DOLLS: Record<string, string> = {
  winter: 'pers_ice-ai', necr: 'mumr-ai', rebellious_tribes: 'leadernp1-ai',
  amfibies: 'leader42-ai', inferno: 'leader2-ai', necrotime: 'leader3a-ai',
  knightsun: 'leaderink-ai',
};

/** Кукла нейтральной фракции — поменьше игровых; подгружается лениво (`data-src`), только когда
 *  карточка подъезжает к окну (см. observeNeutralDolls): ниже по странице — тяжёлые картинки. */
function neutralDollHtml(fname: string, title: string): string {
  const file = NEUTRAL_DOLLS[fname];
  if (!file) return '';
  return `<div class="faction-hero-dolls faction-neutral-dolls"><img class="faction-hero-doll" data-src="${'/images/dolls_neutral/' + file + '.png'}" alt="${title}" title="${title}" width="200" height="200" onerror="if(!this.dataset.r){this.dataset.r=1;var u=this.src.split('?')[0];var im=this;setTimeout(function(){im.src=u+'?r='+Date.now()},1200)}else{this.parentNode.style.display='none'}"></div>`;
}

let neutralDollObserver: IntersectionObserver | null = null;
function observeNeutralDolls(root: HTMLElement | null): void {
  if (!root) return;
  const imgs = Array.from(root.querySelectorAll<HTMLImageElement>('img.faction-hero-doll[data-src]'));
  if (!imgs.length) return;
  const load = (img: HTMLImageElement) => { img.src = img.dataset.src || ''; img.removeAttribute('data-src'); };
  if (typeof IntersectionObserver === 'undefined') { imgs.forEach(load); return; }
  neutralDollObserver?.disconnect();
  neutralDollObserver = new IntersectionObserver(entries => {
    for (const e of entries) {
      if (!e.isIntersecting) continue;
      load(e.target as HTMLImageElement);
      neutralDollObserver?.unobserve(e.target);
    }
  }, { rootMargin: '500px 0px' });   // начинаем грузить, когда до карточки ~полтора экрана
  imgs.forEach(img => neutralDollObserver!.observe(img));
}

/** Случайные платные образы при каждом открытии вкладки — пока выключены (включить: true).
 *  Скачанные образы лежат в `web/images/kukla_premium/` (scripts/download_premium_dolls.py). */
const FACTION_DOLLS_RANDOM = false;

/** Куклы героя фракции столбиком справа: два платных образа (`ap` и `dp`; у фараона один класс, образов тоже два).
 *  При `FACTION_DOLLS_RANDOM` вместо них — два случайных платных образа своей фракции. */
function factionDollsHtml(fname: string, classes: any[]): string {
  const num = FACTION_DOLL_NUM[fname];
  if (!num) return '';
  const picked = FACTION_DOLLS_RANDOM ? pickDolls(fname) : [];
  // Только локальные файлы: `/api/img` на статическом сайте (GitHub Pages) нет, и куклы там пропадали.
  const premium = (suffix: string) => '/images/kukla_premium/p' + num + suffix + '.png';
  const items: Array<{ url: string; title: string }> = picked.length
    ? picked.map(n => ({ url: '/images/kukla_premium/' + n, title: classes[0]?.nameRu || classes[0]?.name || '' }))
    : [{ url: premium('ap'), title: classes[0]?.nameRu || classes[0]?.name || '' },
       { url: premium(SECOND_DOLL_SUFFIX[fname] || 'dp'), title: classes[1]?.nameRu || classes[1]?.name || classes[0]?.nameRu || '' }];
  const img = (it: { url: string; title: string }) =>
    `<img class="faction-hero-doll" src="${it.url}" alt="${it.title}" title="${it.title}" loading="lazy" onerror="if(!this.dataset.r){this.dataset.r=1;var u=this.src.split('?')[0];var im=this;setTimeout(function(){im.src=u+'?r='+Date.now()},1200)}else{this.style.display='none'}">`;
  return `<div class="faction-hero-dolls">${items.map(img).join('')}</div>`;
}

/** Второй образ по умолчанию — `dp`; у фараона, гнома и некроманта по просьбе выбран `cp`, у варвара — `robberp`. */
const SECOND_DOLL_SUFFIX: Record<string, string> = {
  faraon: 'cp', dwarf: 'cp', barbarian: 'robberp', necromance: 'cp',
};

const FACTION_DOLL_NUM: Record<string, number> = {
  knight: 1, necromance: 2, magi: 3, elf: 4, barbarian: 5,
  telf: 6, demon: 7, dwarf: 8, stepbarbarian: 9, faraon: 10,
};


/** Увеличенная кукла: плавно проявляется поверх страницы, закрывается кликом или Esc. */
function openDollZoom(src: string, title: string): void {
  document.getElementById('doll-zoom')?.remove();
  const box = document.createElement('div');
  box.id = 'doll-zoom';
  box.className = 'doll-zoom';
  box.innerHTML = `<img src="${src}" alt="${title}">${title ? `<div class="doll-zoom-cap">${title}</div>` : ''}`;
  const close = () => {
    document.removeEventListener('keydown', onKey);
    box.classList.remove('doll-zoom-on');
    setTimeout(() => box.remove(), 250);
  };
  const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') close(); };
  box.addEventListener('click', close);
  document.addEventListener('keydown', onKey);
  document.body.appendChild(box);
  requestAnimationFrame(() => box.classList.add('doll-zoom-on'));
}

function renderFactions(): void {
  // Манифест платных образов грузится один раз; до этого страница перерисуется сама.
  if (FACTION_DOLLS_RANDOM && !premiumDolls) { void loadPremiumDolls().then(() => renderFactions()); return; }
  const detail = document.getElementById('faction-detail');
  if (detail) { detail.style.display = 'none'; detail.innerHTML = ''; }
  const playableDiv = document.getElementById('faction-playable');
  const neutralDiv = document.getElementById('faction-neutral');
  if (playableDiv) playableDiv.style.display = '';
  if (neutralDiv) neutralDiv.style.display = '';

  const factionUnits: Record<string, UnitRecord[]> = {};
  if (allData.units) {
    for (const u of Object.values(allData.units)) {
      if (u.fraction) {
        if (!factionUnits[u.fraction]) factionUnits[u.fraction] = [];
        factionUnits[u.fraction].push(u);
      }
    }
  }

  function renderFactionBlock(fname: string, isPlayable: boolean): string {
    const meta = FACTIONS_META[fname];
    if (!meta) return '';
    // Состав фракции — по её таблице существ (она же рисует страницу фракции):
    // поле fraction у самих существ есть не у всех, и у ётунов счёт выходил «0 шт».
    const table = allData.unitsByFaction?.[fname];
    const names = new Set<string>();
    const tiers: number[] = [];
    if (table) {
      for (const t of Object.keys(table)) {
        const cols = table[t] || {};
        let any = false;
        for (const c of Object.keys(cols)) for (const sn of cols[c] || []) { names.add(sn); any = true; }
        if (any) tiers.push(parseInt(t));
      }
      tiers.sort((a, b) => a - b);
    }
    const units = names.size ? [...names] : (factionUnits[fname] || []).map(u => u.sysName);
    if (!names.size) {
      for (const t of new Set((factionUnits[fname] || []).map(u => u.tier || u.lvl).filter(Boolean))) tiers.push(t);
      tiers.sort((a, b) => a - b);
    }
    const classes = allData.factions?.[fname]?.classes || [];
    const iconUrl = allData.factions?.[fname]?.icon;
    // &c — сброс браузерного кэша (24 ч): до правки классификации кэша прокси значки
    // «Жителей рощи» и гноллов отдавались чужими картинками (одноимённый файл).
    const proxiedIcon = iconUrl ? `/api/img?url=${encodeURIComponent(iconUrl)}&c=2` : '';
    const desc = isPlayable
      ? (allData.factions?.[fname]?.descRu || allData.factions?.[fname]?.descEn || '')
      : (NEUTRAL_DESCS[fname] || '');
    // Шапка карточки — ссылка на саму фракцию: игрок жмёт по названию, ожидая
    // увидеть её существ, а не уходить на сторонний справочник. Значок — часть
    // шапки, отдельной внешней ссылки на нём нет.
    return `<div class="faction-card">
      <div class="faction-card-header faction-card-link"
           title="Открыть фракцию: ${meta.nameRu}"
           onclick="navigateTo('/factions/${encodeURIComponent(meta.nameEn)}')">
        ${iconUrl ? `<img src="${proxiedIcon}" class="faction-icon" loading="lazy" onload="if(this.naturalWidth&&this.naturalWidth<=64)this.classList.add('faction-icon-px')" onerror="this.style.display='none'">` : ''}
        <div>
          <h3>${meta.nameRu} (${meta.nameEn})</h3>
          ${!isPlayable ? '<div class="badge">Нейтральная</div>' : ''}
        </div>
      </div>
      <div class="faction-card-body">
      <div class="faction-card-main">
      ${desc ? `<div class="faction-desc">${desc}</div>` : ''}
      ${isPlayable && classes.length ? `<div class="classes"><div class="classes-title">Доступные классы:</div>${classes.map(c => `<div class="class-item"><span class="cname">${c.nameRu || c.name||''}</span>${c.skillNameRu ? '<div class="cskill">✦ ' + c.skillNameRu + '</div>' : ''}</div>`).join('')}</div>` : ''}
      <div class="tier-info">Существа: ${units.length} шт${tiers.length ? ', тиры: ' + tiers.join(', ') : ''}</div>
      <div style="margin-top:8px"><a href="/factions/${encodeURIComponent(meta.nameEn)}" onclick="event.preventDefault();navigateTo('/factions/${encodeURIComponent(meta.nameEn)}')" style="color:var(--gold);font-size:14px;text-decoration:none">→ Просмотр существ</a></div>
      </div>
      ${isPlayable ? factionDollsHtml(fname, classes) : neutralDollHtml(fname, meta.nameRu)}
      </div>
    </div>`;
  }

  // Зум по клику на куклу — у игровых и нейтральных фракций (слушатель один раз на контейнер).
  for (const box of [playableDiv, neutralDiv]) {
    if (!box || box.dataset.dollZoom) continue;
    box.dataset.dollZoom = '1';
    box.addEventListener('click', e => {
      const img = (e.target as HTMLElement | null)?.closest?.('img.faction-hero-doll') as HTMLImageElement | null;
      if (img && img.getAttribute('src')) openDollZoom(img.src, img.title || '');
    });
  }
  if (playableDiv) {
    playableDiv.innerHTML = '<h2 style="color:var(--gold);font-size:18px;margin-bottom:16px;padding-bottom:8px;border-bottom:1px solid var(--border)">ИГРАБЕЛЬНЫЕ ФРАКЦИИ</h2>' +
      PLAYABLE.map(f => renderFactionBlock(f, true)).join('');
  }
  if (neutralDiv) {
    neutralDiv.innerHTML = '<h2 style="color:var(--gold);font-size:18px;margin-bottom:16px;padding-bottom:8px;border-bottom:1px solid var(--border);margin-top:32px">НЕЙТРАЛЬНЫЕ ФРАКЦИИ</h2>' +
      NEUTRAL.map(f => renderFactionBlock(f, false)).join('');
    observeNeutralDolls(neutralDiv);
  }
}

function renderFactionTable(fnameEn: string): void {
  const detail = document.getElementById('faction-detail');
  const playable = document.getElementById('faction-playable');
  const neutral = document.getElementById('faction-neutral');
  if (!detail) return;
  
  var key: string | null = null;
  for (const [k, meta] of Object.entries(FACTIONS_META)) {
    if (meta.nameEn.toLowerCase() === fnameEn.toLowerCase()) { key = k; break; }
  }
  if (!key) key = fnameEn.toLowerCase();
  const meta = FACTIONS_META[key];
  if (!meta) { detail.innerHTML = '<div style="padding:20px;color:var(--text-dim)">Фракция не найдена</div>'; detail.style.display = 'block'; if (playable) playable.style.display = 'none'; if (neutral) neutral.style.display = 'none'; return; }

  detail.style.display = 'block';
  if (playable) playable.style.display = 'none';
  if (neutral) neutral.style.display = 'none';
  // Страница фракции открывается СВЕРХУ. Список длинный, и без этого игрок,
  // нажавший фракцию в самом низу, оказывался на середине её замка: прокрутка
  // страницы оставалась там, где была.
  window.scrollTo({ top: 0 });

  const sel = document.getElementById('faction-filter') as HTMLSelectElement;
  if (sel && sel.value !== key) sel.value = key;

  const byFaction = allData.unitsByFaction?.[key];
  if (!byFaction) { detail.innerHTML = '<div style="padding:20px;color:var(--text-dim)">Нет данных</div>'; return; }

  const tiers = Object.keys(byFaction).sort((a,b) => parseInt(a) - parseInt(b));
  const getUnit = (sysName: string): UnitRecord | null => {
    if (!sysName) return null;
    const units = allData.units;
    if (!units) return null;
    const val = units[sysName];
    if (val && (val.sysName === sysName || (val as any).sys_name === sysName)) return val;
    return Object.values(units).find(u => u.sysName === sysName || (u as any).sys_name === sysName) || null;
  };
  let maxCol = 0;
  for (const tier of tiers) {
    const row = byFaction[tier];
    for (const ci in row) {
      if (parseInt(ci) > maxCol) maxCol = parseInt(ci);
    }
  }
  const altHeaders = ALT_HEADER[key] || ['Улучшения РС'];
  // Колонки, где ни у одного тира нет существ, не показываем вовсе: ни шапки, ни прочерков.
  const usedCols: number[] = [];
  for (let ci = 0; ci <= maxCol; ci++) {
    if (tiers.some(t => (byFaction[t][String(ci)] || []).length)) usedCols.push(ci);
  }
  const totalCols = usedCols.length;

  const castleName = CASTLE_ANIMS[key];

  // Заголовок и замок стоят НАД таблицей, а не внутри неё. На узком экране
  // таблица уезжает в горизонтальную прокрутку (иначе колонки не помещаются и
  // обрезаются), и растянутая на всю её ширину видеовставка уехала бы вместе с
  // ней: замок пришлось бы отлистывать вбок.
  let html = `<h2 class="faction-title">${meta.nameRu}</h2>`;
  if (castleName) {
    html += `<div class="castle-anim"><video autoplay loop muted playsinline class="castle-video"><source src="/web/castles/${castleName}.mp4" type="video/mp4"></video></div>`;
  }
  let grid = '';

  const headers: string[] = ['Существа'];
  if (maxCol >= 1) headers.push('Улучшенные существа');
  for (const h of altHeaders) headers.push(h);

  // Header row
  for (const ci of usedCols) {
    grid += `<div class="faction-header">${headers[ci] || 'Особые существа'}</div>`;
  }

  // Data rows — one per tier
  for (const tier of tiers) {
    const row = byFaction[tier];
    for (const ci of usedCols) {
      const sysNames = row[String(ci)];
      if (sysNames && sysNames.length) {
        let cellHtml = '';
        for (const sn of sysNames) {
          const u = getUnit(sn);
          if (u) cellHtml += renderCreatureCard(u);
        }
        grid += `<div class="faction-col">${cellHtml}</div>`;
      } else {
        grid += `<div class="faction-col faction-col-empty"></div>`;
      }
    }
  }

  detail.className = 'faction-page';
  detail.style.display = '';
  // Число колонок отдаём переменной, а не инлайновым grid-template-columns:
  // инлайн перебивает медиазапрос, а на узком экране колонки должны быть
  // фиксированной ширины — с прокруткой вбок вместо нечитаемой каши.
  detail.style.setProperty('--faction-cols', String(totalCols));
  detail.innerHTML = html + `<div class="faction-layout">${grid}</div>`;
  detail.querySelectorAll('.creature-card').forEach(card => {
    card.addEventListener('click', function(this: HTMLElement, e) {
      var sn = this.dataset.sysname;
      if (sn) {
        try { openCreatureModal(sn); history.pushState(null, '', siteUrl('/units/' + sn)); }
        catch(ex) { console.error('openCreatureModal error:', ex); }
      }
    });
  });

  // Add faction classes section with skills
  renderFactionClasses(detail, key);
}

function renderFactionClasses(container: HTMLElement, factionKey: string): void {
  const factionData = allData.factions?.[factionKey];
  const classes = factionData?.classes || [];
  if (!classes.length) return;

  const classesSection = document.createElement('div');
  classesSection.className = 'faction-classes-section';
  classesSection.style.gridColumn = '1 / -1';

  let classesHtml = '<div class="faction-classes-title">Классы фракции</div>';

  classes.forEach((cls: any, classIndex: number) => {
    const iconUrl = cls.icon ? `/api/img?url=${encodeURIComponent(cls.icon)}` : '';
    const skillName = cls.skillNameRu || cls.skillName || '';
    let skillDesc = cls.skillDescRu || cls.skillDesc || '';
    // Картинки в описаниях из справочника лежат по относительным путям (`img/other/...`) на
    // daily-help.ru: без пересчёта в абсолютные они не грузятся (эльф: значки врагов, маг: мини-артефакты).
    skillDesc = skillDesc.replace(/(<img[^>]*\ssrc=")(img\/[^"]+)"/gi, (_m: string, head: string, rel: string) =>
      `${head}/api/img?url=${encodeURIComponent('https://daily-help.ru/' + rel)}" loading="lazy"`);
    // «Мини-артефакты» мага: таблицы из справочника приходят без картинок в шапке
    // (пустые столбцы) — рисуем свои: слева таблица, справа конструктор.
    // Пустые строки перед таблицей из справочника (`<br><br><table>`) — лишний зазор.
    skillDesc = skillDesc.replace(/(?:<br\s*\/?>\s*)+(?=<table)/gi, '');
    const isMiniArt = factionKey === 'magi' && skillName === 'Мини-артефакты';
    const isFavEnemy = factionKey === 'elf' && skillName === 'Заклятый враг';
    const isTamer = factionKey === 'telf' && skillName === 'Призыв подземных существ';
    // Таблица со ссылками «Калькулятор призыва» заменена своим блоком: слева существа, справа расчёт.
    if (isTamer) skillDesc = skillDesc.replace(/<table[\s\S]*?<\/table>/gi, '').replace(/(<br>\s*){2,}/gi, '');
    if (isMiniArt) skillDesc = skillDesc.replace(/<table[\s\S]*?<\/table>/gi, '').replace(/(<br>\s*){3,}/gi, '<br><br>');

    classesHtml += `
      <div class="faction-class-item" data-class-index="${classIndex}">
        <div class="faction-class-header">
          ${iconUrl ? `<img src="${iconUrl}" class="faction-class-icon" onerror="this.style.display='none'">` : '<div class="faction-class-icon" style="background:var(--card);display:flex;align-items:center;justify-content:center;color:var(--text-dim)">?</div>'}
          <div>
            <div class="faction-class-name">${cls.nameRu || cls.name || ''}</div>
            <div class="faction-class-skill">${skillName}</div>
          </div>
        </div>
        <!-- Колеса навыков здесь нет: у него свой раздел, а в карточке класса
             нужно фракционное умение — его название и описание. -->
        <div class="faction-skill-wheel">
          <div class="faction-skill-desc">
            <span class="skill-name">${skillName}</span>
            ${skillDesc.replace(/\n/g, '<br>')}
          </div>
        </div>
        <div class="faction-class-engine" data-class-name="${String(cls.nameRu || cls.name || '').replace(/"/g, '&quot;')}"></div>
        ${isMiniArt ? '<div class="mini-art" id="mini-art"></div>' : ''}
        ${isTamer ? '<div class="mini-art summon-calc" id="summon-calc"></div>' : ''}
        ${isFavEnemy ? '<div class="mini-art fav-enemy" id="fav-enemy"></div>' : ''}
      </div>
    `;
  });

  classesSection.innerHTML = classesHtml;
  container.appendChild(classesSection);
  const fav = classesSection.querySelector<HTMLElement>('#fav-enemy');
  if (fav) renderFavoredEnemies(fav);
  void fillClassEngine(classesSection, factionKey);
}

interface MiniArtifacts { kinds: string[]; kindsRu: string[]; table: number[][]; effectSteps: number[][]; }
let miniArtifactsData: MiniArtifacts | null = null;
interface SummonData {
  creatures: Record<string, string>; family: Record<string, string>;
  base: Record<string, Record<string, number>>; skillPct: number; decay: number; mana: number;
}
let summonData: SummonData | null = null;
interface ClassAbilityRow {
  faction: string; classRu: string; kind: string; status: string; statusRu: string;
  summary: string; refs: { file: string; symbol: string; what: string }[];
}
let classAbilityRows: ClassAbilityRow[] | null = null;

function escHtml(x: unknown): string {
  return String(x ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const MINI_ICON = ['attr_attack', 'attr_defense', 'attr_speed', 'attr_hit_points', 'attr_morale', 'attr_initiative'];
const miniIcon = (i: number) =>
  `<img class="mini-ico" alt="" src="/api/img?url=${encodeURIComponent('https://im.heroeswm.ru/i/icons/' + MINI_ICON[i] + '.png')}">`;
const MINI_PCT = 5;   // индекс «Инициатива»: её часть даёт проценты, остальные — очки

/** Сколько частей помещается в артефакт по боевому уровню героя: одна, с 5-го две, с 9-го три. */
function miniMaxParts(steps: number[][], combatLevel: number): number {
  let n = 1;
  for (const [from, parts] of steps) if (combatLevel >= from) n = parts;
  return n;
}

interface MiniArtifact { id: number; parts: number[]; level: number; wearer: string; hero: number; }

/** Слева — «Перечень доступных для создания мини-артефактов»: эффект одной части каждого
 * вида при умении фракции. Справа — конструктор: выбрать до N РАЗНЫХ частей (N по боевому
 * уровню), собрать артефакт и одеть его на отряд (на отряд — один артефакт). */
function renderMiniArtifacts(box: HTMLElement, d: MiniArtifacts): void {
  const fmt = (i: number, v: number) => (i === MINI_PCT ? `+${v}%` : `+${v}`);
  const head = d.kindsRu.map((k, i) => `<th title="${k}">${miniIcon(i)}</th>`).join('');
  const rows = d.table.map((r, lvl) =>
    `<tr data-lvl="${lvl}"><th>${lvl}</th>${r.map((n, i) => `<td>${n ? fmt(i, n).replace('+', '') : '–'}</td>`).join('')}</tr>`).join('');
  // Отряды мага — по одному на уровень существ, без улучшенных версий (в списке они
  // назывались бы «Големы» три раза): гремлины, горгульи, големы, маги, джинны, ракшасы, титаны.
  const units = ['Гремлины', 'Горгульи', 'Големы', 'Маги', 'Джинны', 'Ракшасы', 'Титаны']
    .map((name, i) => ({ sys: 'tier' + (i + 1), name }));
  const esc = (x: string) => x.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
  box.innerHTML = `
    <div class="mini-left">
      <div class="mini-title">Перечень доступных для создания мини-артефактов</div>
      <div class="mini-sub">Эффект одного параметра при данном умении мага</div>
      <table class="mini-table"><thead><tr><th>Умение<br>мага</th>${head}</tr></thead><tbody>${rows}</tbody></table>
      <ul class="mini-rules">
        <li>Инициатива даёт проценты, остальные параметры — очки.</li>
        <li>Параметры в артефакте должны быть разными.</li>
        <li>Параметров в артефакте: один, с 5-го боевого уровня два, с 9-го три; четвёртого нет.</li>
        <li>На отряд надевается только один мини-артефакт, на любой боевой отряд мага.</li>
        <li>Прочность бесконечная; эффект виден только в бою.</li>
      </ul>
    </div>
    <div class="mini-right">
      <div class="mini-head">
        <div class="mini-title">Собрать новый мини-артефакт</div>
        <div class="mini-heroes" id="mini-heroes" role="group" aria-label="Герой"></div>
      </div>
      <div class="mini-ctx" id="mini-ctx"></div>
      <div class="mini-pick" id="mini-pick"></div>
      <div class="mini-preview" id="mini-preview"></div>
      <button type="button" class="mini-build" id="mini-build">Собрать</button>
      <div class="mini-title mini-title-2">Мои мини-артефакты <span class="mini-count" id="mini-n"></span></div>
      <div class="mini-list" id="mini-list"></div>
    </div>`;
  const q = <T extends HTMLElement>(id: string) => box.querySelector('#' + id) as T;
  const ctxBox = q('mini-ctx'), heroesBox = q('mini-heroes');
  const pickBox = q('mini-pick'), prevBox = q('mini-preview');
  const listBox = q('mini-list'), countBox = q('mini-n'), buildBtn = q<HTMLButtonElement>('mini-build');
  const clampInt = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, Math.trunc(v) || lo));
  /** Умение фракции героя игрока — поле «Ур. фракции» во вкладке «Бой»; боевой уровень — Примерочная. */
  // У героев 1 и 2 свои комплекты: выбранный герой задаёт умение фракции (поле «Ур. фракции»
  // его панели в «Бое») и боевой уровень (его вкладка в Примерочной).
  const HERO_KEY = 'mini-hero-v1';
  let heroIdx = 0;
  try { heroIdx = localStorage.getItem(HERO_KEY) === '1' ? 1 : 0; } catch { heroIdx = 0; }
  const heroSkill = () => clampInt(parseInt((document.getElementById(heroIdx ? 'tac-hero2-flvl' : 'tac-hero-flvl') as HTMLInputElement | null)?.value || '') || DEFAULT_FACTION_LEVEL, 0, d.table.length - 1);
  const heroCombat = () => clampInt(Number(fittingHero(heroIdx)?.level) || DEFAULT_HERO_LEVEL, 1, 40);
  const KEY = 'mini-artifacts-v1';
  let list: MiniArtifact[] = [];
  try { list = JSON.parse(localStorage.getItem(KEY) || '[]') as MiniArtifact[]; } catch { list = []; }
  // Отряд, записанный старой версией списка (имя существа), больше не в перечне — снимаем.
  list.forEach(a => { if (!units.some(u => u.sys === a.wearer)) a.wearer = ''; if (a.hero !== 1) a.hero = 0; });
  const save = () => { try { localStorage.setItem(KEY, JSON.stringify(list)); } catch { /* без хранилища список живёт до перезагрузки */ } };
  let sel: number[] = [];
  const effects = (parts: number[], level: number) =>
    parts.map(i => `<span class="mini-eff">${miniIcon(i)}<b>${fmt(i, d.table[level][i])}</b></span>`).join('');

  function redrawPick(): void {
    const lvl = heroSkill(), combat = heroCombat();
    const max = miniMaxParts(d.effectSteps, combat);
    sel = sel.filter(i => d.table[lvl][i] > 0).slice(0, max);
    ctxBox.innerHTML = `<span class="mini-chip">Умение фракции <b>${lvl}</b></span>
      <span class="mini-chip">Боевой уровень <b>${combat}</b></span>
      <span class="mini-chip mini-chip-cap">Параметров в артефакте: <b>до ${max}</b></span>
      <span class="mini-ctx-note">Берутся у выбранного героя: уровень — в Примерочной, умение фракции — во вкладке «Бой»</span>`;
    heroesBox.innerHTML = [0, 1].map(i =>
      `<button type="button" class="mini-hero ${i === heroIdx ? 'on' : ''}" data-h="${i}" aria-pressed="${i === heroIdx}">Герой ${i + 1}<span class="mini-hero-name">${esc(fittingHeroName(i) || '')}</span></button>`).join('');
    heroesBox.querySelectorAll<HTMLElement>('.mini-hero').forEach(b => b.addEventListener('click', () => {
      heroIdx = Number(b.dataset.h) === 1 ? 1 : 0;
      try { localStorage.setItem(HERO_KEY, String(heroIdx)); } catch { /* выбор живёт до перезагрузки */ }
      sel = []; redrawPick(); redrawList();
    }));
    box.querySelectorAll<HTMLElement>('.mini-table tbody tr').forEach(tr =>
      tr.classList.toggle('mini-cur', Number(tr.dataset.lvl) === lvl));
    pickBox.innerHTML = d.kindsRu.map((k, i) => {
      const v = d.table[lvl][i], on = sel.includes(i);
      const off = !v || (!on && sel.length >= max);
      return `<button type="button" class="mini-card ${on ? 'on' : ''}" data-i="${i}" ${off ? 'disabled' : ''}>
        ${miniIcon(i)}<span class="mini-card-name">${k}</span><b>${v ? fmt(i, v) : '–'}</b></button>`;
    }).join('');
    pickBox.querySelectorAll<HTMLElement>('.mini-card').forEach(b => b.addEventListener('click', () => {
      const i = Number(b.dataset.i);
      sel = sel.includes(i) ? sel.filter(x => x !== i) : [...sel, i];
      redrawPick();
    }));
    prevBox.innerHTML = sel.length
      ? `<span class="mini-prev-lab">Получится:</span> ${effects(sel, lvl)}`
      : '<span class="mini-prev-lab">Выберите параметры — они должны быть разными</span>';
    buildBtn.disabled = !sel.length;
  }

  function redrawList(): void {
    const mine = list.filter(a => a.hero === heroIdx);
    countBox.textContent = mine.length ? String(mine.length) : '';
    if (!mine.length) { listBox.innerHTML = '<div class="mini-empty">Пока пусто: соберите первый артефакт.</div>'; return; }
    const taken = new Set(mine.map(a => a.wearer).filter(Boolean));
    listBox.innerHTML = mine.map(a => `
      <div class="mini-item" data-id="${a.id}">
        <div class="mini-item-fx">${effects(a.parts, a.level)}<span class="mini-lvl">умение ${a.level}</span></div>
        <div class="mini-item-act">
          <select aria-label="Одеть на">
            <option value="">— одеть на —</option>
            ${units.map(u => `<option value="${esc(u.sys)}" ${a.wearer === u.sys ? 'selected' : ''}
              ${taken.has(u.sys) && a.wearer !== u.sys ? 'disabled' : ''}>${esc(u.name)}</option>`).join('')}
          </select>
          <button type="button" class="mini-del">Разобрать</button>
        </div>
      </div>`).join('');
    listBox.querySelectorAll<HTMLElement>('.mini-item').forEach(el => {
      const a = list.find(x => x.id === Number(el.dataset.id));
      if (!a) return;
      el.querySelector('select')!.addEventListener('change', ev => {
        a.wearer = (ev.target as HTMLSelectElement).value; save(); redrawList();
      });
      el.querySelector('.mini-del')!.addEventListener('click', () => {
        list = list.filter(x => x !== a); save(); redrawList();
      });
    });
  }

  buildBtn.addEventListener('click', () => {
    if (!sel.length) return;
    list.push({ id: Date.now(), parts: sel.slice().sort((a, b) => a - b), level: heroSkill(), wearer: '', hero: heroIdx });
    sel = []; save(); redrawPick(); redrawList();
  });
  // Умение и уровень живут в других вкладках: подхватываем изменения при возврате к конструктору.
  box.addEventListener('pointerenter', redrawPick);
  redrawPick(); redrawList();
}

/** «Выбор заклятых врагов» эльфа: по одному отряду-врагу на каждый класс остальных игровых
 * фракций (у фракций с двумя-тремя классами строк по числу классов — как в оригинале).
 * Слева суть умения и шанс двойного урона, справа выбор; у героев 1 и 2 свои наборы. */
/** Призыв укротителя: слева существа по школам магии, справа калькулятор численности.
 * Формула — как в бою (battle/hero_skills.summon_count): база[боевой уровень] ·
 * (1 + 5%·умение) · 0,9^(прежних призывов). Таблицы приходят с сервера. */
function renderSummonCalc(box: HTMLElement, d: SummonData): void {
  const units = (allData as any).units || {};
  const sysList = Object.keys(d.creatures);                       // summoncreature1…8: пара на школу
  const portrait = (sys: string) => {
    const u = units[d.creatures[sys]] || {};
    const anim = u.animUnit || u.anim_unit || '';
    return staticsIconUrl(anim) || (anim ? `/images/portraits/${anim}p60.png` : '');
  };
  const nameOf = (sys: string) => units[d.creatures[sys]]?.nameRu || d.creatures[sys];
  const minLevel = (sys: string) => Math.min(...Object.keys(d.base[d.family[sys]]).map(Number));
  const pairSys = (sys: string) => sysList[Math.floor(sysList.indexOf(sys) / 2) * 2];   // обычная версия пары: считаются одинаково
  const cell = (sys: string) => `<button type="button" class="sm-unit" data-sys="${pairSys(sys)}" title="Рассчитать">
      <img class="sm-ico" alt="" src="${portrait(sys)}" loading="lazy" onerror="this.style.visibility='hidden'">
      <span class="sm-name">${escHtml(nameOf(sys))}</span></button>`;
  const rows = [0, 1, 2, 3].map(i => `<tr><th>${i + 1}</th><td>${cell(sysList[i * 2])}</td><td>${cell(sysList[i * 2 + 1])}</td><td class="sm-lv">с ${minLevel(sysList[i * 2])}-го</td></tr>`).join('');
  box.innerHTML = `
    <div class="mini-left">
      <div class="mini-title">Призываемые существа</div>
      <div class="mini-sub">Школа магии открывает вид существа; с «Повелителем существ» призывается улучшенное</div>
      <table class="mini-table sm-table"><thead><tr><th>Школа<br>магии</th><th>Обычные</th><th>Улучшенные</th><th>Боевой<br>уровень</th></tr></thead><tbody>${rows}</tbody></table>
      <ul class="mini-rules">
        <li>Одновременно под контролем только один призванный отряд.</li>
        <li>Каждый следующий призыв слабее на ${Math.round((1 - d.decay) * 100)}%.</li>
        <li>Цена призыва — ${d.mana} маны.</li>
      </ul>
    </div>
    <div class="mini-right">
      <div class="mini-title">Калькулятор призыва</div>
      <div class="sm-form">
        <label>Существо<select id="sm-sys">${[0, 1, 2, 3].map(i => `<option value="${sysList[i * 2]}">${escHtml(nameOf(sysList[i * 2]))} / ${escHtml(nameOf(sysList[i * 2 + 1]))}</option>`).join('')}</select></label>
        <label>Боевой уровень героя<input id="sm-lvl" type="number" min="1" max="25" step="1"></label>
        <label>Умение фракции<input id="sm-skill" type="number" min="0" max="14" step="1"></label>
      </div>
      <div class="sm-result" id="sm-result"></div>
      <div class="sm-seq" id="sm-seq"></div>
    </div>`;
  const q = <T extends HTMLElement>(id: string) => box.querySelector('#' + id) as T;
  const sel = q<HTMLSelectElement>('sm-sys'), lvl = q<HTMLInputElement>('sm-lvl'), skill = q<HTMLInputElement>('sm-skill');
  const KEY = 'summon-calc-v1';
  let saved: { sys?: string; lvl?: number; skill?: number } = {};
  try { saved = JSON.parse(localStorage.getItem(KEY) || '{}'); } catch { saved = {}; }
  sel.value = saved.sys && d.creatures[saved.sys] ? pairSys(saved.sys) : sysList[0];
  lvl.value = String(saved.lvl ?? DEFAULT_HERO_LEVEL);
  skill.value = String(saved.skill ?? DEFAULT_FACTION_LEVEL);
  const count = (sys: string, level: number, sk: number, n: number): number | null => {
    const tbl = d.base[d.family[sys]];
    const keys = Object.keys(tbl).map(Number);
    if (level < Math.min(...keys)) return null;
    const base = tbl[String(Math.min(level, Math.max(...keys)))];
    return Math.max(1, Math.round(base * (1 + d.skillPct / 100 * sk) * Math.pow(d.decay, n)));
  };
  const redraw = () => {
    const sys = sel.value;
    const level = Math.max(1, Math.min(25, Math.trunc(+lvl.value) || 1));
    const sk = Math.max(0, Math.min(MAX_FACTION_LEVEL, Math.trunc(+skill.value) || 0));
    try { localStorage.setItem(KEY, JSON.stringify({ sys, lvl: level, skill: sk })); } catch { /* без памяти — не страшно */ }
    box.querySelectorAll<HTMLElement>('.sm-unit').forEach(b => b.classList.toggle('on', b.dataset.sys === sys));
    const first = count(sys, level, sk, 0);
    q('sm-result').innerHTML = first === null
      ? `<div class="sm-none">Призыв доступен с ${minLevel(sys)}-го боевого уровня</div>`
      : `<img class="sm-big" alt="" src="${portrait(sys)}" onerror="this.style.visibility='hidden'">
         <div><div class="sm-num">${first}</div><div class="sm-cap">${escHtml(nameOf(sys))} и улучшенные — первый призыв</div></div>`;
    q('sm-seq').innerHTML = first === null ? '' :
      '<div class="sm-seq-title">Следующие призывы</div><div class="sm-chips">' +
      [1, 2, 3, 4, 5].map(n => `<span class="mini-chip">${n + 1}-й <b>${count(sys, level, sk, n)}</b></span>`).join('') + '</div>';
  };
  box.querySelectorAll<HTMLElement>('.sm-unit').forEach(b => b.addEventListener('click', () => { sel.value = b.dataset.sys || sel.value; redraw(); }));
  sel.addEventListener('change', redraw);
  lvl.addEventListener('input', redraw);
  skill.addEventListener('input', redraw);
  redraw();
}

function renderFavoredEnemies(box: HTMLElement): void {
  const factions = (allData as any).factions || {};
  interface FavRow { key: string; faction: string; cls: string; icon: string; options: { tier: number; label: string }[]; }
  const nameOf = (sys: string) => (allData as any).units?.[sys]?.nameRu || sys;
  const rows: FavRow[] = [];
  // Порядок: у фракций с двумя классами основной и альтернативный встают в один ряд двух столбцов
  // (рыцарь — рыцарь света, некромант — повелитель смерти…); варвары с тремя классами уходят вниз
  // к фараону, чтобы остальные пары не сдвигались.
  const FAV_ORDER = ['knight', 'necromance', 'magi', 'telf', 'demon', 'dwarf', 'stepbarbarian', 'barbarian', 'faraon'];
  const favFactions = [...FAV_ORDER.filter(f => PLAYABLE.includes(f)), ...PLAYABLE.filter(f => !FAV_ORDER.includes(f))];
  for (const fk of favFactions) {
    if (fk === 'elf') continue;                        // отряды эльфов заклятыми врагами не бывают
    const fd = factions[fk];
    if (!fd) continue;
    const options: { tier: number; label: string }[] = [];
    for (const tier of Object.keys(fd.unitsTable || {}).sort((a, b) => +a - +b)) {
      // Линия — базовое существо, улучшение и альтернативное улучшение: все идут в заклятые враги.
      const names = [...new Set(lineUnits(fd.unitsTable[tier]).map(nameOf))];
      if (names.length) options.push({ tier: +tier, label: names.join(' / ') });
    }
    for (const c of fd.classes || []) {
      rows.push({ key: `${fk}:${c.nameRu}`, faction: fk, cls: c.nameRu || '', icon: c.icon || fd.icon || '', options });
    }
  }
  const esc = (x: string) => x.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
  const KEY = FAV_STORE_KEY, HKEY = 'fav-hero-v1';
  let heroIdx = 0;
  try { heroIdx = localStorage.getItem(HKEY) === '1' ? 1 : 0; } catch { heroIdx = 0; }
  let store: Record<string, Record<string, number>> = {};
  try { store = JSON.parse(localStorage.getItem(KEY) || '{}'); } catch { store = {}; }
  const save = () => { try { localStorage.setItem(KEY, JSON.stringify(store)); } catch { /* без хранилища выбор живёт до перезагрузки */ } };
  const mine = () => (store[String(heroIdx)] ||= {});
  const heroSkill = () => Math.max(0, Math.min(MAX_FACTION_LEVEL,
    parseInt((document.getElementById(heroIdx ? 'tac-hero2-flvl' : 'tac-hero-flvl') as HTMLInputElement | null)?.value || '') || DEFAULT_FACTION_LEVEL));

  // Один блок: заголовок с плашками и переключателем героя, под ним список в два столбца.
  // Правила умения уже в описании выше, здесь их не повторяем.
  box.innerHTML = `
    <div class="fav-card">
      <div class="mini-head">
        <div class="mini-title">Выбор заклятых врагов</div>
        <div class="mini-heroes" id="fav-heroes" role="group" aria-label="Герой"></div>
      </div>
      <div class="mini-ctx" id="fav-ctx"></div>
      <div class="fav-rows" id="fav-rows"></div>
    </div>`;
  const q = <T extends HTMLElement>(id: string) => box.querySelector('#' + id) as T;
  const ctx = q('fav-ctx'), heroesBox = q('fav-heroes'), rowsBox = q('fav-rows');

  function redraw(): void {
    const lvl = heroSkill();
    const chance = elfCritChance(lvl);
    const sel = mine();
    ctx.innerHTML = `<span class="mini-chip">Умение фракции <b>${lvl}</b></span>
      <span class="mini-chip mini-chip-cap">Шанс двойного урона: <b>${chance}%</b></span>
      <span class="mini-chip">Выбрано <b>${rows.filter(r => sel[r.key]).length}</b> из ${rows.length}</span>
      <span class="mini-ctx-note">Умение берётся у выбранного героя — поле «Ур. фракции» во вкладке «Бой»</span>`;
    heroesBox.innerHTML = [0, 1].map(i =>
      `<button type="button" class="mini-hero ${i === heroIdx ? 'on' : ''}" data-h="${i}" aria-pressed="${i === heroIdx}">Герой ${i + 1}<span class="mini-hero-name">${esc(fittingHeroName(i) || '')}</span></button>`).join('');
    heroesBox.querySelectorAll<HTMLElement>('.mini-hero').forEach(b => b.addEventListener('click', () => {
      heroIdx = Number(b.dataset.h) === 1 ? 1 : 0;
      try { localStorage.setItem(HKEY, String(heroIdx)); } catch { /* выбор живёт до перезагрузки */ }
      redraw();
    }));
    rowsBox.innerHTML = rows.map(r => `
      <label class="fav-row ${sel[r.key] ? 'set' : ''}" title="${esc(r.cls)}">
        <img class="fav-ico" alt="" src="/api/img?url=${encodeURIComponent(r.icon)}">
        <select data-k="${esc(r.key)}">
          <option value="">— не выбран —</option>
          ${r.options.map(o => `<option value="${o.tier}" ${sel[r.key] === o.tier ? 'selected' : ''}>${esc(o.label)}</option>`).join('')}
        </select>
      </label>`).join('');
    rowsBox.querySelectorAll<HTMLSelectElement>('select').forEach(sl => sl.addEventListener('change', () => {
      const m = mine();
      if (sl.value) m[sl.dataset.k as string] = Number(sl.value); else delete m[sl.dataset.k as string];
      save(); redraw();
    }));
  }
  box.addEventListener('pointerenter', redraw);   // умение героя меняется в другой вкладке
  redraw();
}


/** «Как работает в нашем бою» под умением класса: статус, суть и где в коде.
 * Таблица — battle/class_abilities.py; без локального сервера блок просто не появляется. */
async function fillClassEngine(section: HTMLElement, factionKey: string): Promise<void> {
  try {
    if (!classAbilityRows) {
      const res = await fetch('/api/class-abilities');
      if (!res.ok) return;
      const body = (await res.json()) as { classes: ClassAbilityRow[]; miniArtifacts?: MiniArtifacts; summon?: SummonData };
      classAbilityRows = body.classes;
      miniArtifactsData = body.miniArtifacts || null;
      summonData = body.summon || null;
    }
  } catch { return; }
  const mini = section.querySelector<HTMLElement>('#mini-art');
  if (mini && miniArtifactsData) renderMiniArtifacts(mini, miniArtifactsData);
  const summon = section.querySelector<HTMLElement>('#summon-calc');
  if (summon && summonData) renderSummonCalc(summon, summonData);
  section.querySelectorAll<HTMLElement>('.faction-class-engine').forEach(box => {
    const row = classAbilityRows!.find(r => r.faction === factionKey && r.classRu === box.dataset.className);
    if (!row) return;
    // Блок скрыт, пока не нажали «как работает в бою» под описанием умения.
    const item = box.closest('.faction-class-item') as HTMLElement | null;
    const desc = item?.querySelector('.faction-skill-desc') as HTMLElement | null;
    if (item && desc && !desc.querySelector('.fce-hint')) {
      desc.insertAdjacentHTML('beforeend',
        '<button type="button" class="fce-hint" aria-expanded="false">как работает в бою <span class="fce-arrow">▸</span></button>');
      const hint = desc.querySelector('.fce-hint') as HTMLButtonElement;
      hint.addEventListener('click', () => {
        const open = item.classList.toggle('fce-open');
        hint.setAttribute('aria-expanded', String(open));
      });
    }
    box.innerHTML =
      '<div class="fce-head"><span class="fce-lab">В нашем бою</span>' +
      '<span class="fce-chip fce-' + escHtml(row.status) + '">' + escHtml(row.statusRu) + '</span></div>' +
      '<div class="fce-sum">' + escHtml(row.summary) + '</div>' +
      (row.refs.length
        ? '<details class="fce-refs"><summary>Где в коде (' + row.refs.length + ')</summary><ul>' +
          row.refs.map(r => '<li><span class="fce-file">' + escHtml(r.file) + '</span> <code>' +
            escHtml(r.symbol) + '</code> — ' + escHtml(r.what) + '</li>').join('') + '</ul></details>'
        : '');
  });
}

